import { Book } from "@/lib/types";

export const _2kings: Book = {
  id: "2kings",
  name: "2. Könige",
  shortName: "2.Kön",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Und Moab brach mit Israel, nachdem Ahab tot war*. —", heading: "Ahasja von Israel — Sein Götzendienst, Elias Gerichtsandrohung, Ahasjas Tod", footnotes: ["℘ Kap. 3,5; 2Sam 8,2"] },
      { number: 2, text: "Und Ahasja* fiel in seinem Obergemach in Samaria durch das Gitter und wurde krank. Und er sandte Boten und sagte zu ihnen: Geht hin, befragt Baal-Sebub*, den Gott von Ekron*, ob ich von dieser Krankheit genesen werde*!", footnotes: ["℘ 1Kö 22,40.52", "℘ Kap. 17,16; 1Kö 22,54; Jes 19,3", "℘ Jos 15,11", "℘ Kap. 8,8.9"] },
      { number: 3, text: "Da redete der Engel des HERRN zu Elia, dem Tischbiter*: Mache dich auf, geh hinauf, den Boten des Königs von Samaria entgegen, und sage zu ihnen: Gibt es denn keinen Gott in Israel, dass ihr hingeht, um Baal-Sebub, den Gott von Ekron, zu befragen?*", footnotes: ["℘ 1Kö 17,1", "℘ 1Kö 11,33; Jes 8,19; Jer 2,11-13"] },
      { number: 4, text: "Darum, so spricht der HERR: Von dem Bett, das du bestiegen hast, wirst du nicht herunterkommen, sondern du musst sterben*! Und Elia ging hin*.", footnotes: ["℘ Kap. 8,10; 20,1; Spr 11,19", "℘ 1Kö 18,2"] },
      { number: 5, text: "Als nun die Boten zum König* zurückkamen, sagte er zu ihnen: Warum seid ihr denn <schon> zurückgekehrt?", footnotes: ["w. zu ihm"] },
      { number: 6, text: "Sie sagten zu ihm: Ein Mann kam herauf, uns entgegen, und sagte zu uns: Geht, kehrt zum König zurück, der euch gesandt hat, und redet zu ihm: So spricht der HERR: Gibt es denn keinen Gott in Israel, dass du hinsendest, um Baal-Sebub, den Gott von Ekron, zu befragen? Darum wirst du von dem Bett, das du bestiegen hast, nicht herunterkommen, sondern du musst sterben." },
      { number: 7, text: "Da sagte er zu ihnen: Wie war das Aussehen des Mannes*, der euch entgegenkam und diese Worte zu euch redete?", footnotes: ["w. Wie war die Art des Mannes"] },
      { number: 8, text: "Sie sagten zu ihm: Es war ein Mann, mit einem haarigen Mantel* bekleidet* und an seinen Hüften gegürtet mit einem ledernen Schurz*. Da sagte er: Das ist Elia, der Tischbiter!", footnotes: ["℘ Sach 13,4", "o. ein Mann mit langem Haar; w. ein Mann, ein Besitzer von Haar", "℘ 1Kö 18,46; Mt 3,4"] },
      { number: 9, text: "Und er sandte zu ihm einen Obersten über fünfzig <Mann> und seine fünfzig <Leute>. Der ging zu ihm hinauf, und siehe, er saß auf dem Gipfel des Berges*. Und er sagte zu ihm: Mann Gottes*, der König sagt: Komm herab!", footnotes: ["℘ Kap. 2,25; 4,25", "℘ 1Kö 17,18.24"] },
      { number: 10, text: "Elia aber antwortete und redete zu dem Obersten über fünfzig <Mann>: Wenn ich ein Mann Gottes bin, so fahre Feuer vom Himmel herab* und fresse dich und deine fünfzig <Mann>*! Da fuhr Feuer vom Himmel herab und fraß ihn und seine fünfzig <Mann>.", footnotes: ["℘ Hi 1,16", "℘ 3Mo 10,2; Lk 9,54; Offb 11,5; 20,9"] },
      { number: 11, text: "Und er sandte nochmals zu ihm, einen anderen Obersten über fünfzig <Mann> mit seinen fünfzig <Leuten>. Der stieg hinauf* und sagte zu ihm: Mann Gottes, so spricht der König: Schnell, komm herunter!", footnotes: ["so mit LXX und Vulg.; Mas. T.: Der antwortete, o. Der fing an"] },
      { number: 12, text: "Aber Elia antwortete und redete zu ihnen: Wenn ich ein Mann Gottes bin, so fahre Feuer vom Himmel herab* und fresse dich und deine fünfzig <Mann>! Da fuhr Feuer Gottes vom Himmel herab und fraß ihn und seine fünfzig <Mann>*.", footnotes: ["℘ 3Mo 10,2; Lk 9,54; Offb 11,5; 20,9", "℘ 3Mo 10,2; Lk 9,54; Offb 11,5; 20,9"] },
      { number: 13, text: "Und er sandte nochmals hin, einen dritten Obersten über fünfzig <Mann>* und seine fünfzig <Leute>. Und der dritte Oberste über fünfzig <Mann>* ging hinauf und kam und beugte seine Knie vor Elia, flehte ihn an* und redete zu ihm: Mann Gottes! Lass doch mein Leben und das Leben deiner Knechte, dieser fünfzig <Mann>, teuer sein in deinen Augen*!", footnotes: ["w. einen Obersten über dritte Fünfzig", "w. der Oberste über die dritten Fünfzig", "℘ Jak 4,10", "℘ 1Sam 26,21"] },
      { number: 14, text: "Siehe, Feuer ist vom Himmel herabgefahren und hat die beiden vorigen Obersten über fünfzig <Mann> und ihre fünfzig <Leute> gefressen. Nun aber lass mein Leben teuer sein in deinen Augen*!", footnotes: ["℘ 1Sam 26,21"] },
      { number: 15, text: "Da redete der Engel des HERRN zu Elia: Geh mit ihm hinab, fürchte dich nicht vor ihm*! Und er stand auf und ging mit ihm zum König hinab.", footnotes: ["℘ 1Mo 15,1"] },
      { number: 16, text: "Und er redete zu ihm: So spricht der HERR: Weil du Boten gesandt hast, um Baal-Sebub*, den Gott von Ekron, zu befragen — gibt es denn keinen Gott in Israel, um sein Wort zu befragen? —, darum wirst du von dem Bett, das du bestiegen hast, nicht herunterkommen; sondern du musst sterben*!", footnotes: ["℘ Kap. 8,10; 20,1; Spr 11,19", "℘ Kap. 8,10; 20,1; Spr 11,19"] },
      { number: 17, text: "Und er starb nach dem Wort des HERRN*, das Elia geredet hatte*. Und Joram* wurde an seiner Stelle König im zweiten Jahr Jorams, des Sohnes Joschafats, des Königs von Juda*; denn er hatte keinen Sohn.", footnotes: ["℘ 5Mo 34,5", "℘ Kap. 9,36; 10,17; 1Kö 17,16", "d. i. der Bruder Ahasjas", "℘ Kap. 3,1; 8,16; 2Chr 17,1"] },
      { number: 18, text: "Und die übrige Geschichte* Ahasjas, was er getan hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Israel?*", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ Kap. 10,34; 13,8.12; 14,15.28; 15,11.15.21.26.31; 1Kö 14,19"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Und es geschah, als der HERR den Elia im Sturmwind zum Himmel auffahren lassen wollte*, da gingen Elia und Elisa* von Gilgal* fort.", heading: "Elia und Elisa — Elias Himmelfahrt", footnotes: ["℘ V. 11", "℘ 1Kö 19,16.19", "℘ Kap. 4,38; Jos 4,19"] },
      { number: 2, text: "Und Elia sagte zu Elisa: Bleib doch hier! Denn der HERR hat mich nach Bethel* gesandt. Elisa aber sagte: So wahr der HERR lebt und deine Seele lebt*, wenn ich dich verlasse*! Und sie gingen nach Bethel hinab.", footnotes: ["℘ V. 23; 1Mo 28,19", "℘ Kap. 4,30; Rt 1,16; 1Sam 1,26", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde."] },
      { number: 3, text: "Da kamen die Söhne der Propheten*, die in Bethel waren, zu Elisa heraus und sagten zu ihm: Hast du erkannt, dass der HERR heute deinen Herrn über deinen Kopf hin wegnehmen wird? Er sagte: Auch ich habe es erkannt. Seid still!", footnotes: ["Das sind Prophetenjünger o. Schüler der Propheten\n℘ Kap. 4,1.38; 5,22; 6,1; 9,1; 1Sam 10,5; 1Kö 20,35; Am 7,14"] },
      { number: 4, text: "Und Elia sagte zu ihm: Elisa, bleib doch hier! Denn der HERR hat mich nach Jericho* gesandt. Er aber sagte: So wahr der HERR lebt und deine Seele lebt*, wenn ich dich verlasse*! Und sie kamen nach Jericho.", footnotes: ["℘ Jos 6,1", "℘ Kap. 4,30; Rt 1,16; 1Sam 1,26", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde."] },
      { number: 5, text: "Da traten die Söhne der Propheten*, die in Jericho waren, zu Elisa und sagten zu ihm: Hast du erkannt, dass der HERR heute deinen Herrn über deinen Kopf hin wegnehmen wird? Er sagte: Auch ich habe es erkannt. Seid still!", footnotes: ["Das sind Prophetenjünger o. Schüler der Propheten\n℘ Kap. 4,1.38; 5,22; 6,1; 9,1; 1Sam 10,5; 1Kö 20,35; Am 7,14"] },
      { number: 6, text: "Und Elia sagte zu ihm: Bleib doch hier! Denn der HERR hat mich an den Jordan gesandt. Er aber sagte: So wahr der HERR lebt und deine Seele lebt*, wenn ich dich verlasse*! Und so gingen sie beide miteinander*.", footnotes: ["℘ Kap. 4,30; Rt 1,16; 1Sam 1,26", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.", "℘ 1Mo 22,6.8"] },
      { number: 7, text: "Und fünfzig Mann von den Söhnen der Propheten* gingen mit und blieben abseits stehen, als die beiden an den Jordan traten.", footnotes: ["Das sind Prophetenjünger o. Schüler der Propheten\n℘ Kap. 4,1.38; 5,22; 6,1; 9,1; 1Sam 10,5; 1Kö 20,35; Am 7,14"] },
      { number: 8, text: "Da nahm Elia seinen Mantel* und wickelte <ihn> zusammen und schlug auf das Wasser. Und es teilte sich hierhin und dorthin, und die beiden gingen hinüber auf dem Trockenen*.", footnotes: ["℘ 1Sam 28,14; 1Kö 19,19", "℘ 2Mo 14,22"] },
      { number: 9, text: "Und es geschah, als sie hinübergegangen waren, da sagte Elia zu Elisa: Bitte, was ich für dich tun soll, bevor ich von dir weggenommen werde! Elisa sagte: Dass mir doch ein zweifacher Anteil von deinem Geist* <gegeben> werde!", footnotes: ["d. h. wohl: der Anteil des Erstgeborenen; andere üs.: zwei Drittel von deinem Geist"] },
      { number: 10, text: "Da sagte er: Du hast Schweres erbeten! Wenn du mich sehen wirst, wie ich von dir weggenommen werde, dann wird dir das <gegeben> werden; wenn aber nicht, dann wird es <dir> nicht <gegeben> werden." },
      { number: 11, text: "Und es geschah, während sie gingen, gingen und redeten, siehe da: ein feuriger Wagen und feurige Pferde*, die sie beide voneinander trennten! Und Elia fuhr im Sturmwind* auf zum Himmel*.", footnotes: ["℘ Kap. 6,17; Ps 104,4", "℘ Hes 1,4", "℘ V. 1; Mk 16,19; Lk 9,30; Offb 4,1; 11,12"] },
      { number: 12, text: "Und Elisa sah es und schrie: Mein Vater, mein Vater!* Wagen Israels und sein Gespann*! Dann sah er ihn nicht mehr*. Da fasste er seine Kleider und zerriss sie in zwei Stücke.", footnotes: ["℘ Kap. 5,13; Ri 17,10", "℘ Kap. 13,14", "℘ 1Mo 5,24; Apg 8,39"] },
      { number: 13, text: "Und er hob den Mantel* des Elia auf, der diesem entfallen war, kehrte um und trat an das Ufer des Jordan.", footnotes: ["℘ 1Sam 28,14; 1Kö 19,19"] },
      { number: 14, text: "Und er nahm den Mantel des Elia, der diesem entfallen war, und schlug auf das Wasser und sagte: Wo ist der HERR*, der Gott des Elia? Auch er schlug also auf das Wasser, und es teilte sich hierhin und dorthin, und Elisa ging hinüber.*", footnotes: ["℘ Jer 2,6.8", "℘ 2Mo 14,22"] },
      { number: 15, text: "Als nun die Söhne der Propheten*, die gegenüber in Jericho waren, ihn sahen, sagten sie: Der Geist des Elia ruht auf Elisa*! Und sie kamen ihm entgegen und warfen sich vor ihm zur Erde nieder*.", footnotes: ["Das sind Prophetenjünger o. Schüler der Propheten\n℘ Kap. 4,1.38; 5,22; 6,1; 9,1; 1Sam 10,5; 1Kö 20,35; Am 7,14", "℘ 4Mo 11,25; Lk 1,17", "℘ Jos 4,14"] },
      { number: 16, text: "Und sie sagten zu ihm: Sieh doch, es sind bei deinen Knechten fünfzig tüchtige Männer*. Lass sie doch gehen und deinen Herrn suchen, ob nicht etwa der Geist des HERRN ihn weggetragen und ihn auf einen der Berge oder in eines der Täler geworfen hat*! Er aber sagte: Sendet nicht!", footnotes: ["w. fünfzig Männer, Söhne der Kraft", "℘ 1Kö 18,12"] },
      { number: 17, text: "Doch sie drangen in ihn, bis er nachgab* und sagte: Sendet! So sandten sie denn fünfzig Mann hin; die suchten drei Tage lang, aber sie fanden ihn nicht.", footnotes: ["w. bis zum Sich-Schämen, o. bis zum Zuschandenwerden"] },
      { number: 18, text: "Und sie kehrten zu ihm zurück, als er sich <noch> in Jericho aufhielt. Da sagte er zu ihnen: Hatte ich euch nicht gesagt: Geht nicht hin?" },
      { number: 19, text: "Und die Männer der Stadt sagten zu Elisa: Sieh doch, die Lage der Stadt ist gut, wie mein Herr sieht. Aber das Wasser ist schlecht, darum kommt es im Land zu Fehlgeburten*.", heading: "Wundertaten des Elisa: Hilfe in Jericho, Gericht in Bethel", footnotes: ["w. und das Land bringt Fehlgeburten"] },
      { number: 20, text: "Da sagte er: Bringt mir eine neue Schale und tut Salz hinein! Und sie brachten sie ihm." },
      { number: 21, text: "Und er ging hinaus zu der Quelle des Wassers, warf das Salz hinein und sagte: So spricht der HERR: Ich habe dieses Wasser gesund gemacht. Nicht mehr soll Tod und Fehlgeburt daraus entstehen*.", footnotes: ["℘ Kap. 4,41; 2Mo 15,25"] },
      { number: 22, text: "Und das Wasser wurde gesund bis auf diesen Tag nach dem Wort, das Elisa geredet hatte." },
      { number: 23, text: "Und er ging von dort hinauf nach Bethel*. Wie er nun den Weg hinaufging, kamen kleine Jungen aus der Stadt heraus und verspotteten ihn* und sagten zu ihm: Komm herauf, Kahlkopf! Komm herauf, Kahlkopf!", footnotes: ["℘ V. 2", "℘ 2Chr 36,16; Hi 19,18; Jer 20,7.8"] },
      { number: 24, text: "Er aber wandte sich um, sah sie an und verfluchte sie im Namen des HERRN*. Da kamen zwei Bärinnen aus dem Wald und zerrissen von ihnen 42 Kinder*.", footnotes: ["℘ Spr 19,29", "℘ 3Mo 26,22"] },
      { number: 25, text: "Und er ging von dort <weg> zum Berg Karmel*; und von da kehrte er nach Samaria zurück.", footnotes: ["℘ Kap. 1,9; Jos 19,26"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Und Joram, der Sohn Ahabs, wurde König über Israel* in Samaria, im achtzehnten Jahr Joschafats, des Königs von Juda*; und er regierte zwölf Jahre.", heading: "Joram von Israel — Krieg gegen die Moabiter — Hilfe durch Elisa", footnotes: ["℘ 2Chr 22,5", "℘ Kap. 1,17"] },
      { number: 2, text: "Und er tat, was böse war in den Augen des HERRN, doch nicht wie sein Vater und seine Mutter, weil er den Gedenkstein* des Baal beseitigte, den sein Vater gemacht hatte*.", footnotes: ["hebr. mazzeba; d. i. ein aufrecht hingestellter Stein, der zu Ehren eines Gottes kultisch verehrt wurde", "℘ Kap. 10,26.27; 1Kö 16,31.32"] },
      { number: 3, text: "Doch hielt er fest an den Sünden Jerobeams, des Sohnes Nebats, der Israel zur Sünde verführt hatte*; er wich von ihr nicht ab.", footnotes: ["℘ Kap. 10,29.31; 13,2.6.11; 14,24; 15,9.18.24.28; 17,21; 21,16; 23,15; 1Kö 14,16"] },
      { number: 4, text: "Und Mescha, der König von Moab, war Schafzüchter und lieferte dem König von Israel 100 000 Lämmer und 100 000 ungeschorene Widder* <als Tribut>.", footnotes: ["℘ 2Sam 8,2; Jes 16,1"] },
      { number: 5, text: "Und es geschah, als Ahab gestorben war, da brach der König von Moab mit dem König von Israel*.", footnotes: ["℘ Kap. 1,1; 13,20"] },
      { number: 6, text: "Nun zog der König Joram in jener Zeit von Samaria aus und musterte ganz Israel." },
      { number: 7, text: "Und er ging hin und sandte zu Joschafat, dem König von Juda, und ließ <ihm> sagen: Der König von Moab hat mit mir gebrochen. Willst du mit mir gegen Moab in den Kampf ziehen? Er sagte: Ich will hinaufziehen; ich bin wie du, mein Volk wie dein Volk, meine Pferde wie deine Pferde*.", footnotes: ["℘ 1Kö 22,4"] },
      { number: 8, text: "Und er sagte: Welchen Weg wollen wir hinaufziehen? Er sagte: Den Weg <durch die> Wüste Edom." },
      { number: 9, text: "So zogen der König von Israel und der König von Juda und der König von Edom* aus. Als sie nun einen Umweg von sieben Tagereisen gemacht hatten, gab es kein Wasser <mehr> für das Heer und für das Vieh, das in ihrem Gefolge war.", footnotes: ["℘ 1Kö 22,48"] },
      { number: 10, text: "Da sagte der König von Israel: Wehe! Der HERR hat diese drei Könige gerufen, um sie in die Hand Moabs zu geben*!", footnotes: ["℘ Kap. 6,33"] },
      { number: 11, text: "Joschafat aber sagte: Ist hier kein Prophet des HERRN, dass wir den HERRN durch ihn befragen können*? Da antwortete einer von den Dienern des Königs von Israel und sagte: Elisa ist hier, der Sohn des Schafat, der Wasser über Elias Hände goss*.", footnotes: ["℘ 1Kö 22,7; 2Chr 18,6", "℘ 1Kö 19,21"] },
      { number: 12, text: "Und Joschafat sagte: Das Wort des HERRN ist bei ihm. Da gingen der König von Israel und Joschafat und der König von Edom zu ihm hinab." },
      { number: 13, text: "Und Elisa sagte zum König von Israel: Was habe ich mit dir <zu tun>*? Geh zu den Propheten deines Vaters und zu den Propheten deiner Mutter*! Der König von Israel aber sagte zu ihm: Nein! Hat doch der HERR diese drei Könige gerufen, um sie in die Hand Moabs zu geben!", footnotes: ["℘ Hes 14,3; Mt 8,29", "℘ Ri 10,14; 1Kö 18,19"] },
      { number: 14, text: "Da sagte Elisa: So wahr der HERR der Heerscharen lebt, vor dem ich stehe*, fürwahr, wenn ich nicht auf Joschafat, den König von Juda, Rücksicht nähme*, so würde ich dich weder anblicken noch beachten*!", footnotes: ["℘ Kap. 5,16; 1Kö 17,1", "w. wenn ich nicht das Gesicht Joschafats, des Königs von Juda, erhöbe", "w. noch dich ansehen"] },
      { number: 15, text: "Und nun holt mir einen Saitenspieler*. Und es geschah, als der Saitenspieler spielte, da kam die Hand des HERRN über ihn*.", footnotes: ["℘ 1Sam 10,5; 16,23", "℘ 1Kö 18,46"] },
      { number: 16, text: "Und er sagte: So spricht der HERR: Macht in diesem Tal Grube an Grube!" },
      { number: 17, text: "Denn so spricht der HERR: Ihr werdet keinen Wind sehen und keinen Regen sehen, und doch wird sich dieses Tal mit Wasser füllen, so dass ihr trinken könnt, ihr und eure Herden und euer Vieh." },
      { number: 18, text: "Und das ist <noch> zu gering in den Augen des HERRN*, er wird auch Moab in eure Hand geben*.", footnotes: ["℘ 2Sam 7,19", "℘ 1Kö 20,13"] },
      { number: 19, text: "Und ihr werdet jede befestigte Stadt und jede auserlesene Stadt schlagen und werdet alle guten Bäume fällen und alle Wasserquellen verstopfen und jedes gute <Feld>stück mit Steinen verderben*.", footnotes: ["℘ 5Mo 20,19.20"] },
      { number: 20, text: "Und es geschah am Morgen, <zur Zeit,> da man das Speisopfer opfert*, siehe, da kam Wasser aus der Richtung von Edom her, und das Land füllte sich mit Wasser*.", footnotes: ["℘ 2Mo 29,39", "℘ Ps 107,35"] },
      { number: 21, text: "Und als alle Moabiter hörten, dass die Könige heraufgezogen waren, um gegen sie zu kämpfen, da wurden sie zusammengerufen, von jedem an, der das Schwert* umgürten konnte, und darüber; und sie stellten sich an der Grenze auf.", footnotes: ["w. den Gürtel"] },
      { number: 22, text: "Und als sie sich früh am Morgen aufmachten und die Sonne über dem Wasser aufging, da sahen die Moabiter das Wasser gegenüber rot wie Blut." },
      { number: 23, text: "Und sie sagten: Das ist Blut! Ganz sicher haben sich die Könige bekämpft und sich gegenseitig erschlagen. Nun auf zur Beute, Moab!" },
      { number: 24, text: "Als sie aber zum Lager Israels kamen, da erhob sich Israel, und sie schlugen die Moabiter, dass sie vor ihnen flohen. Israel aber drang ins Land ein* und schlug Moab <vernichtend>.", footnotes: ["w. Sie aber kamen in es hinein"] },
      { number: 25, text: "Und sie rissen die Städte nieder*, und auf alle guten <Felder>stücke warfen sie jeder seinen Stein und füllten sie damit an, und sie verstopften alle Wasserquellen und fällten alle guten Bäume*, bis nur noch die Steinmauer von Kir-Heres* standhielt*. Und die Schleuderer umzingelten <die Stadt> und beschossen sie.", footnotes: ["℘ Ri 9,45", "℘ 5Mo 20,19.20", "℘ Jes 16,7.11; Jer 48,31.36", "T.; Mas. T.: bis er von Kir-Heres ihre Steine übrig ließ"] },
      { number: 26, text: "Als aber der König von Moab sah, dass ihm der Kampf zu heftig war, nahm er 700 Mann mit sich, die das Schwert zogen, um gegen den König von Edom* durchzubrechen; aber es gelang ihnen nicht.", footnotes: ["Andere lesen mit Textänderung: zum König von Aram\n℘ Am 2,1"] },
      { number: 27, text: "Da nahm er seinen erstgeborenen Sohn, der an seiner Stelle König werden sollte, und opferte ihn als Brandopfer* auf der Mauer*. Da kam ein großer Zorn über Israel; und sie zogen von ihm ab und kehrten in <ihr> Land zurück.", footnotes: ["℘ 1Mo 22,2", "℘ 5Mo 12,31; Mi 6,7"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Und eine Frau von den Frauen der Prophetensöhne* schrie zu Elisa: Dein Knecht, mein Mann, ist gestorben, und du hast <doch> selbst erkannt, dass dein Knecht den HERRN fürchtete. Nun aber ist der Gläubiger gekommen, um meine beiden Söhne* für sich als Sklaven zu nehmen*.", heading: "Elisa und der Ölkrug der Witwe", footnotes: ["o. Prophetenschüler; o. Jünger der Propheten\n℘ V. 38; Kap. 2,3.5.7.15", "w. Jungen", "℘ 3Mo 25,39; Spr 22,7"] },
      { number: 2, text: "Da sagte Elisa zu ihr: Was soll ich für dich tun? Sag mir, was du im Haus hast!* Sie sagte: Deine Magd hat gar nichts im Haus als nur einen Krug Öl*.", footnotes: ["℘ 2Mo 4,2; Mk 6,38; 8,5", "o. eine Salbung Öl; d. h. so viel, wie ausreicht, um sich zu salben\n℘ 1Kö 17,12"] },
      { number: 3, text: "Da sagte er: Geh hin, erbitte dir Gefäße von draußen, von all deinen Nachbarinnen, leere Gefäße, <aber> nicht zu wenige*!", footnotes: ["℘ Ps 81,11"] },
      { number: 4, text: "Dann geh hinein und schließ die Tür hinter dir und hinter deinen Söhnen zu und gieß in all diese Gefäße; und was voll ist, stelle beiseite!" },
      { number: 5, text: "Und sie ging von ihm weg und schloss die Tür hinter sich und hinter ihren Söhnen zu. Während sie ihr <die Gefäße> reichten, goss sie ein." },
      { number: 6, text: "Und es geschah, als die Gefäße voll waren, da sagte sie zu ihrem Sohn: Reiche mir noch ein Gefäß! Er aber sagte zu ihr: Es ist kein Gefäß mehr da. Da kam das Öl zum Stillstand." },
      { number: 7, text: "Und sie kam und berichtete es dem Mann Gottes, und der sagte: Geh hin, verkaufe das Öl und bezahle deine Schulden! Du aber und deine Söhne<, ihr> könnt von dem restlichen <Öl> leben*.", footnotes: ["℘ Phil 4,19"] },
      { number: 8, text: "Und es geschah eines Tages, da ging Elisa nach Schunem* hinüber. Dort war eine wohlhabende Frau, die nötigte ihn, <bei ihr> zu essen. Und es geschah, sooft er durchzog, kehrte er dort ein, um zu essen*.", heading: "Elisa und der Sohn der Schunemiterin", footnotes: ["℘ Jos 19,18", "℘ Apg 16,15"] },
      { number: 9, text: "Und sie sagte zu ihrem Mann: Sieh doch, ich habe erkannt, dass es ein heiliger Mann Gottes ist*, der regelmäßig <hier> bei uns hindurchzieht.", footnotes: ["℘ 1Kö 17,24"] },
      { number: 10, text: "Lass uns doch ein kleines gemauertes Obergemach machen! Dort wollen wir ihm dann Bett und Tisch und Stuhl und Leuchter hinstellen. Und es soll geschehen, wenn er zu uns kommt, kann er dort einkehren." },
      { number: 11, text: "Und es geschah eines Tages, als er <wieder> dahin kam, kehrte er in das Obergemach ein und schlief dort." },
      { number: 12, text: "Und er sagte zu seinem Diener Gehasi*: Ruf diese Schunemiterin! Und er rief sie, und sie trat vor ihn hin.", footnotes: ["℘ Kap. 5,20; 8,4"] },
      { number: 13, text: "Und er sagte zu ihm: Sage doch zu ihr: Siehe, du hast dir unsertwegen alle diese Mühe gemacht. Was kann man für dich tun? Ist für dich mit dem König zu reden* oder mit dem Heerobersten? Sie aber sagte: Ich wohne mitten in meinem Volk.", footnotes: ["℘ Kap. 8,3"] },
      { number: 14, text: "Und er sagte: Was kann man denn <dann> für sie tun? Da sagte Gehasi: Ach, sie hat keinen Sohn, und ihr Mann ist alt." },
      { number: 15, text: "Und er sagte: Ruf sie! Und er rief sie, und sie trat in die Tür." },
      { number: 16, text: "Und er sprach: Um diese Zeit übers Jahr wirst du einen Sohn umarmen*. Da sagte sie: Nicht doch, mein Herr, du Mann Gottes*, belüge deine Magd nicht*!", footnotes: ["℘ 1Mo 18,10", "℘ 1Kö 17,24", "℘ 1Mo 18,12.14"] },
      { number: 17, text: "Aber die Frau wurde schwanger und gebar einen Sohn zu ebendieser Zeit übers Jahr*, wie Elisa zu ihr geredet hatte.", footnotes: ["℘ 1Mo 21,1; Mt 10,41"] },
      { number: 18, text: "Und das Kind wuchs heran. Und es geschah eines Tages, da ging es zu seinem Vater hinaus, zu den Schnittern." },
      { number: 19, text: "Und es sagte zu seinem Vater: Mein Kopf, mein Kopf! Er sagte zu dem Knecht: Trag ihn zu seiner Mutter!" },
      { number: 20, text: "Der hob ihn auf und brachte ihn zu seiner Mutter. Und er saß auf ihren Knien bis zum Mittag, dann starb er*.", footnotes: ["℘ 1Kö 17,17"] },
      { number: 21, text: "Da ging sie hinauf und legte ihn auf das Bett des Mannes Gottes, schloss hinter ihm zu und ging hinaus." },
      { number: 22, text: "Und sie rief ihren Mann und sagte: Schicke mir doch einen von den Knechten und eine von den Eselinnen! Und ich will zu dem Mann Gottes eilen und <bald> zurückkommen." },
      { number: 23, text: "Er sagte: Warum willst du <gerade> heute zu ihm gehen? Es ist weder Neumond noch Sabbat*. Sie sagte: Friede <mit dir>!", footnotes: ["℘ 4Mo 28,9-15; 1Sam 20,5.18.24; Jes 1,13"] },
      { number: 24, text: "Und sie sattelte die Eselin und sagte zu ihrem Diener: Treib <nur> immerfort an! Halte mich nicht beim Reiten auf, es sei denn, dass ich es dir sage!" },
      { number: 25, text: "So zog sie hin und kam zu dem Mann Gottes auf den Berg Karmel*. Und es geschah, als der Mann Gottes sie von ferne sah, sagte er zu seinem Diener Gehasi*: Siehe da, die Schunemiterin*!", footnotes: ["℘ Kap. 1,9", "℘ Kap. 5,20; 8,4", "w. Siehe, die da ist die Schunemiterin"] },
      { number: 26, text: "Nun lauf ihr doch entgegen und sage zu ihr: Geht es dir gut? Geht es deinem Mann gut?* Geht es dem Kind gut? Sie sagte: Gut!*", footnotes: ["℘ 1Mo 43,27", "w. Ist dir Friede? Ist Friede deinem Mann? Ist Friede deinem Kind? Sie sagte: Friede!"] },
      { number: 27, text: "Und sie kam zu dem Mann Gottes auf den Berg und umfasste seine Füße*. Da trat Gehasi herzu, um sie wegzustoßen. Aber der Mann Gottes sagte: Lass sie! Denn ihre Seele ist betrübt; und der HERR hat es mir verborgen und es mir nicht kundgetan*.", footnotes: ["℘ Mt 28,9", "℘ 1Mo 18,17"] },
      { number: 28, text: "Und sie sagte: Habe ich einen Sohn von meinem Herrn erbeten? Habe ich nicht gesagt: Täusche mich nicht?" },
      { number: 29, text: "Da sagte er zu Gehasi: Gürte deine Hüften* und nimm meinen Stab in deine Hand und geh hin! Wenn du jemandem begegnest, grüße* ihn nicht, und wenn jemand dich grüßt*, antworte ihm nicht!* Und lege meinen Stab auf das Gesicht des Jungen!", footnotes: ["℘ Kap. 9,1", "w. segne", "w. segnet", "℘ Lk 10,4"] },
      { number: 30, text: "Die Mutter des Jungen aber sagte: So wahr der HERR lebt und deine Seele lebt*, wenn ich von dir lasse*!* Da machte er sich auf und ging ihr nach*.", footnotes: ["℘ Kap. 2,2", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.", "℘ 1Mo 32,27", "℘ Kap. 6,3"] },
      { number: 31, text: "Gehasi aber war ihnen vorausgegangen und hatte den Stab auf das Gesicht des Jungen gelegt; aber da war kein Laut und kein Aufhorchen*. Und er kehrte um, ihm entgegen, und berichtete ihm und sagte: Der Junge ist nicht aufgewacht.", footnotes: ["℘ Mk 9,18"] },
      { number: 32, text: "Und als Elisa in das Haus kam, siehe, da war der Junge tot, auf sein Bett hingelegt." },
      { number: 33, text: "Und er ging hinein und schloss die Tür hinter ihnen beiden zu* und betete zu dem HERRN*.", footnotes: ["℘ Mt 6,6", "℘ 1Kö 17,20; Apg 9,40"] },
      { number: 34, text: "Und er stieg auf <das Bett> und legte sich auf das Kind und legte seinen Mund auf dessen Mund und seine Augen auf dessen Augen und seine Hände auf dessen Hände* und beugte sich <so> über ihn*. Da wurde der Leib* des Kindes warm.", footnotes: ["℘ Kap. 13,16", "℘ 1Kö 17,21; Apg 20,10", "w. das Fleisch"] },
      { number: 35, text: "Dann ging er wieder im Haus einmal hierhin, einmal dorthin und stieg <wieder> hinauf und beugte sich über ihn. Da nieste der Junge siebenmal*, und der Junge schlug seine Augen auf*.", footnotes: ["℘ Kap. 5,10.14; 1Kö 18,43", "℘ Kap. 13,21; Mt 9,25"] },
      { number: 36, text: "Und er rief Gehasi und sagte: Ruf diese Schunemiterin! Er rief sie, und sie kam zu ihm herein. Und er sagte: Nimm deinen Sohn!*", footnotes: ["℘ Kap. 8,1.5; 1Kö 17,23"] },
      { number: 37, text: "Da kam sie und fiel ihm zu Füßen und warf sich zur Erde nieder. Und sie nahm ihren Sohn und ging hinaus." },
      { number: 38, text: "Elisa aber kehrte nach Gilgal zurück*. Es war aber Hungersnot im Land*. Als nun die Söhne der Propheten* vor ihm saßen, sagte er zu seinem Diener: Setze den großen Topf auf und koche ein Gericht für die Söhne der Propheten*!", heading: "Elisa und die vergiftete Speise — Elisa und die Hungernden", footnotes: ["℘ Kap. 2,1", "℘ Kap. 8,1; 1Kö 17,1", "o. die Jünger; o. die Schüler der Propheten", "o. die Jünger; o. die Schüler der Propheten\n℘ V. 1"] },
      { number: 39, text: "Da ging einer auf das Feld hinaus, um Kräuter zu sammeln; und er fand ein wildes Rankengewächs und las davon wilde Koloquinten*, sein Gewand voll. Und er kam und zerschnitt sie in den Kochtopf. Sie kannten sie nämlich nicht*.", footnotes: ["Koloquinten sind eine Kürbisart, deren Blätter an Weinlaub erinnern.", "℘ Spr 19,2"] },
      { number: 40, text: "Und sie schütteten es aus zum Essen für die Männer. Aber es geschah, als sie von dem Gericht aßen, da schrien sie auf und sagten: Der Tod ist im Topf, Mann Gottes! Und sie konnten nichts essen." },
      { number: 41, text: "Da sagte er: Holt Mehl! Das warf er in den Topf und sagte: Schütte es aus für die Leute, dass sie essen! Und es war nichts Schädliches <mehr> im Topf*.", footnotes: ["℘ Kap. 2,21"] },
      { number: 42, text: "Und ein Mann kam von Baal-Schalischa* und brachte dem Mann Gottes Erstlingsbrot*, zwanzig Gerstenbrote, und Jungkorn in seinem Beutel*. Und er sagte: Gib es den Leuten, dass sie essen!", footnotes: ["℘ 1Sam 9,4", "d. i. Brot vom ersten Korn der Ernte", "℘ 4Mo 18,13; 1Kö 14,3"] },
      { number: 43, text: "Sein Diener aber sagte: Wie soll ich das hundert Mann vorsetzen*? Er sagte: Gib es den Leuten, dass sie essen! Denn so spricht der HERR: Man wird essen und übrig lassen.", footnotes: ["℘ 4Mo 11,23; Mt 14,17"] },
      { number: 44, text: "Und er setzte es ihnen vor; und sie aßen und ließen übrig* nach dem Wort des HERRN.", footnotes: ["℘ Mt 14,20"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Und Naaman, der Heeroberste des Königs von Aram, war ein bedeutender Mann vor seinem Herrn und angesehen*; denn durch ihn hatte der HERR Sieg* für Aram gegeben. Der Mann war ein Kriegsheld*, <aber> aussätzig*.", heading: "Elisa und die Heilung des Naaman — Gericht über Gehasi", footnotes: ["w. war ein großer Mann vor seinem Herrn und erhobenen Gesichts", "w. Rettung", "o. ein vermögender Mann; o. ein angesehener Mann", "℘ Lk 4,27"] },
      { number: 2, text: "Und die Aramäer waren auf Raub ausgezogen und hatten aus dem Land Israel ein junges Mädchen gefangen weggeführt, das kam in den Dienst der Frau* des Naaman.", footnotes: ["w. das war vor der Frau"] },
      { number: 3, text: "Und sie sagte zu ihrer Herrin: Ach, wäre mein Herr doch vor dem Propheten, der in Samaria <wohnt>! Dann würde er ihn von seinem Aussatz befreien*.", footnotes: ["w. aufnehmen <in die menschliche Gesellschaft>"] },
      { number: 4, text: "Und Naaman* ging und berichtete es seinem Herrn und sagte: So und so hat das Mädchen geredet, das aus dem Land Israel ist.", footnotes: ["w. er"] },
      { number: 5, text: "Da sagte der König von Aram: Geh, zieh hin! Und ich will <dazu> an den König von Israel einen Brief senden. Da ging er hin und nahm zehn Talente Silber mit sich und sechstausend <Schekel> Gold und zehn Wechselkleider*.", footnotes: ["℘ Kap. 8,9; Spr 18,16"] },
      { number: 6, text: "Und er brachte den Brief zum König von Israel; und er lautete so: Und nun, wenn dieser Brief zu dir kommt, <so wisse,> siehe, ich habe meinen Knecht Naaman zu dir gesandt, damit du ihn von seinem Aussatz befreist*.", footnotes: ["w. aufnimmst <in die menschliche Gesellschaft"] },
      { number: 7, text: "Und es geschah, als der König von Israel den Brief gelesen hatte, da zerriss er seine Kleider* und sagte: Bin ich Gott*, <der die Macht hat,> zu töten und lebendig zu machen*, dass dieser zu mir sendet, einen Menschen von seinem Aussatz zu befreien*? Ja, wahrlich, erkennt doch und seht, dass er einen Anlass <zum Streit mit> mir sucht!*", footnotes: ["℘ 2Sam 1,11", "℘ 1Mo 30,2; 50,19", "℘ 1Sam 2,6", "w. aufnehmen <in die menschliche Gesellschaft>", "℘ 1Kö 20,7"] },
      { number: 8, text: "Und es geschah, als Elisa, der Mann Gottes, hörte, dass der König von Israel seine Kleider zerrissen hatte, da sandte er zu dem König und ließ <ihm> sagen: Warum hast du deine Kleider zerrissen? Lass ihn doch zu mir kommen! Und er soll erkennen, dass ein Prophet in Israel ist*.", footnotes: ["℘ 1Kö 18,36; Hes 2,5"] },
      { number: 9, text: "Da kam Naaman mit seinen Pferden und mit seinem Wagen und hielt am Eingang zu Elisas Haus." },
      { number: 10, text: "Und Elisa schickte einen Boten zu ihm und ließ <ihm> sagen: Geh hin und bade dich siebenmal* im Jordan*! So wird dir dein Fleisch wiederhergestellt werden* und rein sein.*", footnotes: ["℘ Kap. 4,35; Jos 6,4", "℘ Joh 9,7", "so mit anderer Vokalisierung; Mas. T.: So wird dein Fleisch zurückkehren", "so die syr. Üs.; Mas. T.: und sei rein!"] },
      { number: 11, text: "Da wurde Naaman zornig und ging <weg>. Und er sagte: Siehe, ich hatte mir gesagt: Er wird nach draußen zu mir herauskommen und hintreten und den Namen des HERRN, seines Gottes, anrufen und wird seine Hand über die Stelle schwingen und so den Aussätzigen <vom Aussatz> befreien*.", footnotes: ["w. aufnehmen <in die menschliche Gesellschaft>\n℘ Jes 55,8.9"] },
      { number: 12, text: "Sind nicht Abana* und Parpar, die Flüsse von Damaskus, besser als alle Wasser von Israel? Kann ich mich nicht darin baden und rein werden? Und er wandte sich um und ging im Zorn <davon>.", footnotes: ["℘ Hl 4,8"] },
      { number: 13, text: "Da traten seine Diener herzu und redeten zu ihm und sagten: Mein Vater*, hätte der Prophet eine große Sache zu dir geredet, hättest du es nicht getan? Wie viel mehr, da er <nur> zu dir gesagt hat: Bade, und du wirst rein sein*!", footnotes: ["℘ Kap. 2,12", "w. und sei rein"] },
      { number: 14, text: "Da stieg er hinab und tauchte im Jordan siebenmal* unter nach dem Wort des Mannes Gottes*. Da wurde sein Fleisch wieder wie das Fleisch eines jungen Knaben*, und er wurde rein*.", footnotes: ["℘ Lk 4,27", "℘ 1Kö 17,16", "℘ Hi 33,25", "℘ Hi 33,25"] },
      { number: 15, text: "Und er kehrte zu dem Mann Gottes zurück, er und sein ganzes Gefolge*, und er kam und trat vor ihn und sagte: Siehe doch, ich habe erkannt, dass es keinen Gott auf der ganzen Erde gibt als nur in Israel*. Und nun nimm doch ein Segensgeschenk von deinem Knecht*!", footnotes: ["w. Heer", "℘ Kap. 19,19; 1Sam 17,46; Dan 2,47", "℘ 1Kö 13,7"] },
      { number: 16, text: "Er aber sagte: So wahr der HERR lebt, vor dem ich stehe*, wenn ich es nehmen werde*!* Und er drang in ihn, es zu nehmen, doch er weigerte sich.", footnotes: ["℘ Kap. 3,14", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.", "℘ 1Mo 14,23; Dan 5,17; Mt 10,8"] },
      { number: 17, text: "Da sagte Naaman: Wenn <also> nicht, dann möge man deinem Knecht doch die Traglast eines Maultiergespannes Erde geben! Denn dein Knecht wird nicht mehr anderen Göttern Brandopfer und Schlachtopfer zubereiten, sondern nur <noch> dem HERRN*.", footnotes: ["℘ 1Thes 1,9"] },
      { number: 18, text: "In dieser <einen> Sache wolle der HERR deinem Knecht <jedoch> vergeben: Wenn mein Herr in das Haus Rimmons geht, um sich dort niederzubeugen, dann stützt er sich auf meinen Arm*, und <auch> ich beuge mich nieder im Haus Rimmons*. Wenn ich mich <nun dabei> niederbeuge im Haus Rimmons, dann möge doch der HERR deinem Knecht in dieser Sache vergeben*!", footnotes: ["w. auf meine Hand\n℘ Kap. 7,2.17", "℘ 2Mo 20,5", "℘ 2Chr 30,18"] },
      { number: 19, text: "Und er sagte zu ihm: Gehe hin in Frieden!* Als er nun von ihm weg eine Strecke Weges* gegangen war,", footnotes: ["℘ 2Mo 4,18; Mk 5,34", "w. Landes"] },
      { number: 20, text: "da sagte <sich> Gehasi*, der Diener Elisas, des Mannes Gottes: Siehe, mein Herr hat diesen Aramäer Naaman geschont, dass er nicht aus seiner Hand genommen hat, was er <ihm> gebracht hatte. So wahr der HERR lebt*, wenn ich nicht hinter ihm herlaufe und etwas von ihm nehme*!*", footnotes: ["℘ Kap. 4,12.25", "℘ Jes 48,1", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.", "℘ 1Tim 6,9.10"] },
      { number: 21, text: "So jagte Gehasi Naaman nach*. Als nun Naaman sah, dass jemand hinter ihm herlief, sprang er vom Wagen herab, <kam> ihm entgegen und sagte: Friede?", footnotes: ["℘ Jak 1,15"] },
      { number: 22, text: "Er sagte: Friede! Mein Herr sendet mich und lässt sagen: Siehe, eben jetzt sind vom Gebirge Ephraim zwei junge Männer von den Söhnen der Propheten* zu mir gekommen. Gib <mir> doch ein Talent Silber und zwei Wechselkleider* für sie!", footnotes: ["o. von den Prophetenschülern\n℘ Kap. 2,3.5.7.15", "℘ Ri 14,12"] },
      { number: 23, text: "Da sagte Naaman: Tu mir den Gefallen*, nimm zwei Talente! Und er drängte ihn* und band zwei Talente Silber in zwei Beutel und <nahm> zwei Wechselkleider und gab es zwei von seinen Dienern; und sie trugen es vor ihm her.", footnotes: ["w. Entschließe dich <mit Selbstüberwindung>; d. i. ein Ausdruck der Höflichkeit", "℘ 1Mo 33,11"] },
      { number: 24, text: "Als er aber an den Hügel kam, nahm er es aus ihrer Hand und brachte es im Haus unter*. Dann entließ er die Männer, und sie gingen <fort>.", footnotes: ["℘ Jos 7,21"] },
      { number: 25, text: "Er aber ging hinein und trat vor seinen Herrn. Da sagte Elisa zu ihm: Woher <kommst du>*, Gehasi? Er sagte: Dein Knecht ist weder hierhin noch dorthin gegangen*.", footnotes: ["℘ 1Mo 3,9; 16,8", "℘ Joh 8,34"] },
      { number: 26, text: "Da sagte er zu ihm: Ging mein Herz nicht mit, als ein Mann sich von seinem Wagen herab dir entgegenwandte*? Ist es <denn> Zeit*, Silber zu nehmen und Kleider zu nehmen und Olivenbäume und Weinberge und Schafe und Rinder und Knechte und Mägde*?", footnotes: ["℘ Kap. 6,12; Spr 12,19; Lk 12,2", "℘ Hag 1,4", "℘ Jer 45,5"] },
      { number: 27, text: "So wird der Aussatz Naamans an dir haften und an deinen Nachkommen für ewig!* Da ging er von ihm hinaus, aussätzig wie Schnee*.", footnotes: ["℘ 2Mo 20,5", "℘ 2Mo 4,6; Apg 5,3-5"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Und die Söhne der Propheten* sagten zu Elisa: Sieh doch, der Raum, wo wir vor dir wohnen, ist zu eng für uns.", heading: "Elisa und das schwimmende Eisen", footnotes: ["o. die Prophetenschüler\n℘ Kap. 2,3.5.7.15"] },
      { number: 2, text: "Lass uns doch an den Jordan gehen und von dort jeder einen Balken holen und uns hier einen Ort herrichten, um dort zu wohnen! Und er sagte: Geht hin!" },
      { number: 3, text: "Und einer sagte: Tu uns den Gefallen* und geh mit deinen Knechten*! Und er sagte: Ich will mitgehen*.", footnotes: ["w. Entschließe dich <mit Selbstüberwindung>; d. i. ein Ausdruck der Höflichkeit", "℘ 2Mo 33,15", "℘ Kap. 4,30; Joh 14,18"] },
      { number: 4, text: "So ging er mit ihnen. Und sie kamen an den Jordan und hieben die Bäume um." },
      { number: 5, text: "Es geschah aber, als einer einen Balken fällte, da fiel das Eisen ins Wasser. Und er schrie auf und sagte: Ach, mein Herr! Und <dabei> ist es doch geliehen!" },
      { number: 6, text: "Der Mann Gottes aber sagte: Wohin ist es gefallen? Und er zeigte ihm die Stelle. Da schnitt er ein <Stück> Holz ab und warf es hinein und brachte das Eisen zum Schwimmen." },
      { number: 7, text: "Und er sagte: Hole es dir heraus*! Da streckte er seine Hand aus und nahm es.", footnotes: ["℘ Mt 17,27"] },
      { number: 8, text: "Und der König von Aram führte Krieg gegen Israel*; und er beriet sich mit seinen Knechten und sagte: An dem und dem Ort soll mein Lager sein*.", heading: "Elisa vereitelt die Kriegsabsichten der Aramäer", footnotes: ["℘ V. 24; 1Kö 20,1; 22,1", "Da die Bedeutung des Wortes nicht gesichert ist, lesen andere mit Textänderung: sollt ihr einen Hinterhalt legen"] },
      { number: 9, text: "Da sandte der Mann Gottes zum König von Israel und ließ <ihm> sagen: Hüte dich, an diesem Ort vorbeizuziehen! Denn dort kommen die Aramäer herab*.", footnotes: ["Andere lesen mit Textänderung: Dort liegen die Aramäer im Hinterhalt\n℘ Hi 5,12; Ps 33,10; Spr 22,12"] },
      { number: 10, text: "Und der König von Israel sandte hin an den Ort, den der Mann Gottes ihm gesagt und <vor dem> er ihn gewarnt hatte, und war dort auf der Hut. <Das geschah> nicht <nur> einmal und nicht <nur> zweimal." },
      { number: 11, text: "Da wurde das Herz des Königs von Aram über diese Sache <sehr> beunruhigt, und er rief seine Knechte und sagte zu ihnen: Könnt ihr mir nicht mitteilen, wer von den Unseren zum König von Israel <hält>?*", footnotes: ["℘ 1Sam 22,8"] },
      { number: 12, text: "Da sagte einer von seinen Knechten: Nein, mein Herr <und> König, aber der Prophet Elisa, der in Israel ist, teilt dem König von Israel die Worte mit, die du in deinem Schlafzimmer redest*.", footnotes: ["℘ Kap. 5,26; Spr 21,30; Jes 8,10"] },
      { number: 13, text: "Da sagte er: Geht hin und seht, wo er ist! Ich werde hinsenden und ihn holen*. Und es wurde ihm berichtet: Siehe, er ist in Dotan*.", footnotes: ["℘ 1Sam 23,22.23; Ps 37,32", "℘ 1Mo 37,17"] },
      { number: 14, text: "Da sandte er Pferde und Kriegswagen dorthin und ein starkes Heer. Und sie kamen bei Nacht* und umringten die Stadt. —", footnotes: ["℘ Lk 22,53"] },
      { number: 15, text: "Und als der Diener des Mannes Gottes früh aufstand und hinausging, siehe, da umringte ein Heer die Stadt und Pferde und Kriegswagen. Und sein Diener sagte zu ihm: Ach, mein Herr! Was sollen wir tun?" },
      { number: 16, text: "Er aber sagte: Fürchte dich nicht*! Denn zahlreicher sind die, die bei uns sind, als die, die bei ihnen sind*.", footnotes: ["℘ 2Mo 14,13; Jos 11,6; Jer 39,17", "℘ 2Chr 32,7.8"] },
      { number: 17, text: "Und Elisa betete und sagte: HERR, öffne doch seine Augen, dass er sieht! Da öffnete der HERR die Augen des Dieners*, und er sah. Und siehe, der Berg war voll von feurigen Pferden und Kriegswagen* um Elisa herum*.", footnotes: ["℘ 4Mo 22,31", "℘ Kap. 2,11; 1Mo 32,2.3", "℘ Ps 125,2"] },
      { number: 18, text: "Und sie kamen zu ihm herab. Und Elisa betete zu dem HERRN und sagte: Schlag doch diese Kriegsschar* mit Blindheit*! Da schlug er sie mit Blindheit nach dem Wort des Elisa*.", footnotes: ["w. diese Nation", "℘ 1Mo 19,11; Sach 12,4; Apg 13,11", "℘ Hos 1,7"] },
      { number: 19, text: "Und Elisa sagte zu ihnen: Dies ist nicht der Weg und dies nicht die Stadt. Folgt mir! Ich will euch zu dem Mann führen, den ihr sucht. Und er führte sie nach Samaria." },
      { number: 20, text: "Und es geschah, als sie nach Samaria gekommen waren, da sagte Elisa: HERR, öffne die Augen dieser <Männer>, dass sie sehen*! Da öffnete der HERR ihre Augen, und sie sahen. Und siehe, <sie waren> mitten in Samaria.", footnotes: ["℘ 4Mo 22,31"] },
      { number: 21, text: "Und der König von Israel sagte zu Elisa, als er sie sah: Soll ich losschlagen, soll ich losschlagen, mein Vater?" },
      { number: 22, text: "Er aber sagte: Du sollst nicht schlagen! Würdest du <etwa> die erschlagen, die du mit deinem Schwert und mit deinem Bogen gefangen genommen hast? Setze ihnen Brot und Wasser vor, dass sie essen und trinken und <dann> zu ihrem Herrn ziehen*!", footnotes: ["℘ Spr 25,21"] },
      { number: 23, text: "Und er richtete ein großes Festmahl für sie aus, und sie aßen und tranken. Dann entließ er sie, und sie zogen zu ihrem Herrn*. Und die Streifscharen Arams kamen fortan nicht mehr in das Land Israel*.", footnotes: ["℘ 2Chr 28,15", "℘ Ps 46,10"] },
      { number: 24, text: "Und es geschah danach, da versammelte Ben-Hadad, der König von Aram, sein ganzes Heer und zog herauf und belagerte Samaria*.", heading: "Hungersnot im belagerten Samaria — Weissagung Elisas — Samarias Rettung", footnotes: ["℘ V. 8; Kap. 17,5; 1Kö 20,1"] },
      { number: 25, text: "Und es entstand eine große Hungersnot in Samaria*; und siehe, sie belagerten es, bis ein Eselskopf für achtzig <Schekel> Silber und ein viertel Kab* Taubenmist für fünf <Schekel> Silber <gehandelt> wurden*.", footnotes: ["℘ 1Kö 18,2", "1 Kab = ein achtzehntel Efa, das sind etwa 1,2 l. Ein viertel Kab fasst also etwa 0,3 l.", "℘ 3Mo 26,26; Hes 4,16.17"] },
      { number: 26, text: "Und es geschah, als der König von Israel auf der Mauer einherging, da schrie eine Frau ihm zu: Hilf, mein Herr und König!*", footnotes: ["℘ 1Mo 41,55"] },
      { number: 27, text: "Er aber sagte: Hilft dir der HERR nicht, woher sollte ich dir helfen?* <Etwa> von der Tenne oder von der Kelterkufe?", footnotes: ["℘ Ps 60,13; 146,3"] },
      { number: 28, text: "Und der König sagte zu ihr: Was hast du? Sie sagte: Diese Frau da hat zu mir gesagt: Gib deinen Sohn her, dass wir ihn heute essen! Meinen Sohn wollen wir dann morgen essen." },
      { number: 29, text: "So kochten wir meinen Sohn und aßen ihn*. Als ich aber am anderen Tag zu ihr sagte: Gib deinen Sohn her, dass wir ihn essen! — da hatte sie ihren Sohn versteckt*.", footnotes: ["℘ 3Mo 26,29; Kla 4,10", "℘ 5Mo 28,53-57"] },
      { number: 30, text: "Und es geschah, als der König die Worte der Frau hörte, da zerriss er seine Kleider*, und zwar als er <noch> auf der Mauer einherging; und das Volk sah, und siehe, <er trug> Sacktuch darunter auf seinem Leib*.", footnotes: ["℘ 1Kö 21,27", "w. Fleisch"] },
      { number: 31, text: "Und er sagte: So soll mir Gott tun und so hinzufügen*, wenn* der Kopf Elisas, des Sohnes Schafats, heute auf ihm bleibt!*", footnotes: ["℘ 1Sam 3,17", "hebr. Schwurformel, die meint: Alles nur erdenkliche Unglück soll Gott mir zufügen, wenn . . .", "℘ 1Kö 19,2; Spr 16,14"] },
      { number: 32, text: "Elisa aber saß in seinem Haus, und die Ältesten saßen bei ihm*. Und der König* sandte einen Mann vor sich her. Bevor nun der Bote zu ihm kam, sagte er zu den Ältesten: Habt ihr gesehen*, dass dieser Mördersohn* hergesandt hat, um mir den Kopf abzuschlagen*? Seht zu, sobald der Bote kommt, verschließt die Tür und drängt ihn mit der Tür zurück! Ist nicht der Schall der Tritte seines Herrn hinter ihm <zu hören>?", footnotes: ["℘ Hes 8,1", "w. er", "℘ Jer 11,18", "℘ 1Kö 21,19", "w. meinen Kopf zu entfernen"] },
      { number: 33, text: "Noch redete er mit ihnen, siehe, da kam der Bote* zu ihm herab; und er* sagte: Siehe, dieses Unglück <kommt> von dem HERRN*. Was soll ich noch <länger> auf den HERRN warten?*", footnotes: ["Andere lesen mit Streichung eines Buchstabens: der König", "d. i. der König", "℘ Kla 3,37-40; Am 3,6", "℘ Kap. 3,10; Hi 2,9; Spr 19,3"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Da sagte Elisa: Hört das Wort des HERRN!* So spricht der HERR: Morgen um diese Zeit wird ein Maß Weizengrieß für einen Schekel <verkauft werden> und zwei Maß Gerste für einen Schekel im Tor von Samaria*.", footnotes: ["℘ 1Sam 15,1", "℘ V. 16.18"] },
      { number: 2, text: "Da antwortete der Anführer, auf dessen Arm* sich der König stützte*, dem Mann Gottes und sagte: Siehe, wenn der HERR Fenster am Himmel machte, könnte wohl so etwas geschehen*? Er aber sagte: Siehe, du wirst es mit deinen <eigenen> Augen sehen, doch du wirst nichts davon essen!*", footnotes: ["w. Hand", "℘ Kap. 5,18", "℘ Ps 78,19", "℘ V. 19; 4Mo 11,13; Hebr 4,2"] },
      { number: 3, text: "Nun waren da vier aussätzige Männer am Eingang des Tores*, die sagten einer zum anderen: Was sollen wir hierbleiben, bis wir sterben?", footnotes: ["℘ 3Mo 13,46; Lk 4,27"] },
      { number: 4, text: "Wenn wir sagen: Lasst uns in die Stadt gehen — in der Stadt <herrscht> ja die Hungersnot —, dann werden wir dort sterben. Wenn wir aber hierbleiben, werden wir auch sterben. So kommt nun und lasst uns ins Heerlager Arams überlaufen! Wenn sie uns am Leben lassen, dann leben wir, und wenn sie uns töten, dann sterben wir*.", footnotes: ["℘ Est 4,16"] },
      { number: 5, text: "So machten sie sich in der Abenddämmerung auf, um ins Heerlager Arams zu kommen. Und sie kamen an den Rand des Heerlagers von Aram, und siehe, da war kein Mensch." },
      { number: 6, text: "Denn der Herr hatte das Heerlager Arams ein Getöse von Wagen und ein Getöse von Pferden hören lassen, das Getöse einer großen Heeresmacht*. Da hatten sie einer zum andern gesagt: Siehe, der König von Israel hat die Könige der Hetiter* und die Könige von Ägypten gegen uns angeworben, dass sie über uns kommen sollen.", footnotes: ["℘ Kap. 19,7", "℘ 1Kö 10,29"] },
      { number: 7, text: "So hatten sie sich aufgemacht und waren in der Abenddämmerung geflohen. Sie hatten ihre Zelte und ihre Pferde und ihre Esel zurückgelassen, das <ganze> Heerlager, so wie es war, und waren um ihr Leben geflohen*.", footnotes: ["℘ Ri 7,21; 1Sam 14,15; 1Kö 20,20; Ps 48,6.7; Spr 28,1"] },
      { number: 8, text: "Als nun jene Aussätzigen an den Rand des Heerlagers kamen, gingen sie in eines der Zelte* und aßen und tranken. Und sie nahmen Silber und Gold und Kleider von dort mit und gingen hin und versteckten es. Dann kehrten sie zurück und gingen in ein anderes Zelt*; und sie nahmen <auch> von dort <etwas mit>, gingen hin und versteckten es.", footnotes: ["w. in ein Zelt. — Im Hebr. steht das Zahlwort »eins«.", "w. in ein Zelt. — Im Hebr. steht das Zahlwort »eins«."] },
      { number: 9, text: "Dann sagten sie einer zum andern: Wir tun nicht recht. Dieser Tag ist ein Tag guter Botschaft. Schweigen wir aber und warten, bis der Morgen hell wird, so wird uns Schuld treffen*. Und nun kommt und lasst uns hineingehen und es im Haus des Königs berichten!", footnotes: ["℘ 1Kor 9,16"] },
      { number: 10, text: "So kamen sie und riefen die Torwache der Stadt und berichteten ihnen: Wir sind in das Heerlager Arams gekommen, und siehe, da war kein Mensch und keine Menschenstimme, sondern nur die Pferde angebunden und die Esel angebunden und die Zelte, so wie sie waren." },
      { number: 11, text: "Da riefen <es> die Torwächter aus*, und man berichtete es drinnen im Haus des Königs.", footnotes: ["so mit einigen hebr. Handschr., LXX und der aram. Üs.; Mas. T.: Und er rief die Torwächter"] },
      { number: 12, text: "Da stand der König in der Nacht auf und sagte zu seinen Knechten: Ich will euch sagen, was die Aramäer mit uns gemacht haben: Sie haben erkannt, dass wir Hunger leiden; da sind sie aus dem Lager abgezogen, um sich im Feld zu verstecken, indem sie sich sagen: Wenn sie aus der Stadt herauskommen, dann wollen wir sie lebendig greifen und in die Stadt eindringen!" },
      { number: 13, text: "Da antwortete einer von seinen Knechten und sagte: Man nehme doch fünf von den übrig gebliebenen Pferden, die hier <noch> übrig geblieben sind! Siehe, ihnen <wird es ja doch ergehen> wie der ganzen Menge Israels, die hier übrig geblieben ist; siehe, ihnen <wird es ergehen> wie der ganzen Menge Israels, die am Ende ist. Schicken wir <doch> hin, und lasst uns sehen!" },
      { number: 14, text: "So nahmen sie zwei Wagen mit Pferden, und der König schickte hinter dem Heerlager Arams <Männer> her und sagte: Geht hin und seht!" },
      { number: 15, text: "Und sie zogen hinter ihnen her bis an den Jordan; und siehe, der ganze Weg war voll von Kleidern und Geräten, die die Aramäer auf ihrer hastigen Flucht weggeworfen hatten. Und die Boten kehrten zurück und berichteten es dem König." },
      { number: 16, text: "Da ging das Volk hinaus und plünderte das Heerlager Arams*. Da wurde ein Maß Weizengrieß für einen Schekel und zwei Maß Gerste für einen Schekel <verkauft> nach dem Wort des HERRN*.", footnotes: ["℘ 2Chr 20,25; Ps 68,13", "℘ V. 1; Jes 44,26"] },
      { number: 17, text: "Der König hatte aber den Offizier, auf dessen Arm* er sich stützte*, <zur Aufsicht> über das Tor bestellt. Und das Volk trat ihn im Tor nieder, so dass er starb, geradeso wie der Mann Gottes geredet hatte, der, als der König zu ihm herabkam, es <voraus>gesagt hatte.", footnotes: ["w. Hand", "℘ V. 2"] },
      { number: 18, text: "Es war ja geschehen, als der Mann Gottes zum König geredet hatte: Zwei Maß Gerste werden morgen um diese Zeit für einen Schekel <verkauft> werden und ein Maß Weizengrieß <ebenso> für einen Schekel im Tor von Samaria*,", footnotes: ["℘ V. 1; Jes 44,26"] },
      { number: 19, text: "da hatte der Offizier dem Mann Gottes geantwortet und gesagt: Siehe, wenn der HERR auch Fenster am Himmel machte, könnte wohl so etwas geschehen? Er aber hatte gesagt: Siehe, du wirst es mit deinen <eigenen> Augen sehen, doch du wirst nichts davon essen*.", footnotes: ["℘ V. 2"] },
      { number: 20, text: "So geschah es ihm nun: Das Volk trat ihn im Tor nieder, so dass er starb*.", footnotes: ["℘ Jer 28,17"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Und Elisa hatte zu der Frau, deren Sohn er lebendig gemacht hatte*, gesagt: Mache dich auf und geh <fort>, du und dein Haus, und bleibe als Fremde, wo du bleiben kannst! Denn der HERR hat eine Hungersnot herbeigerufen*; die wird auch ins Land kommen sieben Jahre lang*.", heading: "Elisa und die Schunemiterin", footnotes: ["℘ Kap. 4,35.36", "℘ Kap. 4,38; Rt 1,1; 2Sam 24,13; Ps 105,16; Hag 1,11", "℘ 1Mo 41,27; Am 4,6"] },
      { number: 2, text: "Da machte sich die Frau auf und tat nach dem Wort des Mannes Gottes: Sie ging <fort>, sie und ihr Haus, und blieb als Fremde in dem Land der Philister sieben Jahre lang." },
      { number: 3, text: "Und es geschah am Ende von sieben Jahren, da kehrte die Frau aus dem Land der Philister zurück*. Und sie ging aus, um zum König wegen ihres Hauses und wegen ihres Feldes zu schreien*.", footnotes: ["℘ Rt 1,7", "℘ Kap. 4,13"] },
      { number: 4, text: "Der König aber redete gerade zu Gehasi*, dem Diener des Mannes Gottes*, und sagte: Erzähle mir doch all die großen Taten, die Elisa getan hat!", footnotes: ["℘ Kap. 4,12.25", "℘ V. 2"] },
      { number: 5, text: "Und es geschah, während er dem König erzählte, dass Elisa* den Toten lebendig gemacht hatte, siehe, da schrie die Frau, deren Sohn er lebendig gemacht hatte, zum König wegen ihres Hauses und wegen ihres Feldes. Da sagte Gehasi: Mein Herr und König! Das ist die Frau, und das ist ihr Sohn, den Elisa lebendig gemacht hat*.", footnotes: ["w. er", "℘ 1Kö 20,1"] },
      { number: 6, text: "Und der König fragte die Frau, und sie erzählte es ihm. Da gab der König ihr einen Hofbeamten* mit und sagte: Erstatte alles zurück, was ihr gehört, sowie den ganzen Ertrag des Feldes, von dem Tag ab, an dem sie das Land verlassen hat, bis jetzt!", footnotes: ["w. einen Eunuchen"] },
      { number: 7, text: "Und Elisa kam nach Damaskus. Ben-Hadad aber, der König von Aram*, war krank. Und es wurde ihm berichtet: Der Mann Gottes ist hierhergekommen.", heading: "Elisa und Hasaël von Damaskus", footnotes: ["℘ 1Kö 20,1"] },
      { number: 8, text: "Da sagte der König zu Hasaël*: Nimm ein Geschenk mit dir* und geh dem Mann Gottes entgegen und befrage den HERRN durch ihn und sage: Werde ich von dieser Krankheit genesen*?", footnotes: ["℘ 1Kö 19,15", "w. in deine Hand\n℘ 1Sam 9,7.8", "℘ Kap. 1,2; 1Kö 14,3"] },
      { number: 9, text: "Und Hasaël ging ihm entgegen und nahm ein Geschenk mit sich* und allerlei Kostbares von Damaskus, eine Traglast für vierzig Kamele*. Und er kam und trat vor ihn hin und sagte: Dein Sohn Ben-Hadad, der König von Aram, hat mich zu dir gesandt und lässt sagen: Werde ich von dieser Krankheit genesen*?", footnotes: ["w. in seine Hand", "℘ Kap. 5,5", "℘ Kap. 1,2; 1Kö 14,3"] },
      { number: 10, text: "Elisa sagte zu ihm: Geh hin, sage ihm: Du wirst bestimmt genesen!* Aber der HERR hat mich sehen lassen, dass er stirbt, <ja dass> er stirbt*.", footnotes: ["so mit 18 hebr. Handschr. und der Leseform des Mas. T.; mit der Schreibform: Geh hin, sage: Nicht wirst du genesen!", "℘ Kap. 1,4"] },
      { number: 11, text: "Dabei starrte er unbeweglich vor sich hin* und war über die Maßen* entsetzt*. Dann weinte der Mann Gottes*.", footnotes: ["w. Dann stellte er sein Gesicht fest", "w. bis zur Beschämung", "So konnte der Text vor der Vokalisierung durch die Masoreten verstanden werden. Mas. T.: und richtete bis zur Beschämung <das Gesicht auf ihn>", "℘ Jer 4,19; Lk 19,41"] },
      { number: 12, text: "Da sagte Hasaël: Warum weint mein Herr? Er sagte: Weil ich erkannt habe, was du den Söhnen Israel Böses antun wirst*: Ihre festen Städte wirst du in Brand stecken und ihre jungen <wehrfähigen> Männer mit dem Schwert erschlagen und ihre Kinder wirst du zerschmettern und ihre Schwangeren aufschlitzen*.", footnotes: ["℘ Kap. 10,32.33; 12,18; 13,3.7.22; Am 1,3.4", "℘ Kap. 15,16; Hos 14,1; Am 1,13"] },
      { number: 13, text: "Da sagte Hasaël: Was ist dein Knecht, der Hund*, dass er eine so große Sache tun könnte? Elisa aber sagte: Der HERR hat mich dich sehen lassen als König über Aram*.", footnotes: ["℘ 1Sam 17,43", "℘ 1Kö 19,15"] },
      { number: 14, text: "Dann ging er von Elisa weg und kam zu seinem Herrn. Der sagte zu ihm: Was hat Elisa dir gesagt? Er sprach: Er hat mir gesagt: Du wirst bestimmt genesen." },
      { number: 15, text: "Und es geschah am folgenden Tag, da nahm er die Decke und tauchte sie ins Wasser und breitete sie über sein Gesicht, so dass er starb. Und Hasaël wurde an seiner Stelle König*.", footnotes: ["℘ 1Kö 19,15"] },
      { number: 16, text: "*Im fünften Jahr des Joram, des Sohnes Ahabs, des Königs von Israel*, *als Joschafat <noch> König von Juda war*, wurde Joram König*, der Sohn Joschafats, des Königs von Juda*.", heading: "Joram von Juda", footnotes: ["℘ 2Chr 21; 22,1", "℘ Kap. 1,17", "Dieser Satz fehlt in LXX und der syr. Üs.", "Dieser Satz fehlt in LXX und der syr. Üs.", "℘ Kap. 11,2; 1Kö 22,51; Mt 1,8", "℘ V. 25"] },
      { number: 17, text: "32 Jahre war er alt, als er König wurde, und er regierte acht Jahre in Jerusalem." },
      { number: 18, text: "Und er ging auf dem Weg der Könige von Israel, wie es das Haus Ahabs tat, denn er hatte eine Tochter Ahabs zur Frau*. Und er tat, was böse war in den Augen des HERRN*.", footnotes: ["℘ 2Chr 22,2", "℘ Kap. 16,3; 1Kö 22,53; 1Kor 15,33"] },
      { number: 19, text: "Aber der HERR wollte Juda nicht vernichten wegen seines Knechtes David*, wie er ihm zugesagt hatte, dass er ihm eine Leuchte geben wolle <und> seinen Söhnen alle Tage*.", footnotes: ["℘ Kap. 19,34; 1Kö 11,12.13; Ps 132,10", "℘ Kap. 11,2; 2Sam 7,13.16; 1Kö 11,36"] },
      { number: 20, text: "In seinen Tagen fiel Edom von <der Herrschaft> unter der Hand Judas* ab und setzte einen <eigenen> König über sich*.", footnotes: ["℘ 1Mo 27,40", "℘ Kap. 3,9; 1Kö 22,48"] },
      { number: 21, text: "Da zog Joram hinüber nach Zaïr und alle Kriegswagen mit ihm. Und es geschah, als er sich des Nachts aufmachte, da schlug er Edom*, das ihn eingekreist hatte, und zwar die Obersten der Wagen. Da floh das Volk zu seinen Zelten.", footnotes: ["℘ Kap. 14,7"] },
      { number: 22, text: "Doch fiel Edom von <der Herrschaft> unter der Hand Judas ab bis auf den heutigen Tag*. Damals, in jener Zeit, fiel <auch> Libna ab.", footnotes: ["℘ 2Chr 28,17"] },
      { number: 23, text: "Und die übrige Geschichte* Jorams und alles, was er getan hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Juda?*", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ Kap. 12,20; 14,18; 15,6.36; 16,19; 20,20; 21,17.25; 23,28; 24,5; 1Kö 14,29"] },
      { number: 24, text: "Und Joram legte sich zu seinen Vätern und wurde bei seinen Vätern begraben in der Stadt Davids*. Und sein Sohn Ahasja wurde an seiner Stelle König.", footnotes: ["℘ Kap. 9,28; 12,22; 14,20; 15,38; 16,20; 1Kö 2,10"] },
      { number: 25, text: "*Im zwölften Jahr Jorams, des Sohnes Ahabs, des Königs von Israel, wurde Ahasja* König, der Sohn Jorams, des Königs von Juda*.", heading: "Ahasja von Juda", footnotes: ["℘ 2Chr 22,1-6", "℘ 1Chr 3,11", "℘ V. 16; Kap. 9,29"] },
      { number: 26, text: "Ahasja war 22 Jahre alt, als er König wurde, und er regierte ein Jahr in Jerusalem; und der Name seiner Mutter war Atalja*, die Tochter Omris*, des Königs von Israel.", footnotes: ["℘ Kap. 11,1", "Gemeint ist die Enkeltochter Omris.\n℘ 1Kö 16,22"] },
      { number: 27, text: "Und er ging auf dem Weg des Hauses Ahabs und tat, was böse war in den Augen des HERRN, wie das Haus Ahabs; denn er war mit dem Haus Ahabs verschwägert." },
      { number: 28, text: "Und er zog mit Joram, dem Sohn Ahabs, in den Kampf gegen Hasaël, den König von Aram, bei Ramot <in> Gilead*. Und die Aramäer verwundeten Joram.", footnotes: ["℘ Kap. 9,1.2; Jos 20,8; 1Kö 22,3.4"] },
      { number: 29, text: "Da kehrte der König Joram zurück, um sich in Jesreel* von den Wunden heilen zu lassen, die ihm die Aramäer bei Rama geschlagen hatten, als er gegen Hasaël, den König von Aram, kämpfte. Und Ahasja, der Sohn Jorams, der König von Juda, zog hinab, um Joram, den Sohn Ahabs, in Jesreel zu besuchen, weil er krank war*.", footnotes: ["℘ Jos 19,18", "℘ Kap. 9,14-16"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "*Und der Prophet Elisa rief einen von den Söhnen der Propheten* und sagte zu ihm: Gürte deine Hüften* und nimm diesen Ölkrug in deine Hand und geh nach Ramot <in> Gilead!*", heading: "Jehu von Israel: Salbung zum König", footnotes: ["℘ V. 1-29: 2Chr 22,5-9", "o. von den Prophetenschülern\n℘ Kap. 2,3.5.7.15", "℘ Kap. 4,29; Lk 12,35", "℘ Kap. 8,28"] },
      { number: 2, text: "Und wenn du dahin gekommen bist, dann sieh dich dort nach Jehu um, dem Sohn des Joschafat, des Sohnes Nimschis; <zu dem> geh hinein und lass ihn aus der Mitte seiner Brüder aufstehen und in die innerste Kammer gehen!" },
      { number: 3, text: "Und nimm den Krug mit Öl und gieß es auf sein Haupt aus und sage: So spricht der HERR: Ich habe dich <hiermit> zum König über Israel gesalbt*! Dann öffne die Tür und flieh und warte nicht!", footnotes: ["℘ 1Sam 10,1; 1Kö 19,16"] },
      { number: 4, text: "Da ging der Diener, der Diener des Propheten, nach Ramot <in> Gilead." },
      { number: 5, text: "Als er hineinkam, siehe, da saßen die Obersten des Heeres <beisammen>. Und er sagte: Ich habe ein Wort an dich, Oberster. Da sagte Jehu: An wen von uns allen? Er sagte: An dich, Oberster." },
      { number: 6, text: "Da stand Jehu* auf und ging ins Haus hinein; und der Prophetenschüler* goss das Öl auf sein Haupt und sagte zu ihm: So spricht der HERR, der Gott Israels: Ich habe dich zum König über das Volk des HERRN gesalbt, über Israel*.", footnotes: ["w. er", "w. er", "℘ 1Sam 10,1; 1Kö 19,16"] },
      { number: 7, text: "Du sollst das Haus Ahabs, deines Herrn, erschlagen*! Und ich räche das Blut meiner Knechte, der Propheten, und das Blut aller Knechte des HERRN <fordere ich> von der Hand Isebels*.", footnotes: ["℘ Kap. 10,11", "℘ 1Kö 18,4; Ps 94,1.2; Offb 19,2"] },
      { number: 8, text: "Ja, das ganze Haus Ahabs soll umkommen. Und ich werde von Ahab <alles> ausrotten, was männlich ist*, den Unmündigen und Mündigen* in Israel*.", footnotes: ["w. was an die Wand pisst", "o. den Verheirateten und Unverheirateten; o. den Sklaven und Freien; w. den Festgehaltenen und Losgelassenen", "℘ Kap. 19,17; 21,13; 1Kö 14,10; 21,21"] },
      { number: 9, text: "Und ich werde das Haus Ahabs machen wie das Haus Jerobeams, des Sohnes Nebats, und wie das Haus Baschas, des Sohnes Ahijas*.", footnotes: ["℘ Kap. 10,11; 1Kö 15,29"] },
      { number: 10, text: "Isebel aber sollen die Hunde fressen auf dem Feld* von Jesreel*, und da wird niemand sein, der begräbt. Und er öffnete die Tür und floh.", footnotes: ["w. Losanteil", "℘ 1Kö 21,23"] },
      { number: 11, text: "Und Jehu kam heraus zu den Knechten seines Herrn. Und man sagte zu ihm: Ist es Friede? Warum ist dieser Rasende* zu dir gekommen? Er sagte zu ihnen: Ihr kennt ja den Mann und sein Geschwätz.", footnotes: ["℘ Jer 29,26; Apg 26,24"] },
      { number: 12, text: "Sie aber sagten: Ausflüchte*! Berichte uns doch! Da sagte er: So und so hat er zu mir geredet und hat gesagt: So spricht der HERR: Ich habe dich zum König über Israel gesalbt*!", footnotes: ["w. Lüge", "℘ 1Sam 10,1; 1Kö 19,16"] },
      { number: 13, text: "Da nahmen sie schnell jeder sein Gewand und legten es unter ihn* auf die nackten Stufen*; und sie stießen ins Horn und riefen: Jehu ist König*!", footnotes: ["d. h. ihm zu Füßen", "℘ Mt 21,7.8", "℘ Kap. 11,12; 2Sam 15,10; 1Kö 1,39"] },
      { number: 14, text: "So stiftete Jehu, der Sohn Joschafats, des Sohnes Nimschis, eine Verschwörung gegen Joram an*. Joram aber hatte Wache gehalten bei Ramot <in> Gilead, er und ganz Israel, wegen Hasaëls, des Königs von Aram.", heading: "Jehus Aufstand: Tod Jorams von Israel, Ahasjas von Juda und Isebels", footnotes: ["℘ Kap. 10,9; 12,21; 1Kö 15,27"] },
      { number: 15, text: "Und der König Joram war zurückgekehrt, um sich in Jesreel von den Wunden heilen zu lassen, die ihm die Aramäer geschlagen hatten, als er gegen Hasaël, den König von Aram, kämpfte*. Und Jehu sagte: Wenn es euer Wille ist, soll niemand aus der Stadt entkommen, um hinzugehen, es in Jesreel zu berichten.", footnotes: ["℘ Kap. 8,28.29"] },
      { number: 16, text: "Und Jehu bestieg den Wagen und fuhr nach Jesreel, denn dort lag Joram <krank>. Und Ahasja, der König von Juda, war hinabgezogen, um Joram zu besuchen*.", footnotes: ["℘ Kap. 8,28.29"] },
      { number: 17, text: "Und der Wächter stand auf dem Turm in Jesreel und sah* die Schar Jehus, wie er herankam, und sagte: Ich sehe eine Schar! Da sagte Joram: Nimm einen Reiter und sende <ihn> ihnen entgegen, und er soll sagen: Ist Friede?", footnotes: ["℘ 2Sam 18,24"] },
      { number: 18, text: "Da zog der Berittene ihm entgegen und sagte: So spricht der König: Ist Friede? Jehu sagte: Was kümmert es dich, ob Friede ist*? Wende um, mir nach! Und der Wächter berichtete: Der Bote ist bis zu ihnen gekommen, kehrt aber nicht zurück.", footnotes: ["℘ Jes 48,22"] },
      { number: 19, text: "Da sandte er einen zweiten Berittenen. Der kam zu ihnen und sagte: So spricht der König: Ist es Friede? Jehu sagte: Was kümmert es dich, ob Friede ist*? Wende um, mir nach!", footnotes: ["℘ Jes 48,22"] },
      { number: 20, text: "Und der Wächter berichtete: Er ist bis zu ihnen gekommen, kehrt aber nicht zurück. Und das Fahren gleicht dem Fahren Jehus, des Sohnes Nimschis; denn er fährt <wie> in Raserei." },
      { number: 21, text: "Da sagte Joram: Spannt an! Und man spannte seinen Wagen an. Und Joram, der König von Israel, und Ahasja, der König von Juda, zogen aus, jeder auf seinem Wagen; sie zogen aus, Jehu entgegen, und trafen ihn auf dem <Feld>stück Nabots, des Jesreeliters*.", footnotes: ["℘ 1Kö 21,16"] },
      { number: 22, text: "Und es geschah, als Joram den Jehu sah, sagte er: Ist es Friede*, Jehu? Er aber sagte: Was, Friede? Bei den vielen Hurereien deiner Mutter Isebel und ihren vielen Zaubereien*!", footnotes: ["℘ Pred 3,8", "℘ 1Kö 21,25; Offb 2,20; 9,21"] },
      { number: 23, text: "Da machte Joram kehrt* und floh und sagte zu Ahasja: Verrat*, Ahasja!", footnotes: ["w. Da wandte Joram seine Hände", "w. Betrug, o. Hinterlist"] },
      { number: 24, text: "Jehu aber nahm seinen Bogen zur Hand* und traf Joram zwischen die Schulterblätter*, so dass der Pfeil ihm durchs Herz fuhr; und er brach in seinem Wagen zusammen*.", footnotes: ["o. hatte den Pfeil auf den Bogen gelegt; w. füllte seine Hand mit dem Bogen", "w. zwischen seine Arme", "℘ Kap. 10,9; 1Kö 19,17; 22,35"] },
      { number: 25, text: "Und Jehu* sagte zu seinem Offizier* Bidkar: Nimm ihn <und> wirf ihn auf das Feldstück des Jesreeliters Nabot! Denn denk daran, wie ich und du zweispännig* hinter seinem Vater herfuhren und der HERR diesen Ausspruch über ihn tat:", footnotes: ["w. er", "o. Wagenkämpfer; w. zu seinem dritten <Mann auf dem Kriegswagen>", "Damit ist ein Offizierswagen mit zwei Pferden gemeint."] },
      { number: 26, text: "»Wenn ich das Blut Nabots und das Blut seiner Söhne gestern nicht gesehen habe*! spricht der HERR*. Ich werde es dir vergelten auf diesem <Feld>stück, spricht der HERR*.« Und nun nimm <ihn auf>, wirf ihn auf das <Feld>stück nach dem Wort des HERRN*!", footnotes: ["Der Satz ist eine Schwurformel mit der Bedeutung: Ich habe den Tod Nabots nicht übersehen!", "w. ist der Ausspruch des HERRN", "w. ist der Ausspruch des HERRN", "℘ 1Kö 21,13.19.29; Ps 9,13"] },
      { number: 27, text: "Als Ahasja, der König von Juda, das sah, floh er in Richtung Bet-Gan*. Jehu aber jagte ihm nach und sagte: *Auch ihn! Und man verwundete ihn auf dem Wagen beim Anstieg von Gur*, das bei Jibleam* <liegt>. Und er floh nach Megiddo* und starb dort*.", footnotes: ["o. in die Richtung des Gartenhauses", "so liest LXX; Mas. T.: Auch ihn erschlagt auf dem Wagen beim Anstieg von Gur", "so liest LXX; Mas. T.: Auch ihn erschlagt auf dem Wagen beim Anstieg von Gur", "℘ Jos 17,11", "℘ Jes 48,22", "℘ Kap. 12,21; 14,19; 21,23"] },
      { number: 28, text: "Und seine Knechte führten ihn auf einem Wagen nach Jerusalem, und sie begruben ihn in seinem Grab bei seinen Vätern in der Stadt Davids*.", footnotes: ["℘ Kap. 8,24; 1Kö 2,10"] },
      { number: 29, text: "Und im elften Jahr Jorams, des Sohnes Ahabs, war Ahasja König geworden über Juda*.", footnotes: ["℘ Kap. 8,25"] },
      { number: 30, text: "Und Jehu kam nach Jesreel. Und als Isebel es hörte, belegte sie ihre Augen mit Schminke und schmückte ihr Haupt* und schaute zum Fenster hinaus.", footnotes: ["℘ Jer 4,30; Hes 23,40"] },
      { number: 31, text: "Und als Jehu ins Tor kam, sagte sie: Geht es dir gut*, du Simri, der seinen Herrn erschlug*?", footnotes: ["w. Ist Friede", "℘ 1Kö 16,10.18"] },
      { number: 32, text: "Er erhob sein Gesicht zum Fenster und sagte: Wer ist mit mir, wer? Da blickten zwei, drei Hofbeamte* zu ihm hinunter.", footnotes: ["w. Eunuchen"] },
      { number: 33, text: "Und er sagte: Stürzt sie herunter! Und sie stürzten sie hinunter. Und es spritzte von ihrem Blut an die Wand und an die Pferde, und er zertrat sie*.", footnotes: ["℘ Jes 26,6; Mi 7,10; Sach 10,5; Mal 3,21"] },
      { number: 34, text: "Darauf ging er hinein, aß und trank. Dann sagte er: Seht doch nach dieser Verfluchten und begrabt sie! Denn sie ist eine Königstochter*.", footnotes: ["℘ 1Kö 16,31"] },
      { number: 35, text: "Da gingen sie hin, um sie zu begraben. Aber sie fanden nichts von ihr als nur den Schädel und die Füße und die Handteller*.", footnotes: ["℘ Pred 6,3; Jes 14,18-20"] },
      { number: 36, text: "Und sie kamen zurück und berichteten es ihm. Da sagte er: Das ist das Wort des HERRN, das er durch seinen Knecht Elia, den Tischbiter, geredet hat*: Auf dem Feld* von Jesreel sollen die Hunde das Fleisch Isebels fressen*;", footnotes: ["℘ Kap. 1,17", "w. Losanteil", "℘ 1Kö 21,23"] },
      { number: 37, text: "und die Leiche Isebels soll auf dem Feld* von Jesreel wie der Mist auf dem Acker werden*, so dass man nicht <mehr> sagen kann: Das ist Isebel.", footnotes: ["w. Losanteil", "℘ Ps 83,11; Jer 8,2"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Und Ahab hatte siebzig Söhne in Samaria. Und Jehu schrieb Briefe und sandte sie nach Samaria an die Obersten von Jesreel*, an die Ältesten* und an die Erzieher <der Söhne> Ahabs, die lauteten:", heading: "Ausrottung des Hauses Ahabs durch Jehu", footnotes: ["LXX und Vulg. lesen: an die Obersten der Stadt", "℘ 1Kö 21,8"] },
      { number: 2, text: "Und nun, wenn dieser Brief zu euch kommt — bei euch sind ja die Söhne eures Herrn und bei euch die Kriegswagen und die Pferde und eine befestigte Stadt und Waffen —," },
      { number: 3, text: "so seht <euch um nach dem> besten und tüchtigsten von den Söhnen eures Herrn und setzt ihn auf den Thron seines Vaters und kämpft für das Haus eures Herrn!" },
      { number: 4, text: "Aber sie fürchteten sich über alle Maßen und sagten <sich>: Siehe, die beiden Könige konnten nicht vor ihm bestehen, wie sollten wir da bestehen können*?", footnotes: ["℘ Kap. 9,24.27"] },
      { number: 5, text: "Und der, der über das Haus*, und der, der über die Stadt <gesetzt> war, und die Ältesten und die Erzieher sandten hin zu Jehu und ließen <ihm> sagen: Deine Knechte sind wir; alles, was du zu uns sagst, wollen wir tun*; wir wollen niemanden zum König machen. Tu, was gut ist in deinen Augen!", footnotes: ["d. i. über den Königspalast", "℘ Kap. 18,14; Jos 9,25"] },
      { number: 6, text: "Da schrieb er zum zweiten Mal einen Brief an sie, der lautete: Wenn ihr mir <folgt> und auf meine Stimme hört, dann nehmt die Häupter* der Männer, der Söhne eures Herrn, und kommt morgen um diese Zeit zu mir nach Jesreel! Und die Königssöhne, siebzig Mann, <waren gerade> bei den Großen der Stadt, die sie aufzogen.", footnotes: ["Das Wort »Haupt« bedeutet im Hebr. sowohl »Kopf« als auch »Oberhaupt, Anführer« und wird hier wohl bewusst doppeldeutig gebraucht."] },
      { number: 7, text: "Und es geschah, als der Brief zu ihnen kam, nahmen sie die Söhne des Königs und schlachteten sie, siebzig Mann*, und legten ihre Köpfe in Körbe und sandten sie zu ihm nach Jesreel.", footnotes: ["℘ 1Kö 21,19-22"] },
      { number: 8, text: "Und der Bote kam und berichtete ihm und sagte: Man hat die Köpfe der Königssöhne gebracht. Da sagte er: Legt sie in zwei Haufen an den Eingang des Tores bis zum Morgen!" },
      { number: 9, text: "Und es geschah am Morgen, da ging er hinaus, trat hin und sagte zum ganzen Volk: Ihr seid gerecht! Siehe, ich habe mich gegen meinen Herrn verschworen und habe ihn umgebracht*. Wer aber hat alle diese erschlagen?", footnotes: ["℘ Kap. 9,14.24"] },
      { number: 10, text: "Erkennt also, dass nichts zur Erde fällt* von dem Wort des HERRN, das der HERR gegen das Haus Ahabs geredet hat! Der HERR hat getan, was er durch seinen Knecht Elia geredet hat*.", footnotes: ["℘ 1Sam 3,19", "℘ 1Kö 21,19-22"] },
      { number: 11, text: "Und Jehu erschlug alle, die vom Haus Ahabs in Jesreel übrig geblieben waren, alle seine Großen und seine Vertrauten und seine Priester, bis er ihm nicht einen Entkommenen übrig gelassen hatte*.", footnotes: ["℘ Kap. 9,7.9; 1Kö 21,29; 2Chr 22,7; Hos 1,4"] },
      { number: 12, text: "Und er machte sich auf, ging hin und zog nach Samaria. Er war bei Bet-Eked-Haroim* auf dem Weg,", footnotes: ["d. h. Haus des Sandhaufens der Hirten"] },
      { number: 13, text: "da traf Jehu die Brüder Ahasjas*, des Königs von Juda. Und er sagte: Wer seid ihr? Sie sagten: Wir sind die Brüder Ahasjas und ziehen hinab zur Begrüßung der Söhne des Königs und der Söhne der Herrin*.", footnotes: ["℘ 2Chr 22,1", "d. i. der Königinmutter"] },
      { number: 14, text: "Da sagte Jehu*: Packt sie lebendig! Und sie packten sie lebendig und schlachteten sie bei der Zisterne von Bet-Eked, 42 Mann, und er ließ keinen von ihnen übrig*.", footnotes: ["w. er", "℘ 2Chr 22,8"] },
      { number: 15, text: "Dann ging er von dort <weiter> und traf Jonadab, den Sohn Rechabs*, der ihm entgegenkam. Und er grüßte* ihn und sagte zu ihm: Ist dein Herz aufrichtig wie mein Herz gegen dein Herz?* Jonadab sagte: Es ist so. — Wenn es so ist, dann gib mir deine Hand* — und er gab ihm seine Hand. Da ließ er ihn zu sich auf den Wagen steigen*", footnotes: ["℘ 1Chr 2,55; Neh 3,14; Jer 35,6", "w. segnete", "℘ 1Chr 12,18", "℘ Esr 10,19; Hes 17,18", "℘ 1Kö 20,33"] },
      { number: 16, text: "und sagte: Komm mit mir und sieh mein Eifern für den HERRN an*! Und man ließ ihn auf seinem Wagen mitfahren.", footnotes: ["℘ 1Kö 19,10; Spr 27,2"] },
      { number: 17, text: "Und als er nach Samaria kam, erschlug er alle, die von Ahab in Samaria übrig geblieben waren, bis er ihn ganz ausgetilgt hatte* nach dem Wort des HERRN, das er zu Elia geredet hatte*.", footnotes: ["℘ Kap. 9,8", "℘ Kap. 1,17; 1Kö 21,21"] },
      { number: 18, text: "Und Jehu versammelte das ganze Volk und sagte zu ihnen: Ahab hat dem Baal ein wenig gedient*, Jehu will ihm viel dienen*.", heading: "Ausrottung des Baalsdienstes durch Jehu", footnotes: ["℘ Kap. 17,16; 1Kö 16,31.32", "℘ Hi 13,7"] },
      { number: 19, text: "Und nun, ruft alle Propheten des Baal*, alle seine Diener und alle seine Priester zu mir! Kein Mann soll vermisst werden! Denn ich habe ein großes Schlachtopfer für den Baal <vorbereitet>. Keiner, der vermisst wird, soll am Leben bleiben! Jehu handelte aber mit Hinterlist, um die Diener des Baal umzubringen.", footnotes: ["℘ 1Kö 22,6"] },
      { number: 20, text: "Und Jehu sagte: Heiligt dem Baal eine Festversammlung! Und man rief sie aus." },
      { number: 21, text: "Und Jehu sandte <Boten> in ganz Israel umher. Da kamen alle Diener des Baal; keiner blieb übrig, der nicht gekommen wäre. Und sie kamen in das Haus des Baal*, und das Haus des Baal wurde voll von einem Ende bis zum andern.", footnotes: ["℘ 1Kö 16,32"] },
      { number: 22, text: "Und er sagte zu dem, der über die Kleiderkammer <gesetzt> war: Bring <Fest>kleidung heraus für alle Diener des Baal! Und er brachte ihnen die Gewänder heraus." },
      { number: 23, text: "Und Jehu und Jonadab, der Sohn Rechabs, gingen ins Haus des Baal hinein, und er sagte zu den Dienern des Baal: Sucht gründlich nach und seht zu, dass nicht etwa einer von den Dienern des HERRN hier bei euch sei, sondern nur Diener des Baal allein!" },
      { number: 24, text: "Und sie gingen hinein, um Schlachtopfer und Brandopfer zuzubereiten. Jehu hatte sich aber draußen achtzig Mann aufgestellt und gesagt: Der Mann, der einen von den Männern entkommen lässt*, die ich in eure Hände kommen lasse, sein Leben soll für dessen Leben <einstehen>*.", footnotes: ["T.; Mas. T.: Der Mann, der sich retten kann von den Männern", "w. seine Seele stattdessen Seele; d. h. statt des Baalsdieners, den er hätte umbringen sollen\n℘ 1Kö 20,39"] },
      { number: 25, text: "Und es geschah, sobald man mit der Zubereitung des Brandopfers fertig war, sagte Jehu zu den Leibwächtern* und zu den Offizieren*: Geht hinein, erschlagt sie! Keiner darf herauskommen*! Und sie schlugen sie mit der Schärfe des Schwertes*. Und die Leibwächter* und die Offiziere* warfen sie <hinaus>. Dann gingen sie zum Stadt<teil> des Hauses des Baal", footnotes: ["w. Läufer(n)", "o. Wagenkämpfer; w. zu seinem dritten <Mann auf dem Kriegswagen>", "℘ 2Mo 32,27", "℘ Kap. 11,18; 1Kö 18,40", "o. Wagenkämpfer; w. zu seinem dritten <Mann auf dem Kriegswagen>", "o. Wagenkämpfer; w. zu seinem dritten <Mann auf dem Kriegswagen>"] },
      { number: 26, text: "und holten die Gedenksteine* des Hauses des Baal heraus und verbrannten sie*;", footnotes: ["hebr. mazzebot; das sind aufrecht hingestellte Steine, die kultisch verehrt wurden", "℘ Kap. 18,4; 19,18; 23,4.14; 5Mo 7,5; 1Kö 15,13; 1Chr 14,12"] },
      { number: 27, text: "und sie rissen den Gedenkstein des Baal nieder*; und sie rissen das Haus des Baal nieder* und machten Aborte daraus*; <die sind dort> bis auf den heutigen Tag.", footnotes: ["℘ 2Mo 34,13", "℘ Kap. 3,2; 11,18; 2Chr 34,3-7", "℘ Esr 6,11"] },
      { number: 28, text: "So tilgte Jehu den Baal aus Israel aus." },
      { number: 29, text: "Nur von den Sünden Jerobeams, des Sohnes Nebats, der Israel zur Sünde verführt hatte, von denen wich Jehu nicht ab, von den goldenen Kälbern*, die in Bethel und in Dan waren*.", footnotes: ["Das Wort Kalb ist hier ein verächtlicher Ausdruck für ein Stierbild.", "℘ Kap. 3,3; 1Kö 12,29"] },
      { number: 30, text: "Und der HERR sprach zu Jehu: Weil du gut ausgeführt hast, was recht ist in meinen Augen, <und> am Haus Ahabs nach allem getan hast, was in meinem Herzen war, darum sollen dir Söhne der vierten <Generation> auf dem Thron Israels sitzen*.", footnotes: ["℘ V. 35; Kap. 13,1.10; 14,23.29; 15,8-12"] },
      { number: 31, text: "Aber Jehu achtete nicht darauf, mit seinem ganzen Herzen im Gesetz des HERRN, des Gottes Israels, zu leben*. Er wich nicht von den Sünden Jerobeams, der Israel zur Sünde verführt hatte*.", footnotes: ["w. zu gehen\n℘ 5Mo 10,12", "℘ Kap. 17,22; 1Kö 14,16"] },
      { number: 32, text: "In jenen Tagen begann der HERR, <Teile> in Israel abzuschlagen. Und Hasaël schlug sie im ganzen Gebiet Israels*,", footnotes: ["℘ Kap. 8,12"] },
      { number: 33, text: "vom Jordan an nach Sonnenaufgang zu das ganze Land Gilead, die Gaditer und die Rubeniter und die Manassiter, von Aroër an, das am Fluss Arnon <liegt>, sowohl Gilead als auch Baschan*.", footnotes: ["℘ 5Mo 3,12.13"] },
      { number: 34, text: "Und die übrige Geschichte* Jehus und alles, was er getan hat, und alle seine Machttaten, ist das nicht geschrieben im Buch der Geschichte* der Könige von Israel*?", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ Kap. 1,18; 1Kö 14,19"] },
      { number: 35, text: "Und Jehu legte sich zu seinen Vätern, und man begrub ihn in Samaria. Und sein Sohn Joahas wurde an seiner Stelle König*.", footnotes: ["℘ V. 30; Kap. 13,1.9.10"] },
      { number: 36, text: "Die Tage aber, die Jehu über Israel in Samaria regierte, <betrugen> 28 Jahre." },
    ]},
    { number: 11, verses: [
      { number: 1, text: "*Als aber Atalja, die Mutter Ahasjas*, sah, dass ihr Sohn tot war*, machte sie sich auf und brachte die ganze königliche Nachkommenschaft um*.", heading: "Herrschaft der Atalja in Jerusalem — Verschwörung des Priesters Jojada gegen sie — Einsetzung des Joasch zum König", footnotes: ["℘ V. 1-3: 2Chr 22,10-12", "℘ Kap. 8,26", "℘ Kap. 9,27", "℘ 2Chr 24,7"] },
      { number: 2, text: "Doch Joscheba, die Tochter des Königs Joram* und Schwester des Ahasja, nahm Joasch*, den Sohn Ahasjas, und stahl ihn aus der Mitte der Königssöhne*, die getötet werden sollten, <und brachte> ihn und seine Amme in die Bettenkammer. So verbargen sie ihn vor Atalja, und er wurde nicht getötet*.", footnotes: ["℘ Kap. 8,16", "℘ 1Chr 3,11", "℘ Jer 36,26", "℘ Kap. 8,19; Jer 33,17"] },
      { number: 3, text: "Und er hielt sich sechs Jahre <lang> bei ihr im Haus des HERRN versteckt*. Atalja aber herrschte als Königin über das Land.", footnotes: ["℘ 2Mo 2,2; Ri 9,5"] },
      { number: 4, text: "*Und im siebten Jahr sandte Jojada hin und ließ die Obersten über Hundert von den Karern* und den Leibwächtern* holen und zu sich ins Haus des HERRN kommen. Und er schloss einen Bund mit ihnen und ließ sie im Haus des HERRN schwören und zeigte ihnen den Sohn des Königs.", footnotes: ["℘ V. 4-20: 2Chr 23", "d. i. ein Volksstamm im Südwesten von Kleinasien; gemeint sind Söldner\n℘ 2Sam 8,18", "w. Läufern\n℘ 1Kö 14,27"] },
      { number: 5, text: "Und er befahl ihnen: Das ist es, was ihr tun sollt: Ein Drittel von euch, die ihr am Sabbat antretet, soll Wache halten im Haus des Königs," },
      { number: 6, text: "und ein Drittel soll am Tor Sur <Wache halten> und ein Drittel am Tor hinter den Leibwächtern* sein. Und ihr sollt abwechselnd Wache beim Haus halten.", footnotes: ["w. Läufern"] },
      { number: 7, text: "Die zwei Abteilungen von euch aber, alle, die am Sabbat abtreten, die sollen im Haus des HERRN Wache halten beim König." },
      { number: 8, text: "Und ihr sollt den König von allen Seiten umgeben, jeder mit seinen Waffen in seiner Hand; und wer in die Reihen eindringen will, soll getötet werden; und ihr sollt bei dem König sein, wenn er herauskommt und wenn er hineingeht." },
      { number: 9, text: "Und die Obersten über Hundert taten nach allem, was der Priester Jojada befohlen hatte. Sie nahmen jeder seine Männer, die am Sabbat antraten, <zusammen> mit denen, die am Sabbat abtraten, und kamen zum Priester Jojada." },
      { number: 10, text: "Und der Priester gab den Obersten über Hundert die Speere und die Schilde, die dem König David gehört hatten <und> die im Haus des HERRN waren*.", footnotes: ["℘ 2Sam 8,7"] },
      { number: 11, text: "Und die Leibwächter* stellten sich auf, jeder mit seinen Waffen in seiner Hand, von der rechten Seite* des Hauses bis zur linken Seite* des Hauses, zum Altar und zum Haus hin, rings um den König herum.", footnotes: ["w. Läufer", "d. i. die Südseite", "d. i. die Nordseite"] },
      { number: 12, text: "Und er führte den Sohn des Königs heraus und setzte ihm die Krone auf* und gab ihm die Ordnung*, und sie machten ihn zum König und salbten ihn*. Und sie klatschten in die Hände und riefen: Es lebe der König*!", footnotes: ["℘ Ps 21,4", "d. i. das Königsprotokoll; andere üs. mit Textänderung: die Armspangen; vgl. 2Sam 1,10\n℘ 5Mo 17,18", "℘ 2Sam 2,4.7; 1Kö 1,34", "℘ Kap. 9,13; 1Kö 1,25"] },
      { number: 13, text: "Als aber Atalja das Geschrei der Leibwächter* und des Volkes hörte, kam sie zum Volk ins Haus des HERRN.", footnotes: ["w. Läufer"] },
      { number: 14, text: "Und sie sah: Siehe, da stand der König auf dem <erhöhten> Standort*, wie <es> Brauch <war>, und die Obersten und die Trompeter <standen> beim König; und alles Volk des Landes war fröhlich und stieß in die Trompeten*. Da zerriss Atalja ihre Kleider und rief: Verschwörung, Verschwörung!", footnotes: ["o. an der Säule\n℘ Kap. 23,3", "℘ Kap. 9,13; 1Kö 1,25"] },
      { number: 15, text: "Der Priester Jojada aber befahl den Obersten über Hundert, den Vorgesetzten des Heeres, und sagte zu ihnen: Führt sie durch die Reihen* hinaus, und wer ihr folgt, den tötet mit dem Schwert! Denn der Priester hatte gesagt: Sie soll nicht im Haus des HERRN getötet werden*.", footnotes: ["o. aus dem Inneren der Vorhöfe", "℘ 2Mo 21,14"] },
      { number: 16, text: "Und sie legten Hand an sie*, und sie ging ins Haus des Königs auf dem Weg, den die Pferde zum Haus des Königs nehmen*. Dort wurde sie getötet*.", footnotes: ["o. Und sie machten ihr Platz. — So verstehen LXX, die syr. und aram. Üs. den Text.", "℘ Neh 3,28", "℘ 1Mo 9,6; Jak 2,13"] },
      { number: 17, text: "Und Jojada schloss den Bund zwischen dem HERRN und dem König und dem Volk, dass sie das Volk des HERRN sein sollten*, und <auch> zwischen dem König und dem Volk*.", footnotes: ["℘ Kap. 23,3; Jos 24,25", "℘ 2Sam 5,3"] },
      { number: 18, text: "Da ging das ganze Volk des Landes in das Haus des Baal und riss es nieder; seine Altäre und seine Götzenbilder zerschlugen sie gründlich*; und Mattan, den Priester des Baal, erschlugen sie vor den Altären*. Und der Priester stellte Wachen am Haus des HERRN auf.", footnotes: ["℘ Kap. 10,26.27; 18,4", "℘ Kap. 10,25; 23,20; 5Mo 13,6.10"] },
      { number: 19, text: "Und er nahm die Obersten über Hundert und die Karer und die Leibwächter* und das ganze Volk des Landes, und sie führten den König aus dem Haus des HERRN hinab und kamen auf dem Weg durch das Tor der Leibwächter* ins Haus des Königs. Und er setzte sich auf den Thron der Könige*.", footnotes: ["w. Läufer", "℘ 1Kö 14,27", "℘ 1Chr 29,23"] },
      { number: 20, text: "Und das ganze Volk des Landes freute sich*, und die Stadt hatte Ruhe*. Atalja aber hatten sie im Haus des Königs mit dem Schwert getötet*.", footnotes: ["℘ Spr 11,10", "o. die Stadt aber verhielt sich still; d. h. sie freute sich nicht mit", "℘ 1Mo 9,6; Jak 2,13"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "*Sieben Jahre war Joasch alt, als er König wurde*.", heading: "Joasch von Juda — Ausbesserung des Tempels", footnotes: ["℘ V. 1-17: 2Chr 24,1-16", "℘ Kap. 13,1.10"] },
      { number: 2, text: "Im siebten Jahr Jehus wurde Joasch König, und er regierte vierzig Jahre in Jerusalem; und der Name seiner Mutter war Zibja, von Beerscheba." },
      { number: 3, text: "Und Joasch tat alle seine Tage, was recht war in den Augen des HERRN*, weil* der Priester Jojada ihn unterwies.", footnotes: ["℘ Kap. 18,3; 22,2; 1Kö 15,11", "o. Und Joasch tat, was recht war in den Augen des HERRN, alle seine Tage, die"] },
      { number: 4, text: "Doch die Höhen wichen nicht; das Volk brachte auf den Höhen noch Schlachtopfer und Rauchopfer dar*.", footnotes: ["℘ Kap. 14,4; 15,4; 16,4; 17,11; 1Kö 3,2"] },
      { number: 5, text: "*Und Joasch sagte zu den Priestern: Alles Geld der heiligen Gaben*, das ins Haus des HERRN gebracht wird — <sowohl> das Geld derer, die <zu den Gemusterten> hinübergehen*, <als auch> das Geld der Personen*, <die vom Priester geschätzt wurden,> jeder seiner Schätzung gemäß*, <als auch> alles Geld, das jemand freiwillig dem Haus des HERRN zukommen lässt* —,", footnotes: ["℘ V. 5-16: vgl. Kap. 22,4-7", "o. heiligen Dinge", "o. das Geld, wie es <beim Händler> gängig ist; vgl. 1Mo 23,16\n℘ 2Mo 30,13", "o. der Seelen", "℘ 3Mo 27,2-8", "w. alles Geld, das einem Menschen aufs Herz kommt, <es> dem Haus des HERRN zukommen zu lassen\n℘ 4Mo 18,15.16; 1Chr 29,6-9"] },
      { number: 6, text: "sollen die Priester an sich nehmen, jeder von seinem Bekannten*. Und sie selbst sollen die Risse des Hauses ausbessern, überall, wo ein Riss gefunden wird.", footnotes: ["o. von seinem Kaufmann"] },
      { number: 7, text: "Und es geschah im 23. Jahr des Königs Joasch, da hatten die Priester die Risse des Hauses <noch> nicht ausgebessert*.", footnotes: ["℘ Hag 1,2"] },
      { number: 8, text: "Da rief der König Joasch den Priester Jojada und die Priester und sagte zu ihnen: Warum bessert ihr die Risse des Hauses nicht aus? Jetzt aber sollt ihr kein Geld von euren Bekannten* <mehr für euch selbst> nehmen, sondern ihr sollt es für die Risse des Hauses abgeben!", footnotes: ["o. Kaufleuten"] },
      { number: 9, text: "Und die Priester willigten ein, kein Geld <mehr> vom Volk anzunehmen und <deshalb> auch die Risse des Hauses nicht <mehr> ausbessern zu müssen." },
      { number: 10, text: "Und der Priester Jojada nahm einen Kasten und bohrte ein Loch in seinen Deckel und stellte ihn neben den Altar, zur Rechten, wenn man in das Haus des HERRN hineingeht*. Dahinein legten die Priester, die an der Schwelle wachten*, alles Geld, das ins Haus des HERRN gebracht wurde.", footnotes: ["℘ Mk 12,41", "℘ Kap. 22,4; 23,4; 1Chr 9,19"] },
      { number: 11, text: "Und es geschah, wenn sie sahen, dass viel Geld in dem Kasten war, dann kamen der Schreiber des Königs und der Hohepriester herauf, und sie banden es zusammen und zählten das Geld, das sich im Haus des HERRN vorfand." },
      { number: 12, text: "Und sie gaben das abgezählte Geld in die Hand der Werkführer, die über das Haus des HERRN eingesetzt waren; und die gaben es weiter an die Zimmerleute und an die Bauleute, die am Haus des HERRN arbeiteten," },
      { number: 13, text: "und an die Maurer und an die Steinhauer, und um Holz und gehauene Steine* zu kaufen, um die Risse des Hauses des HERRN auszubessern, und für alles, was zur Ausbesserung des Hauses ausgegeben werden musste*.", footnotes: ["o. Bruchsteine", "w. hinausging\n℘ Esr 3,7"] },
      { number: 14, text: "Doch wurden für das Haus des HERRN keine silbernen Becken, Messer, Sprengschalen, Trompeten, keinerlei goldenes Gerät oder silbernes Gerät von dem Geld gemacht, das in das Haus des HERRN gebracht wurde;" },
      { number: 15, text: "sondern man gab es den Werkführern, und sie besserten damit das Haus des HERRN aus." },
      { number: 16, text: "Und man rechnete nicht ab mit den Männern, in deren Hand man das Geld gab, damit sie es denen gaben, die die Arbeit taten; denn sie handelten gewissenhaft*.", footnotes: ["o. sondern man handelte auf Treu und Glauben; w. denn in Treue handelten sie\n℘ Neh 13,13; 1Kor 4,2"] },
      { number: 17, text: "Das Geld von Schuldopfern und das Geld von Sündopfern wurde nicht in das Haus des HERRN gebracht; es war für die Priester*.", footnotes: ["So lesen LXX, Vulg. und die syr. Üs.; Mas. T.: sie (die Opfer) waren für die Priester\n℘ 3Mo 7,7.9; 4Mo 18,9"] },
      { number: 18, text: "*Damals zog Hasaël, der König von Aram*, herauf und kämpfte gegen Gat und nahm es ein. Und Hasaël richtete sein Angesicht darauf, gegen Jerusalem hinaufzuziehen.", heading: "Auslieferung der Tempelschätze an die Aramäer durch Joasch — Seine Ermordung", footnotes: ["℘ 2Chr 24,17-27", "℘ Kap. 8,12.13; 2Chr 16,2"] },
      { number: 19, text: "Da nahm Joasch, der König von Juda, alle heiligen Gaben*, die seine Väter Joschafat und Joram und Ahasja, die Könige von Juda, geheiligt hatten, und seine <eigenen> heiligen Gaben* und alles Gold, das sich in den Schatzkammern des Hauses des HERRN und des Hauses des Königs vorfand, und sandte es Hasaël, dem König von Aram*. Da zog der von Jerusalem ab.", footnotes: ["o. heiligen Dinge", "o. heiligen Dinge", "℘ Kap. 16,8; 18,15.16; 1Kö 15,18"] },
      { number: 20, text: "Und die übrige Geschichte* des Joasch und alles, was er getan hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Juda*?", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ Kap. 8,23; 1Kö 14,29"] },
      { number: 21, text: "Und seine Knechte erhoben sich <gegen ihn>*, machten eine Verschwörung und erschlugen Joasch* im Haus des Millo*, wo man nach Silla hinabgeht.", footnotes: ["℘ Kap. 9,14; 10,9; 14,19; 1Kö 15,27", "℘ Kap. 9,27", "»Haus des Millo« bezeichnet einen Raum in Salomos Befestigungsanlage; vgl. 1Kö 9,15.24\n℘ 2Sam 5,9"] },
      { number: 22, text: "Und Josachar, der Sohn Schimats, und Josabad, der Sohn Schomers, seine Knechte*, erschlugen ihn, und er starb*. Und man begrub ihn bei seinen Vätern in der Stadt Davids*. Und sein Sohn Amazja wurde an seiner Stelle König*.", footnotes: ["℘ Kap. 14,5", "℘ Kap. 14,19; 15,10; 2Chr 25,27", "℘ Kap. 8,24; 1Kö 2,10", "℘ Kap. 14,1"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Im 23. Jahr des Joasch, des Sohnes Ahasjas, des Königs von Juda*, wurde Joahas, der Sohn Jehus, König über Israel in Samaria* <und regierte> siebzehn Jahre.", heading: "Joahas von Israel", footnotes: ["℘ Kap. 12,1", "℘ V. 10; Kap. 10,35"] },
      { number: 2, text: "Und er tat, was böse war in den Augen des HERRN; und er folgte den Sünden Jerobeams, des Sohnes Nebats, der Israel zur Sünde verführt hatte: Er wich nicht davon ab*.", footnotes: ["℘ V. 11; 1Kö 14,16"] },
      { number: 3, text: "Da entbrannte der Zorn des HERRN gegen Israel*, und er gab sie in die Hand Hasaëls, des Königs von Aram*, und in die Hand Ben-Hadads, des Sohnes Hasaëls*, alle Tage.", footnotes: ["℘ Kap. 17,20; Ri 2,14", "℘ Kap. 8,12; 3Mo 26,17", "℘ V. 22.24"] },
      { number: 4, text: "Und Joahas besänftigte das Angesicht des HERRN, und der HERR hörte auf ihn*, denn er sah die Bedrängnis Israels*, dass der König von Aram sie <hart> bedrängte. —", footnotes: ["℘ V. 23; 2Chr 33,13; Esr 8,23; Hi 22,27", "℘ Kap. 14,26; 2Mo 3,7.9.16"] },
      { number: 5, text: "Und der HERR gab Israel einen Retter, so dass sie von der Hand Arams loskamen*. Und die Söhne Israel wohnten in ihren Zelten wie früher*.", footnotes: ["℘ V. 25; Kap. 14,27; 1Sam 12,11", "w. wie gestern <und> vorgestern"] },
      { number: 6, text: "Dennoch wichen sie nicht ab von den Sünden des Hauses Jerobeams, der Israel zur Sünde verführt hatte: Sie lebten* darin*, und auch die Aschera blieb in Samaria stehen*. —", footnotes: ["w. gingen", "℘ V. 11; 1Kö 14,16", "℘ Kap. 21,3; 1Kö 16,33; Jes 26,10"] },
      { number: 7, text: "Denn er hatte dem Joahas kein <Kriegs>volk übrig gelassen als nur fünfzig Pferde und zehn Kriegswagen und zehntausend Mann zu Fuß; denn der König von Aram hatte sie vernichtet* und sie gemacht wie Staub beim Dreschen*.", footnotes: ["℘ Kap. 8,12; 3Mo 26,17", "℘ Am 4,10"] },
      { number: 8, text: "Und die übrige Geschichte* des Joahas und alles, was er getan hat, und seine Machttaten, sind die nicht geschrieben im Buch der Geschichte* der Könige von Israel*?", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ Kap. 1,18; 1Kö 14,19"] },
      { number: 9, text: "Und Joahas legte sich zu seinen Vätern, und man begrub ihn in Samaria*. Und sein Sohn Joasch wurde an seiner Stelle König*.", footnotes: ["℘ V. 13", "℘ Kap. 10,35"] },
      { number: 10, text: "Im 37. Jahr des Joasch, des Königs von Juda*, wurde Joasch, der Sohn des Joahas, König über Israel* in Samaria <und regierte> sechzehn Jahre.", heading: "Joasch von Israel — Elisas letzte Weissagung und Tod", footnotes: ["℘ Kap. 12,1", "℘ V. 1; Kap. 14,1.17"] },
      { number: 11, text: "Und er tat, was böse war in den Augen des HERRN; er wich nicht ab von allen Sünden Jerobeams, des Sohnes Nebats, der Israel zur Sünde verführt hatte: Er lebte* darin*.", footnotes: ["w. ging", "℘ V. 2"] },
      { number: 12, text: "Und die übrige Geschichte* des Joasch und alles, was er getan hat, und seine Machttaten, wie er mit Amazja, dem König von Juda, Krieg geführt hat*, ist das nicht geschrieben im Buch der Geschichte* der Könige von Israel*?", footnotes: ["w. der Rest der Begebenheiten", "℘ 2Chr 25,21-24", "w. der Begebenheiten der Tage", "℘ Kap. 1,18; 14,11-16; 1Kö 14,19"] },
      { number: 13, text: "Und Joasch legte sich zu seinen Vätern, und Jerobeam setzte sich auf seinen Thron*. Joasch aber wurde in Samaria begraben bei den Königen von Israel*.", footnotes: ["℘ Kap. 14,23", "℘ V. 9"] },
      { number: 14, text: "Und Elisa erkrankte an seiner Krankheit, an der er <später> starb*. Und Joasch, der König von Israel, kam zu ihm herab und weinte über seinem Gesicht* und sagte: Mein Vater, mein Vater! Wagen Israels und sein Gespann*!", footnotes: ["℘ 1Mo 48,1; 49,33; Sach 1,5", "℘ 1Mo 50,1", "℘ Kap. 2,12"] },
      { number: 15, text: "Da sagte Elisa zu ihm: Hole einen Bogen und Pfeile! Und er holte ihm Bogen und Pfeile." },
      { number: 16, text: "Und er sagte zum König von Israel: Spanne den Bogen*! Da spannte er <ihn>*; und Elisa legte seine Hände auf die Hände des Königs*.", footnotes: ["w. Lass deine Hand über den Bogen fahren", "w. Da ließ er seine Hand <über den Bogen> fahren", "℘ Kap. 4,34"] },
      { number: 17, text: "Und er sagte: Öffne das Fenster nach Osten! Und er öffnete es! Und Elisa sagte: Schieß! Und er schoss. Da sagte er: Pfeil der Rettung von dem HERRN und Pfeil der Rettung gegen Aram*! So wirst du bei Afek* Aram schlagen bis zur Vernichtung.", footnotes: ["o. Pfeil des Sieges für den HERRN und Pfeil des Sieges gegen Aram", "℘ 1Kö 20,26"] },
      { number: 18, text: "Dann sagte er: Nimm die Pfeile! Und er nahm sie. Und er sagte zum König von Israel: Schlag auf die Erde! Und er schlug dreimal und hielt inne." },
      { number: 19, text: "Da wurde der Mann Gottes zornig über ihn und sagte: Zu schlagen war fünf- oder sechsmal, dann hättest du Aram bis zur Vernichtung geschlagen. Jetzt aber wirst du Aram <nur> dreimal schlagen*.", footnotes: ["℘ V. 25"] },
      { number: 20, text: "Und Elisa starb*, und man begrub ihn. Und es kamen moabitische Räuberscharen* ins Land, als das Jahr anfing*.", footnotes: ["℘ 1Mo 48,1; 49,33; Sach 1,5", "℘ Kap. 3,5", "w. als das Jahr kam. — Andere üs. mit Änderung eines Wortes: Jahr für Jahr kamen die Räuberscharen Moabs ins Land"] },
      { number: 21, text: "Und es geschah, als sie einen Mann begruben, siehe, da sahen sie die Räuberschar, und sie warfen den Mann in das Grab Elisas. *Als aber der Mann <da hinein>kam und die Gebeine Elisas berührte*, da wurde er lebendig und stellte sich auf seine Füße*.", footnotes: ["Andere üs. mit Textänderung: und flohen. Als aber der Mann Elisas Gebeine berührte", "Andere üs. mit Textänderung: und flohen. Als aber der Mann Elisas Gebeine berührte", "℘ Kap. 4,35"] },
      { number: 22, text: "Und Hasaël, der König von Aram, bedrängte Israel* alle Tage des Joahas.", footnotes: ["℘ V. 3; Kap. 8,12"] },
      { number: 23, text: "Aber der HERR war ihnen gnädig, erbarmte sich über sie* und wandte sich ihnen zu wegen seines Bundes mit Abraham, Isaak und Jakob*. Er wollte sie nicht vernichten und verstieß sie nicht von seinem Angesicht bis dahin*.", footnotes: ["℘ V. 4; Kap. 14,26; Ri 10,16; Ps 78,38", "℘ 2Mo 2,24; Ps 106,45", "℘ Kap. 17,18"] },
      { number: 24, text: "Und Hasaël, der König von Aram, starb. Und sein Sohn Ben-Hadad wurde an seiner Stelle König*.", footnotes: ["℘ V. 3"] },
      { number: 25, text: "Da entriss Joasch, der Sohn des Joahas, der Hand Ben-Hadads, des Sohnes Hasaëls, die Städte wieder, die dieser aus der Hand seines Vaters Joahas im Krieg genommen hatte. Dreimal schlug ihn Joasch* und brachte die Städte Israels wieder zurück.", footnotes: ["℘ V. 5.19; 1Kö 20,29"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "*Im zweiten Jahr des Joasch, des Sohnes des Joahas, des Königs von Israel*, wurde Amazja* König, der Sohn des Joasch, des Königs von Juda*.", heading: "Amazja von Juda — Sein Krieg mit Joasch von Israel — Ende des Joasch und des Amazja", footnotes: ["℘ 2Chr 25; 26,1.2", "℘ V. 17.23; Kap. 13,10", "℘ 1Chr 3,12", "℘ V. 23; Kap. 12,22"] },
      { number: 2, text: "Er war 25 Jahre alt, als er König wurde, und er regierte 29 Jahre in Jerusalem; und der Name seiner Mutter war Joaddan, von Jerusalem." },
      { number: 3, text: "Und er tat, was recht war in den Augen des HERRN, nur nicht wie sein Vater David*; <aber> nach allem, was sein Vater Joasch getan hatte, tat <auch> er.", footnotes: ["℘ Kap. 18,3; 22,2; 1Kö 15,11"] },
      { number: 4, text: "Nur die Höhen wichen nicht; das Volk brachte auf den Höhen noch Schlachtopfer und Rauchopfer dar*.", footnotes: ["℘ Kap. 12,4"] },
      { number: 5, text: "Und es geschah, als das Königtum in seiner Hand gefestigt war, erschlug er seine Knechte, die den König, seinen Vater, erschlagen hatten*.", footnotes: ["℘ Kap. 12,21.22; 21,24"] },
      { number: 6, text: "Aber die Söhne der Totschläger tötete er nicht, wie es im Buch des Gesetzes des Mose geschrieben steht, wo der HERR geboten hat: Nicht sollen Väter um der Söhne willen getötet werden, und Söhne sollen nicht um der Väter willen getötet werden, sondern jeder soll für seine <eigene> Sünde getötet werden*. —", footnotes: ["℘ 5Mo 24,16"] },
      { number: 7, text: "Er schlug die Edomiter im Salztal*, zehntausend <Mann>; und er nahm <die Stadt> Sela im Kampf ein und gab ihr den Namen Jokteel bis auf diesen Tag.", footnotes: ["℘ Kap. 8,20-22; 2Sam 8,13"] },
      { number: 8, text: "Damals sandte Amazja Boten zu Joasch, dem Sohn des Joahas, des Sohnes Jehus, dem König von Israel, und ließ <ihm> sagen: Auf, lass uns einander ins Angesicht sehen*!", footnotes: ["d. h. im Gefecht\n℘ Ri 9,29"] },
      { number: 9, text: "Da sandte Joasch, der König von Israel, zu Amazja, dem König von Juda, und ließ <ihm> sagen: Der Dornstrauch auf dem Libanon sandte zu der Zeder auf dem Libanon und sprach: Gib meinem Sohn deine Tochter zur Frau! Da liefen die Tiere des Feldes, die auf dem Libanon <lebten>, darüber und zertraten den Dornstrauch*.", footnotes: ["℘ Ri 9,14"] },
      { number: 10, text: "Gewiss, du hast Edom geschlagen, und <darum> erhebt sich* dein Herz*. Genieße <deinen> Ruhm und bleib in deinem Haus! Wozu willst du dich denn mit dem Unglück einlassen? Dass du fällst, du und Juda mit dir?*", footnotes: ["w. erhebt dich", "℘ 5Mo 8,14; 2Chr 26,16; Hes 28,5.17", "℘ Spr 3,30"] },
      { number: 11, text: "Aber Amazja hörte nicht. Da zog Joasch, der König von Israel, herauf; und sie sahen einander ins Angesicht*, er und Amazja, der König von Juda, bei Bet-Schemesch*, das zu Juda gehört.", footnotes: ["d. h. im Gefecht", "℘ Jos 15,10"] },
      { number: 12, text: "Und Juda wurde vor Israel geschlagen; und sie flohen, jeder in sein Zelt." },
      { number: 13, text: "Und Joasch, der König von Israel, nahm Amazja, den König von Juda, den Sohn des Joasch, des Sohnes Ahasjas, bei Bet-Schemesch gefangen. Und er kam nach Jerusalem und riss <eine Bresche> in die Mauer Jerusalems, am Tor Ephraim* <anfangend,> bis an das Ecktor*, vierhundert Ellen.", footnotes: ["℘ Neh 8,16", "℘ Jer 31,38"] },
      { number: 14, text: "Und er nahm alles Gold und Silber und alle Geräte, die sich im Haus des HERRN und in den Schatzkammern des Hauses des Königs vorfanden*, und Geiseln und kehrte nach Samaria zurück.", footnotes: ["℘ 1Kö 14,26"] },
      { number: 15, text: "Und die übrige Geschichte* des Joasch, was er getan hat und seine Machttaten und wie er mit Amazja, dem König von Juda, gekämpft hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Israel*?", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ V. 23.28; Kap. 13,12.13"] },
      { number: 16, text: "Und Joasch legte sich zu seinen Vätern und wurde in Samaria begraben bei den Königen von Israel. Und sein Sohn Jerobeam wurde an seiner Stelle König*.", footnotes: ["℘ V. 23.28; Kap. 13,12.13"] },
      { number: 17, text: "Und Amazja, der Sohn des Joasch, der König von Juda, lebte nach dem Tod des Joasch, des Sohnes des Joahas, des Königs von Israel, <noch> fünfzehn Jahre." },
      { number: 18, text: "Und die übrige Geschichte* Amazjas, ist sie nicht geschrieben im Buch der Geschichte* der Könige von Juda?*", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ Kap. 8,23; 1Kö 14,29"] },
      { number: 19, text: "Und man machte in Jerusalem eine Verschwörung gegen ihn, er aber floh nach Lachisch; da sandten sie <Männer> hinter ihm her bis Lachisch* und töteten ihn dort*.", footnotes: ["℘ Kap. 18,14; Jos 10,31", "℘ Kap. 9,27; 15,10"] },
      { number: 20, text: "Und sie hoben ihn auf die Pferde, und er wurde in Jerusalem bei seinen Vätern begraben, in der Stadt Davids*.", footnotes: ["℘ Kap. 8,24; 1Kö 2,10"] },
      { number: 21, text: "Und das ganze Volk von Juda nahm Asarja* — der war sechzehn Jahre alt —, und sie machten ihn zum König anstelle seines Vaters Amazja*.", footnotes: ["℘ 1Chr 3,12; Mt 1,8", "℘ Kap. 15,1.2"] },
      { number: 22, text: "Er baute Elat* <wieder auf> und brachte es an Juda zurück*, nachdem der König sich zu seinen Vätern gelegt hatte.", footnotes: ["℘ 5Mo 2,8; 1Kö 9,26", "℘ Kap. 16,6"] },
      { number: 23, text: "Im fünfzehnten Jahr Amazjas, des Sohnes des Joasch, des Königs von Juda*, wurde Jerobeam, der Sohn des Joasch, des Königs von Israel, König in Samaria* und <regierte> 41 Jahre.", heading: "Jerobeam II. von Israel", footnotes: ["℘ V. 1.17", "℘ V. 16; Kap. 13,13; 15,1; 1Chr 5,17; Hos 1,1; Am 1,1; 7,10"] },
      { number: 24, text: "Und er tat, was böse war in den Augen des HERRN; er wich nicht ab von allen Sünden Jerobeams, des Sohnes Nebats, der Israel zur Sünde verführt hatte*.", footnotes: ["℘ Kap. 3,3; 1Kö 14,16; Am 7,9-13"] },
      { number: 25, text: "Er stellte das Gebiet Israels wieder her, vom Zugang nach Hamat* bis an das Meer der Ebene*, nach dem Wort des HERRN, des Gottes Israels, das er geredet hatte durch seinen Knecht Jona, den Sohn des Amittai, den Propheten*, der von Gat-Hefer war*.", footnotes: ["o. von Lebo-Hamat\n℘ 4Mo 34,8", "o. an das Meer der Araba; d. i. das Tote Meer; zu Araba vgl. Anm. zu 5Mo 1,1\n℘ 5Mo 3,17", "℘ Jon 1,1", "℘ Jos 19,13"] },
      { number: 26, text: "Denn der HERR sah das überaus bittere Elend Israels*, und dass dahin war der Unmündige und dahin der Mündige* und dass kein Helfer da war für Israel*.", footnotes: ["T. in Anlehnung an LXX; Mas. T.: dass das Leiden Israels überaus widerspenstig war\n℘ Kap. 13,4.23", "o. dahin der Sklave und dahin der Freie; w. dahin der Festgehaltene und dahin der Losgelassene\n℘ 5Mo 32,36", "℘ Ps 107,12; Hes 22,30"] },
      { number: 27, text: "Der HERR hatte nicht gesagt, dass er den Namen Israels unter dem Himmel auslöschen wolle*. So rettete er sie durch die Hand Jerobeams, des Sohnes des Joasch*.", footnotes: ["℘ 1Sam 12,22", "℘ Kap. 13,5"] },
      { number: 28, text: "Und die übrige Geschichte* Jerobeams und alles, was er getan hat, und seine Machttaten, wie er Krieg geführt hat und wie er Damaskus und Hamat, die Juda gehört hatten*, an Israel zurückgebracht hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Israel?*", footnotes: ["w. der Rest der Begebenheiten", "℘ 2Sam 8,6; 2Chr 8,3.4; Am 1,5", "w. der Begebenheiten der Tage", "℘ V. 16; Kap. 1,18; 1Kö 14,19"] },
      { number: 29, text: "Und Jerobeam legte sich zu seinen Vätern, zu den Königen von Israel. Und sein Sohn Secharja wurde an seiner Stelle König*.", footnotes: ["℘ Kap. 10,30; 15,8"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "*Im 27. Jahr Jerobeams, des Königs von Israel*, wurde Asarja* König, der Sohn Amazjas, des Königs von Juda.", heading: "Asarja von Juda", footnotes: ["℘ 2Chr 26", "℘ Kap. 14,23", "In V. 13.30.32 wird Asarja Usija genannt; vgl. 2Chr 26,1.\n℘ V. 8.13.17.27.32; Kap. 14,21; Jes 1,1"] },
      { number: 2, text: "Sechzehn Jahre war er alt, als er König wurde, und er regierte 52 Jahre in Jerusalem; und der Name seiner Mutter war Jecholja, von Jerusalem." },
      { number: 3, text: "Und er tat, was recht war in den Augen des HERRN, nach allem, was sein Vater Amazja getan hatte*.", footnotes: ["℘ V. 34; Kap. 12,3"] },
      { number: 4, text: "Doch die Höhen wichen nicht; das Volk brachte noch auf den Höhen Schlachtopfer und Rauchopfer dar*.", footnotes: ["℘ V. 35; Kap. 12,4"] },
      { number: 5, text: "Und der HERR schlug den König, und er war aussätzig bis zum Tag seines Todes; und er wohnte in einem abgesonderten Haus*. Jotam* aber, der Sohn des Königs, war über das Haus <des Königs gesetzt worden> und richtete das Volk des Landes.", footnotes: ["o. im Haus der Befreiung <von den Staatsgeschäften>; o. im Haus der Freiheit; als verhüllende Rede für eine Art »geschlossene Station«\n℘ 3Mo 13,46", "℘ V. 32; 1Chr 3,12"] },
      { number: 6, text: "Und die übrige Geschichte* Asarjas und alles, was er getan hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Juda?*", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ Kap. 8,23; 1Kö 14,29"] },
      { number: 7, text: "Und Asarja legte sich zu seinen Vätern, und man begrub ihn bei seinen Vätern* in der Stadt Davids. Und sein Sohn Jotam wurde an seiner Stelle König.", footnotes: ["℘ Jes 6,1"] },
      { number: 8, text: "Im 38. Jahr Asarjas, des Königs von Juda*, wurde Secharja, der Sohn Jerobeams, König über Israel* in Samaria <und regierte> sechs Monate.", heading: "Secharja, Schallum, Menahem, Pekachja und Pekach von Israel", footnotes: ["℘ V. 1", "℘ Kap. 14,29"] },
      { number: 9, text: "Und er tat, was böse war in den Augen des HERRN, so wie seine Väter getan hatten; er wich nicht ab von den Sünden Jerobeams, des Sohnes Nebats, der Israel zur Sünde verführt hatte*.", footnotes: ["℘ V. 24.28; Kap. 3,3; 1Kö 14,16"] },
      { number: 10, text: "Und Schallum, der Sohn des Jabesch, verschwor sich gegen ihn und erschlug ihn vor dem Volk* und tötete ihn*. Und er wurde an seiner Stelle König*.", footnotes: ["Eine LXX-Ausgabe liest: und erschlug ihn in Jibleam", "℘ Kap. 12,21.22; 14,19; Hos 7,7; Am 7,9", "℘ V. 14.22.25.30; 1Kö 16,10; Hos 8,4"] },
      { number: 11, text: "Und die übrige Geschichte* Secharjas, siehe, sie ist geschrieben im Buch der Geschichte* der Könige von Israel*.", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ Kap. 1,18; 1Kö 14,19"] },
      { number: 12, text: "Das ist das Wort des HERRN, das er zu Jehu geredet hatte: Söhne der vierten <Generation> sollen dir auf dem Thron Israels sitzen*. So ist es auch geschehen.", footnotes: ["℘ Kap. 10,30; 1Sam 3,19"] },
      { number: 13, text: "Schallum, der Sohn des Jabesch, wurde König im 39. Jahr Usijas, des Königs von Juda*; und er regierte einen vollen Monat in Samaria*.", footnotes: ["℘ V. 1", "℘ Hos 10,3.7"] },
      { number: 14, text: "Da zog Menahem, der Sohn Gadis, von Tirza* herauf und kam nach Samaria; und er erschlug Schallum, den Sohn des Jabesch, in Samaria und tötete ihn. Und er wurde an seiner Stelle König*.", footnotes: ["℘ 1Kö 14,17", "℘ V. 10.17"] },
      { number: 15, text: "Und die übrige Geschichte* Schallums und seine Verschwörung, die er gemacht hat, siehe, das ist geschrieben im Buch der Geschichte* der Könige von Israel*.", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ V. 11"] },
      { number: 16, text: "Damals schlug Menahem <die Stadt> Tifsach und alles, was darin war, und ihr Gebiet, von Tirza aus. Weil man ihm <die Tore> nicht geöffnet hatte, schlug er <die Stadt>; alle ihre Schwangeren schlitzte er auf*.", footnotes: ["℘ Kap. 8,12; Am 1,13"] },
      { number: 17, text: "Im 39. Jahr Asarjas, des Königs von Juda*, wurde Menahem, der Sohn Gadis, König über Israel* <und regierte> zehn Jahre in Samaria.", footnotes: ["℘ V. 1", "℘ V. 14"] },
      { number: 18, text: "Und er tat, was böse war in den Augen des HERRN; er wich nicht ab von den Sünden Jerobeams, des Sohnes Nebats, der Israel zur Sünde verführt hatte*, *alle seine Tage*.", footnotes: ["℘ V. 24.28; Kap. 3,3; 1Kö 14,16", "LXX: In seinen Tagen 19 kam Pul", "℘ V. 9"] },
      { number: 19, text: "<Und> es kam Pul*, der König von Assur, gegen das Land. Und Menahem gab Pul tausend Talente Silber, damit dessen Hände mit ihm sein sollten, das Königtum in seiner Hand zu befestigen*.", footnotes: ["LXX: In seinen Tagen 19 kam Pul", "℘ Kap. 16,8; Hos 5,13"] },
      { number: 20, text: "Und Menahem legte das Geld <als Steuer> auf Israel, auf alle vermögenden* Leute, um es dem König von Assur zu geben*: fünfzig Schekel Silber auf jeden Mann. Da kehrte der König von Assur um und blieb nicht dort im Land.", footnotes: ["o. angesehenen", "℘ Kap. 23,35"] },
      { number: 21, text: "Und die übrige Geschichte* Menahems und alles, was er getan hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Israel*?", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ Kap. 1,18; 1Kö 14,19"] },
      { number: 22, text: "Und Menahem legte sich zu seinen Vätern. Und sein Sohn Pekachja wurde an seiner Stelle König*.", footnotes: ["℘ V. 10"] },
      { number: 23, text: "Im fünfzigsten Jahr Asarjas, des Königs von Juda, wurde Pekachja, der Sohn Menahems, König über Israel in Samaria <und regierte> zwei Jahre." },
      { number: 24, text: "Und er tat, was böse war in den Augen des HERRN; er wich nicht ab von den Sünden Jerobeams, des Sohnes Nebats, der Israel zur Sünde verführt hatte*.", footnotes: ["℘ V. 9; Kap. 1,18"] },
      { number: 25, text: "Gegen ihn verschwor sich Pekach, der Sohn Remaljas, einer seiner Offiziere*, und erschlug ihn in Samaria in dem Palast des Königshauses, <außerdem> den Argob und den Arje; mit ihm waren fünfzig Mann von den Söhnen der Gileaditer. Und er tötete ihn und wurde an seiner Stelle König*.", footnotes: ["w. sein Dritter; d. i. der dritte Mann auf einem Kriegswagen", "℘ V. 10"] },
      { number: 26, text: "Und die übrige Geschichte* Pekachjas und alles, was er getan hat, siehe, das ist geschrieben im Buch der Geschichte* der Könige von Israel*.", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ Kap. 1,18; 1Kö 14,19"] },
      { number: 27, text: "Im 52. Jahr Asarjas, des Königs von Juda*, wurde Pekach, der Sohn Remaljas, König über Israel* in Samaria <und regierte> zwanzig Jahre.", footnotes: ["℘ V. 1", "℘ V. 37; Jes 7,1.4.9"] },
      { number: 28, text: "Und er tat, was böse war in den Augen des HERRN; er wich nicht ab von den Sünden Jerobeams, des Sohnes Nebats, der Israel zur Sünde verführt hatte*.", footnotes: ["℘ V. 9; Kap. 1,18"] },
      { number: 29, text: "In den Tagen Pekachs, des Königs von Israel, kam Tiglat-Pileser, der König von Assur*, und nahm Ijon ein und Abel-Bet-Maacha* und Janoach und Kedesch* und Hazor* und Gilead und Galiläa, das ganze Land Naftali*, und führte die Bewohner* gefangen fort nach Assur*.", footnotes: ["℘ Kap. 16,7; 2Chr 28,20", "℘ 2Sam 20,15", "℘ Jos 19,37", "℘ Jos 11,1", "℘ Jes 8,23", "w. führte sie", "℘ Kap. 17,6; 8,11; 19,11; Ri 18,30; 1Chr 5,26; Hes 23,9; Am 5,27; 6,15"] },
      { number: 30, text: "Und Hoschea, der Sohn Elas, machte eine Verschwörung gegen Pekach, den Sohn Remaljas, und erschlug ihn und tötete ihn*. Und er wurde an seiner Stelle König* im zwanzigsten Jahr Jotams*, des Sohnes Usijas.", footnotes: ["℘ Jes 7,16", "℘ V. 10; Kap. 17,1", "℘ V. 32"] },
      { number: 31, text: "Und die übrige Geschichte* Pekachs und alles, was er getan hat, siehe, das ist geschrieben im Buch der Geschichte* der Könige von Israel*.", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ Kap. 1,18; 1Kö 14,19"] },
      { number: 32, text: "*Im zweiten Jahr Pekachs, des Sohnes Remaljas, des Königs von Israel, wurde Jotam König, der Sohn Usijas, des Königs von Juda*.", heading: "Jotam von Juda", footnotes: ["℘ 2Chr 27", "℘ V. 5.7.30; 1Chr 5,17; Mi 1,1; Mt 1,9"] },
      { number: 33, text: "Er war 25 Jahre alt, als er König wurde, und er regierte sechzehn Jahre in Jerusalem; und der Name seiner Mutter war Jeruscha, die Tochter Zadoks." },
      { number: 34, text: "Und er tat, was recht war in den Augen des HERRN; er tat nach allem, was sein Vater Usija getan hatte*.", footnotes: ["℘ V. 3"] },
      { number: 35, text: "Doch die Höhen wichen nicht: Das Volk brachte auf den Höhen noch Schlachtopfer und Rauchopfer dar*. Er baute das obere Tor des Hauses des HERRN.", footnotes: ["℘ V. 4"] },
      { number: 36, text: "Und die übrige Geschichte* Jotams und alles, was er getan hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Juda?*", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ Kap. 8,23; 1Kö 14,29"] },
      { number: 37, text: "In jenen Tagen begann der HERR, Rezin, den König von Aram, und Pekach, den Sohn Remaljas*, gegen Juda zu senden*.", footnotes: ["℘ V. 27", "℘ Kap. 16,5"] },
      { number: 38, text: "Und Jotam legte sich zu seinen Vätern und wurde bei seinen Vätern begraben in der Stadt seines Vaters David*. Und sein Sohn Ahas wurde an seiner Stelle König*.", footnotes: ["℘ Kap. 8,24; 1Kö 2,10", "℘ Kap. 16,1"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "*Im siebzehnten Jahr Pekachs, des Sohnes Remaljas, wurde Ahas* König, der Sohn Jotams, des Königs von Juda*.", heading: "Ahas von Juda — Seine Unterwerfung unter Assur und sein Götzendienst", footnotes: ["℘ 2Chr 28", "℘ 1Chr 3,13; Mt 1,9", "℘ Kap. 15,38; 17,1; Jes 7,1.3.10"] },
      { number: 2, text: "Zwanzig Jahre war Ahas alt, als er König wurde, und er regierte sechzehn Jahre in Jerusalem. Und er tat nicht, was recht war in den Augen des HERRN, seines Gottes, wie sein Vater David;" },
      { number: 3, text: "sondern er ging auf dem Weg der Könige von Israel*. Er ließ sogar seinen Sohn durchs Feuer gehen* nach den Gräueln der Nationen, die der HERR vor den Söhnen Israel vertrieben hatte*.", footnotes: ["℘ Kap. 8,18", "℘ Kap. 17,17; 21,6; 23,10; Ps 106,37; Hes 20,26", "℘ Kap. 17,8; 21,2.9; 3Mo 18,21.24"] },
      { number: 4, text: "Und er brachte Schlachtopfer und Rauchopfer dar auf den Höhen und auf den Hügeln und unter jedem grünen Baum.*", footnotes: ["℘ Kap. 12,4; 1Kö 14,23; Jes 57,5; Hes 43,7"] },
      { number: 5, text: "Damals zogen Rezin, der König von Aram, und Pekach, der Sohn Remaljas, der König von Israel, nach Jerusalem hinauf zum Kampf*; und sie belagerten Ahas, konnten aber nicht <gegen ihn> kämpfen*.", footnotes: ["℘ Kap. 15,37", "d. h. vielleicht: Sie konnten die Stadt nicht erobern; o. sie konnten Ahas nicht zum Kampf zwingen\n℘ Jes 7,1"] },
      { number: 6, text: "In dieser Zeit brachte Rezin, der König von Aram, Elat wieder an Aram und trieb die Juden aus Elat hinaus; und es kamen Edomiter* nach Elat, und <sie> haben sich dort niedergelassen bis auf diesen Tag*.", footnotes: ["die syr. und aram. Üs. lesen mit der Schreibform: die Aramäer", "℘ Kap. 14,22"] },
      { number: 7, text: "Da sandte Ahas Boten an Tiglat-Pileser, den König von Assur*, und ließ <ihm> sagen: Dein Knecht und dein Sohn bin ich*. Komm herauf und rette mich aus der Hand des Königs von Aram und aus der Hand des Königs von Israel, die sich gegen mich erhoben haben!*", footnotes: ["℘ Kap. 15,29", "℘ Jer 13,21", "℘ Kap. 18,7; Hos 7,11"] },
      { number: 8, text: "Und Ahas nahm das Silber und das Gold, das sich in dem Haus des HERRN und in den Schatzkammern des Königshauses vorfand*, und sandte es als Geschenk dem König von Assur*.", footnotes: ["℘ Kap. 18,15", "℘ Kap. 12,19; 15,19.20; 17,3"] },
      { number: 9, text: "Da hörte der König von Assur auf ihn*. Und der König von Assur zog hinauf gegen Damaskus und nahm es ein und führte seine Einwohner* gefangen fort nach Kir*; Rezin aber tötete er*.", footnotes: ["℘ 2Chr 16,4", "w. führte es", "℘ Jes 22,6; Am 1,5", "℘ Jes 7,16; 9,10; 10,9"] },
      { number: 10, text: "Und der König Ahas zog Tiglat-Pileser, dem König von Assur, entgegen, nach Damaskus. Und als er den Altar sah, der in Damaskus war, da schickte der König Ahas dem Priester Uria eine Nachbildung des Altars und seine Maße* seiner ganzen Ausführung entsprechend*.", footnotes: ["w. seine Bauart", "℘ 5Mo 12,30"] },
      { number: 11, text: "Und der Priester Uria* baute den Altar ganz nach dem, was der König Ahas aus Damaskus geschickt hatte. So machte ihn der Priester Uria, bis der König Ahas aus Damaskus kam.", footnotes: ["℘ Kap. 21,4; 2Chr 33,4; Jes 8,2; Mal 2,7.8"] },
      { number: 12, text: "Und als der König aus Damaskus kam, da sah der König den Altar; und der König trat an den Altar und stieg auf ihn hinauf*.", footnotes: ["℘ 1Kö 12,33"] },
      { number: 13, text: "Dann ließ er sein Brandopfer und sein Speisopfer als Rauch aufsteigen und goss sein Trankopfer aus und sprengte das Blut seiner Heilsopfer* an den Altar.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 14, text: "Den bronzenen Altar aber, der vor dem HERRN <stand>*, den rückte er von der Vorderseite des Hauses weg, von <der Stelle> zwischen dem <neuen> Altar und dem Haus des HERRN, und setzte ihn an die Nordseite des <neuen> Altars*.", footnotes: ["℘ 2Chr 4,1", "℘ Hes 43,8"] },
      { number: 15, text: "Und der König Ahas befahl dem Priester Uria: Auf dem großen Altar bringe das Morgenbrandopfer und das Abendspeisopfer dar* sowie das Brandopfer des Königs samt seinem Speisopfer und das Brandopfer des ganzen Volkes des Landes samt ihren Speisopfern und ihren Trankopfern; und alles Blut der Brandopfer und alles Blut der Schlachtopfer sollst du daran sprengen! Der bronzene Altar aber soll für mich sein, dass ich <auf ihm> Opferschau vornehme*.", footnotes: ["w. Auf dem großen Altar lass das Morgenbrandopfer und das Abendspeisopfer als Rauch aufsteigen\n℘ 2Mo 29,39; 1Kö 7,23-39", "o. Um den bronzenen Altar aber will ich mich kümmern"] },
      { number: 16, text: "Und der Priester Uria tat nach allem, was der König Ahas <ihm> befohlen hatte*.", footnotes: ["℘ Kap. 21,4; 2Chr 33,4; Jes 8,2; Mal 2,7.8"] },
      { number: 17, text: "Und der König Ahas brach die <Schluss>leisten an den Gestellen ab und entfernte die Kessel, die darauf waren*. Und er ließ das Meer von den bronzenen Rindern, die darunter waren, herunternehmen und setzte <es> auf ein Steinpflaster.", footnotes: ["℘ 2Chr 29,19"] },
      { number: 18, text: "Und die überdachte Sabbathalle, die man am Haus gebaut hatte, und den äußeren Eingang des Königs* veränderte er am Haus* des HERRN wegen des Königs von Assur.", footnotes: ["℘ 1Chr 9,18; Hes 44,3", "Andere üs. mit Textänderung: entfernte er aus dem Haus"] },
      { number: 19, text: "Und die übrige Geschichte* des Ahas, was er getan hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Juda?*", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ Kap. 8,23; 1Kö 14,29"] },
      { number: 20, text: "Und Ahas legte sich zu seinen Vätern und wurde bei seinen Vätern begraben in der Stadt Davids*. Und sein Sohn Hiskia wurde an seiner Stelle König*.", footnotes: ["℘ Kap. 8,24; 1Kö 2,10", "℘ Kap. 18,1"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Im zwölften Jahr des Ahas, des Königs von Juda*, wurde Hoschea, der Sohn Elas, in Samaria König über Israel* <und regierte> neun Jahre.", heading: "Hoschea, letzter König von Israel — Wegführung nach Assur", footnotes: ["℘ Kap. 16,1", "℘ Kap. 15,30; 18,1"] },
      { number: 2, text: "Und er tat, was böse war in den Augen des HERRN*, doch nicht wie die Könige von Israel, die vor ihm gewesen waren*.", footnotes: ["℘ Kap. 21,2", "℘ 1Kö 16,30"] },
      { number: 3, text: "*Gegen ihn zog Salmanassar, der König von Assur, herauf*; und Hoschea wurde sein Knecht und entrichtete ihm Tribut*.", footnotes: ["℘ V. 3-23: Kap. 18,9-12", "℘ 3Mo 26,25", "℘ Kap. 16,8; 18,7"] },
      { number: 4, text: "Aber der König von Assur entdeckte eine Verschwörung bei Hoschea; denn der hatte Boten an So, den König von Ägypten, gesandt und hatte dem König von Assur keinen Tribut <mehr> hinaufgebracht* wie <bisher> Jahr für Jahr. Da verhaftete ihn der König von Assur und warf ihn gefesselt* ins Gefängnis.", footnotes: ["℘ Hos 8,10; 10,4; 12,2", "w. fesselte ihn"] },
      { number: 5, text: "Dann zog der König von Assur durch das ganze Land und zog herauf nach Samaria und belagerte es drei Jahre lang*.", footnotes: ["℘ Kap. 6,24"] },
      { number: 6, text: "Im neunten Jahr Hoscheas nahm der König von Assur Samaria ein* und führte Israel gefangen fort nach Assur*. Und er ließ sie wohnen in Halach und am Habor, dem Strom von Gosan, und in den Städten Mediens*.", footnotes: ["℘ Kap. 18,34; 21,13; 1Kö 8,46; Jes 8,4; 17,4", "℘ V. 23; Kap. 15,29; 5Mo 28,36; 29,27; Hos 1,4; 9,3", "℘ 1Chr 5,26; Jer 50,17"] },
      { number: 7, text: "Und das geschah, weil die Söhne Israel gesündigt hatten gegen den HERRN, ihren Gott, der sie aus dem Land Ägypten hatte heraufkommen lassen aus der Hand des Pharao, des Königs von Ägypten*, und weil sie andere Götter fürchteten*", heading: "Die Schuld Israels", footnotes: ["℘ Ps 78,12-14", "℘ 2Mo 20,2-5; Ps 106,36; Jes 57,5.7; Hos 4,12.13"] },
      { number: 8, text: "und in den Ordnungen der Nationen lebten*, die der HERR vor den Söhnen Israel vertrieben hatte*, und <in den Ordnungen> der Könige von Israel, die <diese> eingeführt hatten*.", footnotes: ["w. gingen", "℘ 2Mo 23,24; 5Mo 18,9", "℘ Kap. 16,3; 3Mo 26,1; 1Kö 12,28"] },
      { number: 9, text: "Und die Söhne Israel ersannen gegen den HERRN, ihren Gott, Dinge, die nicht recht waren*; und sie bauten sich Höhen in all ihren Städten*, vom Wachtturm bis zur befestigten Stadt.", footnotes: ["℘ Jes 29,15; Hes 8,12; Joh 3,20", "℘ Kap. 18,8; Ps 78,58; Hes 20,28"] },
      { number: 10, text: "Und sie errichteten sich Gedenksteine* und Ascherim auf jedem hohen Hügel und unter jedem grünen Baum*,", footnotes: ["hebr. mazzebot; das sind kultisch verehrte Steine", "℘ 3Mo 26,1; 5Mo 16,22; 1Kö 14,23; Jer 3,6"] },
      { number: 11, text: "und sie brachten dort auf allen Höhen Rauchopfer dar* wie die Nationen, die der HERR vor ihnen gefangen weggeführt hatte*. Und sie taten böse Dinge, um den HERRN zum Zorn zu reizen*.", footnotes: ["℘ Kap. 12,4; Hos 9,10", "℘ 2Mo 23,24; 5Mo 18,9", "℘ 1Kö 14,15; 5Mo 32,16"] },
      { number: 12, text: "Und sie dienten den Götzen*, von denen der HERR ihnen gesagt hatte: So etwas sollt ihr nicht tun*!", footnotes: ["w. Mistkugeln, o. Klötzen; ein verächtlicher Ausdruck", "℘ 2Mo 20,2-5; Hes 20,28"] },
      { number: 13, text: "Und der HERR hatte Israel und Juda durch alle Propheten <und> jeden Seher gewarnt* und hatte gesagt: Kehrt um von euren bösen Wegen* und bewahrt meine Gebote, meine Ordnungen, dem ganzen Gesetz gemäß, das ich euren Vätern geboten und das ich euch durch meine Knechte, die Propheten, gesandt habe!", footnotes: ["o. Aber der HERR war gegen Israel und gegen Juda als Zeuge aufgetreten durch alle Propheten und Seher\n℘ Kap. 21,10; Ri 6,8.10; 1Sam 9,9; 1Kö 16,1; 2Chr 36,15; Jer 11,7; 25,3; Hos 12,11", "℘ Hi 11,14; Jes 1,16; Jer 18,11"] },
      { number: 14, text: "Aber sie hörten nicht, sondern verhärteten ihren Nacken* gleich dem Nacken ihrer Väter, die dem HERRN, ihrem Gott, nicht geglaubt hatten*.", footnotes: ["℘ 2Mo 16,28; 2Chr 24,19; Jer 7,26; Hes 2,3; 12,2.3", "℘ Neh 9,29; Ps 78,22; Jer 3,7; Hos 11,2"] },
      { number: 15, text: "Und sie verwarfen seine Ordnungen und seinen Bund, den er mit ihren Vätern geschlossen*, und seine Warnungen, mit denen er sie gewarnt hatte*, und liefen der Nichtigkeit* hinterher* — und wurden <selber> nichtig — und <liefen> den Nationen nach, die rings um sie her waren, von denen der HERR ihnen geboten hatte, nicht wie sie zu tun*.", footnotes: ["℘ 5Mo 29,24; Ps 78,10", "o. Zeugnisse, mit denen er gegen sie als Zeuge ausgesagt hatte\n℘ 2Mo 16,28; 2Chr 24,19; Jer 7,26; Hes 2,3; 12,2.3", "o. dem Windhauch; d. i. eine Bezeichnung für Götzen", "℘ 1Sam 12,21; Jer 2,5", "℘ 5Mo 12,30; Jer 44,23"] },
      { number: 16, text: "Und sie verließen alle Gebote des HERRN, ihres Gottes, und machten sich ein Gussbild*, zwei Kälber*, und machten eine Aschera* und warfen sich vor dem ganzen Heer des Himmels nieder* und dienten dem Baal*.", footnotes: ["℘ Jes 2,8", "℘ Kap. 16,3; 3Mo 26,1; 1Kö 12,28", "℘ Kap. 16,3; 3Mo 26,1; 1Kö 12,28", "℘ Kap. 21,3; 5Mo 4,19", "℘ Kap. 10,18; 1Kö 22,54"] },
      { number: 17, text: "Sie ließen ihre Söhne und ihre Töchter durchs Feuer gehen* und trieben Wahrsagerei und Zauberei* und verkauften sich, zu tun, was böse war in den Augen des HERRN*, um ihn zum Zorn zu reizen*.", footnotes: ["℘ V. 31; Kap. 16,3", "℘ Kap. 21,6; 3Mo 19,26.31", "℘ 1Kö 21,20; Hos 12,15", "℘ 1Kö 14,15; 5Mo 32,16"] },
      { number: 18, text: "Da wurde der HERR sehr zornig über Israel und schaffte sie fort von seinem Angesicht*. Nichts blieb übrig als allein der Stamm Juda.", footnotes: ["℘ Kap. 13,23; 21,14; 23,27; 24,3; 5Mo 32,20; Jos 23,13; Ri 18,30; Ps 51,13; Jer 7,15; 52,3; Hos 12,3"] },
      { number: 19, text: "<Aber> auch Juda beachtete nicht die Gebote des HERRN, seines Gottes, sondern sie lebten* in den Ordnungen Israels, die sie <selber> eingeführt hatten*.", footnotes: ["w. gingen", "℘ 1Kö 14,22; Jer 3,8; Hes 23,31; Am 2,4"] },
      { number: 20, text: "Da verwarf der HERR die ganze Nachkommenschaft Israels*, und er demütigte sie und gab sie in die Hand von Plünderern*, bis er sie von seinem Angesicht verstoßen hatte*.", footnotes: ["℘ Jes 2,6; Jer 6,30; Hos 1,6", "℘ Kap. 13,3; Neh 9,27.28; Ps 80,13.14.17", "℘ Kap. 13,23; 21,14; 23,27; 24,3; 5Mo 32,20; Jos 23,13; Ri 18,30; Ps 51,13; Jer 7,15; 52,3; Hos 12,3"] },
      { number: 21, text: "Denn er hatte Israel vom Haus Davids losgerissen*, und sie hatten Jerobeam, den Sohn Nebats, zum König gemacht. Jerobeam aber hatte Israel davon abgebracht, dem HERRN nachzufolgen*, und hatte sie zu einer großen Sünde verführt*.", footnotes: ["℘ 1Kö 12,19", "w. hatte Israel von <der Nachfolge> hinter dem HERRN her abgebracht", "℘ 1Kö 14,16; 2Kö 3,3"] },
      { number: 22, text: "Und die Söhne Israel lebten* in allen Sünden Jerobeams, die er getan hatte. Sie wichen nicht davon ab*,", footnotes: ["w. gingen", "℘ Kap. 10,31"] },
      { number: 23, text: "bis dass der HERR Israel von seinem Angesicht fortgeschafft hatte*, so wie er durch alle seine Knechte, die Propheten, geredet hatte*. So wurde Israel aus seinem Land gefangen nach Assur weggeführt*<; und das ist so> bis auf den heutigen Tag*.", footnotes: ["℘ 1Kö 14,16; 2Kö 3,3", "℘ 1Kö 14,16; 2Kö 3,3", "℘ V. 6; Kap. 25,21; 1Kö 9,7; Jes 7,8; Am 5,27; Mi 1,5", "℘ Neh 9,32"] },
      { number: 24, text: "Und der König von Assur brachte <Leute> aus Babel und aus Kuta und aus Awa und aus Hamat* und aus Sefarwajim* und ließ sie anstelle der Söhne Israel in den Städten Samarias wohnen. Und sie nahmen Samaria in Besitz und wohnten in seinen Städten*.", heading: "Entstehung des Volkes der Samaritaner", footnotes: ["℘ Jes 11,11", "℘ Kap. 18,34", "℘ Esr 4,2.9.10; Mt 10,5"] },
      { number: 25, text: "Und es geschah, als sie anfingen, dort zu wohnen, fürchteten sie den HERRN nicht. Da sandte der HERR Löwen unter sie, die unter ihnen mordeten." },
      { number: 26, text: "Und man sagte zum König von Assur: Die Nationen, die du weggeführt und in den Städten Samarias hast wohnen lassen, kennen nicht die Verehrung*<, die> dem Gott des Landes <gebührt>. So hat er Löwen unter sie gesandt, und siehe, die töten sie, weil sie die Verehrung* des Gottes des Landes nicht kennen.", footnotes: ["o. den Brauch; o. das Recht", "o. den Brauch; o. das Recht"] },
      { number: 27, text: "Da befahl der König von Assur: Lasst einen der Priester, die ihr von dort gefangen weggeführt habt, dorthin <zurück>gehen, dass er hingeht und dort wohnt*! Und er lehre sie die Verehrung* des Gottes des Landes*!", footnotes: ["so mit einer LXX-Ausgabe, der syr. Üs. und der Vulg.; Mas. T.: dass sie hingehen und wohnen", "o. den Brauch; o. das Recht", "℘ Esr 7,25"] },
      { number: 28, text: "Da kam einer der Priester, die man aus Samaria gefangen weggeführt hatte, und wohnte in Bethel* und lehrte sie, wie sie den HERRN fürchten sollten.", footnotes: ["℘ 1Kö 12,31.33"] },
      { number: 29, text: "Doch machten sie sich — Nation für Nation — ihre <eigenen> Götter und stellten sie in die Höhenhäuser, die die Samaritaner — Nation für Nation — in ihren Städten gemacht hatten, in denen sie wohnten*.", footnotes: ["℘ Mi 4,5"] },
      { number: 30, text: "Und die Leute von Babel machten Sukkot-Benot, die Leute von Kuta machten Nergal, die Leute von Hamat machten Aschima," },
      { number: 31, text: "die Awiter machten Nibhas und Tartak, die Sefarwiter verbrannten ihre Söhne im Feuer* dem Adrammelech und dem Anammelech, den Göttern von Sefarwajim.", footnotes: ["℘ V. 17"] },
      { number: 32, text: "Doch fürchteten sie <auch> den HERRN und machten sich aus ihrer Gesamtheit Höhenpriester, die für sie in den Höhenhäusern opferten*.", footnotes: ["℘ 1Kö 12,31.33"] },
      { number: 33, text: "So fürchteten sie den HERRN und dienten <zugleich> ihren Göttern entsprechend dem Brauch* der Nationen, aus denen man sie gefangen weggeführt hatte*.", footnotes: ["o. der <Gottes>verehrung; o. dem Recht", "℘ V. 41; Mt 6,24"] },
      { number: 34, text: "Bis auf den heutigen Tag tun sie nach den früheren Bräuchen*: Sie fürchten den HERRN nicht*, und sie tun nicht nach ihren Ordnungen und nach ihren Bräuchen*, <auch nicht> nach dem Gesetz und nach dem Gebot, die der HERR den Söhnen Jakobs geboten hatte, dem er den Namen Israel gab*.", footnotes: ["o. Rechtsbestimmungen; o. <Gottes>verehrungen", "℘ Ps 55,20; Spr 14,2", "o. Rechtsbestimmungen; o. <Gottes>verehrungen", "℘ 1Mo 32,29"] },
      { number: 35, text: "Und <doch> hatte der HERR mit ihnen einen Bund geschlossen* und hatte ihnen geboten: Ihr sollt nicht andere Götter fürchten* und euch nicht vor ihnen niederwerfen und sollt ihnen nicht dienen und ihnen nicht opfern*,", footnotes: ["℘ 5Mo 5,2", "℘ Ri 6,10", "℘ 2Mo 20,3.5; Jer 25,6"] },
      { number: 36, text: "sondern den HERRN, der euch mit großer Kraft und mit ausgestrecktem Arm aus dem Land Ägypten heraufgeführt hat*, ihn sollt ihr fürchten, und vor ihm sollt ihr euch niederwerfen und ihm opfern*!", footnotes: ["℘ 2Mo 6,6; 1Kö 8,42", "℘ 5Mo 6,12.14"] },
      { number: 37, text: "Und die Ordnungen und die Bräuche* und das Gesetz und das Gebot, die er für euch aufgeschrieben hat, sollt ihr bewahren, <sie> alle Tage zu tun*, und ihr sollt nicht andere Götter fürchten*!", footnotes: ["o. Rechtsbestimmungen; o. <Gottes>verehrungen", "℘ 5Mo 5,22.29-33", "℘ Ri 6,10"] },
      { number: 38, text: "Und den Bund, den ich mit euch geschlossen habe, sollt ihr nicht vergessen* und sollt nicht andere Götter fürchten*,", footnotes: ["℘ 5Mo 4,23", "℘ Ri 6,10"] },
      { number: 39, text: "sondern den HERRN, euren Gott, sollt ihr fürchten*! Er wird euch retten aus der Hand aller eurer Feinde*.", footnotes: ["℘ 1Sam 12,24", "℘ 1Sam 7,3"] },
      { number: 40, text: "Aber sie hörten nicht, sondern taten nach ihren früheren Bräuchen*.", footnotes: ["o. Rechtsbestimmungen; o. <Gottes>verehrungen"] },
      { number: 41, text: "So fürchteten diese Nationen den HERRN und dienten <zugleich> ihren Götterbildern*, auch ihre Kinder und ihre Kindeskinder. Wie ihre Väter getan haben, so tun <auch> sie bis auf den heutigen Tag*.", footnotes: ["d. i. ein aus Stein gehauenes oder aus Holz geschnitztes Bild", "℘ V. 32.33; 1Kö 18,21; Joh 4,22"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "*Und es geschah im dritten Jahr Hoscheas, des Sohnes Elas, des Königs von Israel*, da wurde Hiskia* König, der Sohn des Ahas, des Königs von Juda*.", heading: "Hiskia von Juda", footnotes: ["℘ 2Chr 29-31", "℘ Kap. 17,1", "℘ 1Chr 3,13; Mt 1,9", "℘ Kap. 16,20"] },
      { number: 2, text: "25 Jahre war er alt, als er König wurde, und er regierte 29 Jahre in Jerusalem; und der Name seiner Mutter war Abi, die Tochter Secharjas." },
      { number: 3, text: "Und er tat, was recht war in den Augen des HERRN*, nach allem, was sein Vater David getan hatte*.", footnotes: ["℘ Kap. 20,3; 5Mo 10,12.20", "℘ Kap. 12,3; 1Kö 15,11; Jes 38,3"] },
      { number: 4, text: "Er beseitigte die Höhen und zertrümmerte die Gedenksteine* und rottete die Aschera aus* und schlug die eherne* Schlange, die Mose gemacht hatte*, in Stücke. Denn bis zu jenen Tagen hatten die Söhne Israel ihr Rauchopfer dargebracht, und man nannte sie Nehuschtan*.", footnotes: ["hebr. mazzebot; das sind aufrecht hingestellte Steine, die kultisch verehrt wurden", "℘ Kap. 11,18; 21,3; 23,14; 5Mo 5,5.25", "w. bronzene", "℘ V. 22; 4Mo 21,8.9", "d. h. Ehernes, w. Bronzenes"] },
      { number: 5, text: "Er vertraute auf den HERRN, den Gott Israels*. Und nach ihm hat es seinesgleichen nicht gegeben unter allen Königen von Juda noch unter denen, die vor ihm waren*.", footnotes: ["℘ V. 19; Kap. 19,10; 2Chr 32,7.8", "℘ Kap. 23,25"] },
      { number: 6, text: "Er hing dem HERRN an, er wich nicht davon ab, ihm nachzufolgen*. Und er bewahrte seine Gebote, die der HERR dem Mose geboten hatte*.", footnotes: ["w. wich nicht ab von <der Nachfolge> hinter ihm her", "℘ Kap. 20,3; 5Mo 10,12.20"] },
      { number: 7, text: "Und der HERR war mit ihm*; in allem, wozu er auszog, hatte er Erfolg*. Und er empörte sich gegen den König von Assur und diente ihm nicht <mehr>*.", footnotes: ["℘ Ri 1,19", "℘ 1Mo 39,2; 1Sam 18,14; 2Sam 8,6; 2Chr 31,21; Ps 1,3", "℘ V. 20; Kap. 16,7; 17,3"] },
      { number: 8, text: "Er schlug die Philister bis nach Gaza* und dessen Gebiet, vom Wachtturm bis zur befestigten Stadt*.", footnotes: ["℘ 5Mo 2,23; Jos 15,47; 1Kö 5,4", "℘ Kap. 17,9"] },
      { number: 9, text: "*Und es geschah im vierten Jahr des Königs Hiskia, das war das siebte Jahr Hoscheas, des Sohnes Elas, des Königs von Israel, da zog Salmanassar, der König von Assur, gegen Samaria herauf und belagerte es.", heading: "Hoschea von Israel — Wegführung nach Assur", footnotes: ["℘ Kap. 17,3-23"] },
      { number: 10, text: "Und am Ende von drei Jahren nahm er es ein. Im sechsten Jahr Hiskias, das war das neunte Jahr Hoscheas, des Königs von Israel, wurde Samaria eingenommen*.", footnotes: ["℘ Jes 10,9; Mi 1,6"] },
      { number: 11, text: "Und der König von Assur führte Israel gefangen nach Assur fort* *und ließ sie in Halach bleiben, am Habor, dem Strom Gosans, und in den Städten Mediens*,", footnotes: ["℘ Kap. 15,29; 23,27", "So lesen die alten Üs.; Mas. T.: und leitete sie nach Halach <weiter>, an den Habor, den Strom Gosans, und in die Städte Mediens", "So lesen die alten Üs.; Mas. T.: und leitete sie nach Halach <weiter>, an den Habor, den Strom Gosans, und in die Städte Mediens\n℘ Neh 9,30"] },
      { number: 12, text: "weil sie auf die Stimme des HERRN, ihres Gottes, nicht gehört* und seinen Bund übertreten hatten, <nämlich> alles, was Mose, der Knecht des HERRN, geboten hatte. Sie haben nicht gehört* und nicht <danach> getan*.", footnotes: ["℘ Ps 81,12-14", "℘ Kap. 20,3; 5Mo 10,12.20", "℘ 5Mo 29,24; 31,16; Hes 11,12; Dan 9,5-11"] },
      { number: 13, text: "*Im vierzehnten Jahr des Königs Hiskia zog Sanherib, der König von Assur, herauf gegen alle befestigten Städte Judas und nahm sie ein*.", heading: "Belagerung Jerusalems durch Assur — Die Hohnreden des Rabschake", footnotes: ["℘ V. 13-16: 2Chr 32,1-8; Jes 36,1", "℘ Jes 7,17; Mi 1,8.9"] },
      { number: 14, text: "Da sandte Hiskia, der König von Juda, zum König von Assur nach Lachisch* und ließ <ihm> sagen: Ich habe unrecht getan, kehre um von mir! Was du mir auferlegst, will ich tragen*. Da legte der König von Assur Hiskia, dem König von Juda, dreihundert Talente Silber und dreißig Talente Gold auf.", footnotes: ["℘ Kap. 14,19", "℘ Kap. 10,5; 1Kö 20,4"] },
      { number: 15, text: "Und Hiskia gab alles Silber, das sich im Haus des HERRN und in den Schatzkammern des Königshauses vorfand*.", footnotes: ["℘ Kap. 16,8"] },
      { number: 16, text: "In dieser Zeit brach Hiskia von den Türflügeln des Tempelraums des HERRN und von den Pfosten, die Hiskia, der König von Juda, überzogen hatte, <das Gold> ab und gab es* dem König von Assur*.", footnotes: ["w. brach Hiskia die Türflügel . . . und die Pfosten ab, die Hiskia . . . überzogen hatte, und gab sie", "℘ Kap. 12,19"] },
      { number: 17, text: "*Aber der König von Assur sandte von Lachisch aus den Tartan* und den Rab-Saris* und den Rabschake* mit einem gewaltigen Heer gegen den König Hiskia nach Jerusalem. Und sie zogen herauf und kamen nach Jerusalem: Sie zogen herauf und kamen und stellten sich an der Wasserleitung des oberen Teiches auf, der* an der Straße des Walkerfeldes <liegt>*.", footnotes: ["℘ V. 17-37: 2Chr 32,9-19; Jes 36,2-22", "Tartan ist der assyrische Titel des Oberfeldherrn.\n℘ Jes 20,1", "d. i. ein hoher Beamter; w. Obereunuch", "d. i. ein assyrischer Würdenträger, wahrscheinlich Mundschenk", "o. die", "℘ Jes 7,3"] },
      { number: 18, text: "Und sie riefen nach dem König. Da gingen zu ihnen hinaus der Palastvorsteher* Eljakim, der Sohn des Hilkija*, und der Schreiber Schebna* und der Berater* Joach, der Sohn Asafs.", footnotes: ["w. der über das Haus <gesetzt> war", "℘ Jes 22,15-20", "℘ Kap. 20,3; 5Mo 10,12.20", "w. der Bekanntmachende\n℘ 2Sam 8,16"] },
      { number: 19, text: "Und der Rabschake sagte zu ihnen: Sagt doch zu Hiskia: So spricht der große König, der König von Assur: Was ist das für ein Vertrauen, mit dem du vertraust?*", footnotes: ["℘ V. 5"] },
      { number: 20, text: "Du sagst: Fürwahr, ein bloßes Wort* ist <schon> Rat und Macht zum Krieg*. Nun, auf wen vertraust du, dass du dich gegen mich empört hast*?", footnotes: ["w. ein Wort der beiden Lippen", "℘ Spr 20,18; Lk 14,31", "℘ V. 7"] },
      { number: 21, text: "Nun, siehe, du vertraust auf diesen geknickten Rohrstab, auf Ägypten, der jedem, der sich auf ihn stützt, in seine Hand dringt und sie durchbohrt. So ist der Pharao, der König von Ägypten, für alle, die auf ihn vertrauen*.", footnotes: ["℘ Jes 30,1-7; Hes 29,6.7"] },
      { number: 22, text: "Wenn ihr aber zu mir sagt: Auf den HERRN, unseren Gott, vertrauen wir! — ist er es nicht, dessen Höhen und Altäre Hiskia beseitigt hat*, als er zu Juda und zu Jerusalem sagte: Vor diesem Altar in Jerusalem sollt ihr euch niederwerfen?* —", footnotes: ["℘ V. 4", "℘ 5Mo 12,5"] },
      { number: 23, text: "Und nun, geh doch mit meinem Herrn, dem König von Assur, eine Wette ein: Ich will dir zweitausend Pferde stellen, wenn du dir <die nötigen> Reiter dafür aufstellen kannst!" },
      { number: 24, text: "Doch wie willst du <auch nur> einen einzigen <Provinz>statthalter zurücktreiben*, einen von den geringsten Knechten* meines Herrn? Aber du vertraust auf Ägypten wegen der Wagen und Pferde*!", footnotes: ["℘ 1Kö 20,10", "w. Wie willst du das Gesicht eines einzigen <Provinz>statthalters abwenden, <eines> von den kleinen Knechten", "℘ Jes 30,1-7; Hes 29,6.7"] },
      { number: 25, text: "Nun, bin ich etwa ohne den HERRN gegen diesen Ort heraufgezogen, um ihn zu verheeren? Der HERR hat zu mir gesagt: Zieh hinauf gegen dieses Land und verheere es!*", footnotes: ["℘ Jes 10,5.6"] },
      { number: 26, text: "Da sagten Eljakim, der Sohn Hilkijas, und Schebna und Joach zum Rabschake: Rede doch zu deinen Knechten aramäisch*! Denn wir verstehen es. Und rede nicht judäisch mit uns vor den Ohren des Volkes, das auf der Mauer ist!", footnotes: ["℘ Esr 4,7"] },
      { number: 27, text: "Doch der Rabschake sagte zu ihnen: Hat mich mein Herr <etwa nur> zu deinem Herrn und zu dir gesandt, um diese Worte zu reden, <und> nicht zu den Männern, die auf der Mauer sitzen, um mit euch ihren Kot zu essen und ihren Harn zu trinken?*", footnotes: ["℘ Kla 4,4.5"] },
      { number: 28, text: "Und der Rabschake trat hin und rief mit lauter Stimme auf Judäisch und redete und sprach: Hört das Wort des großen Königs, des Königs von Assur!" },
      { number: 29, text: "So spricht der König: Hiskia täusche euch nicht! Denn er kann euch nicht aus meiner Hand* retten*.", footnotes: ["so mit den allermeisten hebr. Handschr. und den alten Üs.; Mas. T.: aus seiner Hand", "℘ Ps 73,8.9"] },
      { number: 30, text: "Und Hiskia vertröste euch nicht auf den HERRN, indem er sagt: Der HERR wird uns gewiss retten; diese Stadt wird nicht in die Hand des Königs von Assur gegeben werden*.", footnotes: ["℘ Kap. 19,10; Ps 3,3; 42,4.11"] },
      { number: 31, text: "Hört nicht auf Hiskia! Denn so spricht der König von Assur: Macht Frieden* mit mir und kommt zu mir heraus! Dann soll jeder von seinem Weinstock und jeder von seinem Feigenbaum essen* und jeder das Wasser seiner Zisterne trinken,", footnotes: ["w. Segen", "℘ 1Kö 5,5"] },
      { number: 32, text: "bis ich komme und euch in ein Land hole wie euer Land, ein Land von Korn und Most, ein Land von Brot und Weinbergen, ein Land von Olivenöl und Honig*. Dann sollt ihr am Leben bleiben und nicht sterben. Aber hört nicht auf Hiskia, wenn er euch verführt, indem er sagt: Der HERR wird uns retten*!", footnotes: ["℘ 4Mo 14,8; 5Mo 8,7-9", "℘ Kap. 19,10; Ps 3,3; 42,4.11"] },
      { number: 33, text: "Haben etwa die Götter der Nationen jeder sein Land aus der Hand des Königs von Assur gerettet*?", footnotes: ["℘ Kap. 19,12"] },
      { number: 34, text: "Wo sind die Götter von Hamat und Arpad*? Wo die Götter von Sefarwajim, von Hena und Awa*?* Haben sie etwa Samaria aus meiner Hand gerettet*?", footnotes: ["℘ Jer 49,23", "Eine LXX-Ausgabe liest: Wo sind die Götter des Landes Samaria", "℘ Kap. 17,24; 19,13", "℘ Kap. 17,6"] },
      { number: 35, text: "Welche sind es unter allen Göttern der Länder, die ihr Land aus meiner Hand gerettet haben, dass der HERR Jerusalem aus meiner Hand retten sollte*?", footnotes: ["℘ Kap. 19,11.17-19; 2Mo 5,2; Dan 3,15"] },
      { number: 36, text: "Da schwieg das Volk still und antwortete ihm kein Wort; denn das war der Befehl des Königs: Ihr sollt ihm nicht antworten*!", footnotes: ["℘ Pred 3,7; Am 5,13"] },
      { number: 37, text: "Und Eljakim, der Sohn des Hilkija, der Palastvorsteher*, und der Schreiber Schebna und der Berater* Joach, der Sohn Asafs, kamen mit zerrissenen Kleidern zu Hiskia und berichteten ihm die Worte des Rabschake.", footnotes: ["w. der über das Haus <gesetzt> war", "w. der Bekanntmachende"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "*Und es geschah, als der König Hiskia es hörte, zerriss er seine Kleider, hüllte sich in Sacktuch* und ging in das Haus des HERRN.", heading: "Die Weissagung des Jesaja — Brief des Königs von Assur — Hiskias Gebet und Gottes Antwort durch Jesaja — Abzug des Königs von Assur", footnotes: ["℘ 2Chr 32,20-23; Jes 37", "℘ 1Mo 37,34; 1Kö 21,27; Jon 3,5"] },
      { number: 2, text: "Dann sandte er Eljakim, den Palastvorsteher*, und den Schreiber Schebna und die Ältesten der Priester, in Sacktuch gehüllt, zum Propheten Jesaja, dem Sohn des Amoz*.", footnotes: ["w. der über das Haus <gesetzt> war", "℘ 2Chr 26,22"] },
      { number: 3, text: "Und sie sagten zu ihm: So spricht Hiskia: Ein Tag der Bedrängnis und der Züchtigung und der Schmähung ist dieser Tag*! Denn die Kinder sind bis an den Muttermund gekommen, aber da ist keine Kraft zu gebären*.", footnotes: ["℘ Ps 123,3.4", "℘ Hos 13,13"] },
      { number: 4, text: "Vielleicht hört der HERR, dein Gott, alle Worte des Rabschake, den sein Herr, der König von Assur, gesandt hat, um den lebendigen Gott* zu verhöhnen*, und bestraft <ihn> wegen der Worte, die der HERR, dein Gott, gehört hat*. Erhebe doch ein Gebet für den Rest, der sich <noch> findet!*", footnotes: ["℘ Jos 3,10", "℘ V. 16.23; 1Sam 17,10.26", "℘ Neh 3,36; Ps 74,18", "℘ V. 31"] },
      { number: 5, text: "So kamen die Knechte des Königs Hiskia zu Jesaja." },
      { number: 6, text: "Und Jesaja sagte zu ihnen: So sollt ihr zu eurem Herrn sagen: So spricht der HERR: Fürchte dich nicht vor den Worten, die du gehört hast, mit denen die Diener des Königs von Assur mich gelästert haben*!", footnotes: ["℘ Kap. 18,30-35; Jes 10,24; Kla 3,57"] },
      { number: 7, text: "Siehe, ich will ihm einen Geist eingeben, dass er ein Gerücht hören und in sein Land zurückkehren wird*; dann will ich ihn in seinem Land durchs Schwert fällen*.", footnotes: ["℘ V. 28; Kap. 7,6", "℘ V. 35-37; Ps 94,23"] },
      { number: 8, text: "Und der Rabschake kehrte zurück und fand den König von Assur im Kampf gegen Libna*; denn er hatte gehört, dass er von Lachisch aufgebrochen war.", footnotes: ["℘ Jos 10,29"] },
      { number: 9, text: "Der <König> hatte nämlich über Tirhaka, den König von Kusch*, sagen hören: Siehe, er ist ausgezogen, um gegen dich zu kämpfen. Da sandte er wieder Boten zu Hiskia und ließ <ihm> sagen:", footnotes: ["℘ Jes 18,1"] },
      { number: 10, text: "So sollt ihr zu Hiskia, dem König von Juda, sagen: Dein Gott täusche dich nicht, auf den du vertraust, indem du sagst: Jerusalem wird nicht in die Hand des Königs von Assur gegeben werden*!", footnotes: ["℘ Kap. 18,5.30"] },
      { number: 11, text: "Siehe, du hast gehört, was die Könige von Assur allen Ländern getan haben, indem sie an ihnen den Bann vollstreckten. Und du solltest gerettet werden*?", footnotes: ["℘ Kap. 15,29; 18,35; 2Chr 32,17"] },
      { number: 12, text: "Haben die Götter der Nationen, die meine Väter vernichtet haben, sie gerettet: Gosan, Haran* und Rezef und die Söhne Edens*, die in Telassar waren?*", footnotes: ["℘ 1Mo 11,31.32", "℘ Hes 27,23", "℘ Kap. 18,33.34"] },
      { number: 13, text: "Wo ist der König von Hamat* und der König von Arpad und der König der Stadt Sefarwajim, <von> Hena und Awa?*", footnotes: ["℘ 2Chr 8,3", "℘ Kap. 18,33.34"] },
      { number: 14, text: "Da nahm Hiskia den Brief* aus der Hand der Boten und las ihn. Dann ging er ins Haus des HERRN hinauf, und Hiskia breitete ihn vor dem HERRN aus*.", footnotes: ["w. die Briefe", "℘ 1Sam 8,21; Ps 62,9; Jer 11,20"] },
      { number: 15, text: "Und Hiskia betete vor dem HERRN: HERR, Gott Israels, der du über den Cherubim thronst*, du bist es, der da Gott ist, du allein für alle Königreiche der Erde. Du hast den Himmel und die Erde gemacht*.", footnotes: ["℘ 2Mo 25,22", "℘ 1Mo 1,1; Ps 102,26; Jer 32,17"] },
      { number: 16, text: "Neige, HERR, dein Ohr und höre! Tu, HERR, deine Augen auf und sieh!* Ja, höre die Worte Sanheribs, die er gesandt hat, um den lebendigen Gott zu verhöhnen*.", footnotes: ["℘ 1Kö 8,29; Dan 9,18", "℘ V. 4; Ps 74,22"] },
      { number: 17, text: "Es ist wahr, HERR, die Könige von Assur haben die Nationen und ihr Land in Trümmer gelegt*,", footnotes: ["℘ Kap. 18,33.35"] },
      { number: 18, text: "und ihre Götter haben sie ins Feuer geworfen*; denn sie waren nicht Götter, sondern ein Werk von Menschenhänden, Holz und Stein*, und sie haben sie verloren gegeben.", footnotes: ["℘ Kap. 10,26", "℘ Ps 115,4-8; Jer 16,20"] },
      { number: 19, text: "Und nun, HERR, unser Gott, rette uns doch aus seiner Hand, damit alle Königreiche der Erde erkennen, dass du, HERR, allein Gott bist!*", footnotes: ["℘ Kap. 5,15; 2Mo 7,17; 1Kö 18,36.37; Ps 83,19"] },
      { number: 20, text: "Da sandte Jesaja, der Sohn des Amoz, zu Hiskia und ließ <ihm> sagen: So spricht der HERR, der Gott Israels: Was du wegen Sanheribs des Königs von Assur, zu mir gebetet hast, habe ich gehört*.", footnotes: ["℘ Kap. 20,5; Ps 65,3; Jes 65,24; Dan 9,23; 1Jo 3,21.22"] },
      { number: 21, text: "Dies ist das Wort, das der HERR über ihn geredet hat: Es verachtet dich, es verspottet dich die Jungfrau, die Tochter Zion; die Tochter Jerusalem schüttelt das Haupt hinter dir her." },
      { number: 22, text: "Wen hast du gehöhnt und gelästert und gegen wen die Stimme erhoben? Gegen den Heiligen Israels hast du deine Augen emporgerichtet*!", footnotes: ["℘ Jes 10,13"] },
      { number: 23, text: "Durch deine Boten hast du den Herrn verhöhnt* und hast gesagt: Mit der Menge meiner Wagen* habe ich die Höhe der Berge erstiegen, das äußerste Ende des Libanon; und ich haue den Hochwald seiner Zedern um, die Auslese seiner Wacholderbäume, und ich komme in seine fernste Herberge, in das Dickicht seines Baumbestandes*.", footnotes: ["℘ V. 4; Nah 2,14", "℘ Ps 20,8", "℘ Jes 10,13"] },
      { number: 24, text: "Ich habe gegraben und fremdes Wasser getrunken; und mit der Sohle meiner Füße trockne ich alle Ströme* Mazors* aus*.", footnotes: ["d. i. eine stehende Bezeichnung für die Arme und Kanäle des Nil", "Mazor ist ein anderes Wort für Ägypten; nach einigen speziell für Unterägypten.", "℘ Jes 19,6"] },
      { number: 25, text: "Hast du nicht gehört, dass ich lange vorher* es gewirkt und von den Tagen der Vorzeit her es gebildet habe*? Nun habe ich es kommen lassen*, dass du befestigte Städte verwüstest zu öden Steinhaufen.", footnotes: ["o. von fern her", "o. es geplant habe\n℘ Jes 45,7.21", "℘ Ps 33,11"] },
      { number: 26, text: "Und ihre Bewohner waren machtlos*, sie wurden mit Schrecken erfüllt und zuschanden; sie waren <wie> Kraut des Feldes und grünes Gras, <wie> Gras auf den Dächern, das vor dem Ostwind verdorrt*.", footnotes: ["w. ihre Bewohner hatten eine <zu> kurze Hand", "so mit Qu.; Mas. T.: Gras auf den Dächern und <wie> das Verdorren vor dem Getreide<, das auf dem Halm steht>"] },
      { number: 27, text: "Dein Sitzen und dein Aus- und Eingehen kenne ich, ja, dein Toben gegen mich*.", footnotes: ["℘ Ps 139,1-3"] },
      { number: 28, text: "Wegen deines Tobens gegen mich und weil dein Übermut in meine Ohren heraufgekommen ist, werde ich meinen Ring in deine Nase legen und meinen Zaum an deine Lippen* und werde dich zurückführen auf dem Weg, auf dem du gekommen bist*. —", footnotes: ["℘ Hes 38,4", "℘ V. 7"] },
      { number: 29, text: "Und dies soll dir* das Zeichen sein*: Man wird in diesem Jahr den Nachwuchs <der Ernte> essen und im zweiten Jahr den Wildwuchs. Im dritten Jahr aber sollt ihr säen und ernten und Weinberge pflanzen und ihre Frucht essen*.", footnotes: ["d. h. Hiskia", "℘ Kap. 20,9; Jes 7,11; Lk 2,12", "℘ 3Mo 25,6.22"] },
      { number: 30, text: "Und das, was vom Haus Juda entkommen, was übrig geblieben ist, wird wieder wurzeln nach unten und Frucht tragen nach oben." },
      { number: 31, text: "Denn von Jerusalem wird ein Rest ausgehen* und das Entkommene vom Berg Zion*. Der Eifer des HERRN der Heerscharen wird das tun*.", footnotes: ["℘ Jes 10,20-22", "℘ V. 4", "℘ Joe 2,18"] },
      { number: 32, text: "Darum, so spricht der HERR über den König von Assur: Er wird nicht in diese Stadt kommen, und er wird keinen Pfeil hineinschießen und ihr nicht mit dem Schild entgegentreten und wird keinen Wall gegen sie aufschütten." },
      { number: 33, text: "Auf dem Weg, den er gekommen ist, auf ihm wird er zurückkehren* und wird nicht in diese Stadt kommen, spricht der HERR*.", footnotes: ["℘ V. 7", "w. ist der Ausspruch des HERRN\n℘ Spr 21,1"] },
      { number: 34, text: "Denn ich will diese Stadt beschirmen*, um sie zu retten, um meinetwillen* und um meines Knechtes David willen*.", footnotes: ["℘ Ps 46,6; Jes 31,5; Sach 9,8", "℘ Hes 36,22", "℘ Kap. 8,19; 20,6; Hos 1,7"] },
      { number: 35, text: "Und es geschah in dieser Nacht, da zog ein Engel des HERRN aus und schlug im Lager von Assur 185 000 Mann. Und als man früh am Morgen aufstand, siehe, da <fand man> sie alle, lauter Leichen*.", footnotes: ["℘ 2Mo 9,16; 2Chr 20,24; Ps 76,6.7; Jes 17,14"] },
      { number: 36, text: "Und Sanherib, der König von Assur, brach auf, zog fort und kehrte zurück; und er blieb in Ninive*.", footnotes: ["℘ Nah 1,1.2"] },
      { number: 37, text: "Und es geschah, als er sich im Haus seines Gottes Nisroch niederwarf, da erschlugen ihn seine Söhne Adrammelech und Sarezer mit dem Schwert*; und sie entkamen in das Land Ararat*. Und sein Sohn Asarhaddon wurde an seiner Stelle König*.", footnotes: ["℘ V. 7", "℘ 1Mo 8,4", "℘ Esr 4,2"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "*In jenen Tagen wurde Hiskia todkrank. Und der Prophet Jesaja, der Sohn des Amoz, kam zu ihm und sagte zu ihm: So spricht der HERR: Bestelle dein Haus*! Denn du wirst sterben* und nicht am Leben bleiben.", heading: "Hiskias Krankheit und Genesung", footnotes: ["℘ 2Chr 32,24; Jes 38,1-8", "℘ 2Sam 17,23", "℘ Kap. 1,16; 5Mo 31,14"] },
      { number: 2, text: "Da wandte er sein Gesicht zur Wand und betete zu dem HERRN*. Und er sprach:", footnotes: ["℘ Ps 50,15; Jak 5,13"] },
      { number: 3, text: "Ach, HERR! Denke doch daran*, dass ich vor deinem Angesicht in Treue* und mit ungeteiltem Herzen gelebt* und dass ich getan habe, was gut ist in deinen Augen*! Und Hiskia weinte sehr*.", footnotes: ["℘ Neh 13,14", "o. in Wahrheit", "w. hin- und hergegangen bin", "℘ Kap. 18,3-6; 1Kö 3,6; 8,23; 2Chr 31,20; Hi 4,6; Apg 24,16", "℘ Hi 16,20; Ps 6,7; 39,13; Am 5,4"] },
      { number: 4, text: "Und es geschah — Jesaja war <noch> nicht aus der inneren Stadt* hinausgegangen —, da geschah das Wort des HERRN zu ihm:", footnotes: ["Einige hebr. Handschr., die Masoreten und die alten Üs. lesen: aus dem inneren Vorhof"] },
      { number: 5, text: "Kehre um und sage zu Hiskia, dem Fürsten meines Volkes: So spricht der HERR, der Gott deines Vaters David*: Ich habe dein Gebet gehört*, ich habe deine Tränen gesehen*. Siehe, ich will dich heilen*; am dritten Tag wirst du ins Haus des HERRN hinaufgehen.", footnotes: ["℘ 2Chr 34,3", "℘ Kap. 19,20; 22,19; 2Mo 3,7.9; 1Kö 9,3; Ps 6,10; 34,18; 119,26", "℘ Ps 56,9", "℘ 5Mo 32,39; Ps 107,20; Mk 1,41"] },
      { number: 6, text: "Und ich will zu deinen Tagen fünfzehn Jahre hinzufügen. Und aus der Hand des Königs von Assur will ich dich und diese Stadt retten; und ich will diese Stadt beschirmen um meinetwillen und um meines Knechtes David willen*.", footnotes: ["℘ Kap. 19,34"] },
      { number: 7, text: "Und Jesaja sagte: Bringt einen Feigenkuchen! Und sie brachten ihn und legten ihn auf das Geschwür. Da genas er." },
      { number: 8, text: "Und Hiskia sagte zu Jesaja: Was ist das Zeichen, dass der HERR mich heilen wird und dass ich am dritten Tag in das Haus des HERRN hinaufgehen werde*?", footnotes: ["℘ 1Mo 15,8"] },
      { number: 9, text: "Jesaja sagte: Dies wird dir das Zeichen vom HERRN sein*, dass der HERR das Wort, das* er geredet hat, tun wird: Soll der Schatten <an der Sonnenuhr> zehn Stufen vorwärtsgehen*, oder soll er zehn Stufen zurückgehen?", footnotes: ["℘ Kap. 19,29; 1Sam 14,10", "o. die Sache, von der", "℘ Jos 10,12.13"] },
      { number: 10, text: "Da sagte Hiskia: Es ist dem Schatten ein Leichtes, sich <an der Sonnenuhr> um zehn Stufen zu neigen*; nein, sondern der Schatten soll zehn Stufen rückwärtsgehen.", footnotes: ["℘ Jos 10,12.13"] },
      { number: 11, text: "Da rief der Prophet Jesaja zu dem HERRN. Und er ließ den Schatten um <so viele> Stufen <der Sonnenuhr> zurückgehen, wie die Sonne* an den Stufen <der Sonnenuhr> des Ahas hinabgegangen war, zehn Stufen zurück.", footnotes: ["w. die sie; vgl. Jes 38,8"] },
      { number: 12, text: "*In jener Zeit sandte Merodach-Baladan*, der Sohn Baladans, der König von Babel, Brief und Geschenk an Hiskia; denn er hatte gehört, dass Hiskia krank gewesen war.", heading: "Gesandtschaft aus Babel bei Hiskia — Sein Tod", footnotes: ["℘ 2Chr 32,25-33; Jes 39", "so mit Jes 39,1; Mas. T.: Berodach-Baladan"] },
      { number: 13, text: "Und Hiskia freute sich über sie* und zeigte ihnen* sein ganzes Schatzhaus: das Silber und Gold, die Balsamöle und das köstliche Öl und sein ganzes Vorratshaus und alles, was sich in seinen Schatzkammern vorfand. Es gab nichts in seinem Haus und in seiner ganzen Herrschaft, das Hiskia ihnen nicht gezeigt hätte*.", footnotes: ["so mit einigen hebr. Handschr., LXX, Vulg. und der syr. Üs.; Mas. T.: Und Hiskia hörte auf sie", "d. i. den Boten", "℘ Ps 62,11; Jer 9,22; 1Kor 4,7"] },
      { number: 14, text: "Da kam der Prophet Jesaja zum König Hiskia und sprach zu ihm: Was haben diese Männer gesagt, und woher sind sie zu dir gekommen*? Da sagte Hiskia: Aus einem fernen Land sind sie gekommen, aus Babel.", footnotes: ["℘ 4Mo 22,9"] },
      { number: 15, text: "Er sprach: Was haben sie in deinem Haus gesehen? Und Hiskia sagte: Sie haben alles gesehen, was in meinem Haus ist. Es gibt nichts in meinen Schatzkammern, das ich ihnen nicht gezeigt hätte*.", footnotes: ["℘ Ps 62,11; Jer 9,22; 1Kor 4,7"] },
      { number: 16, text: "Da sprach Jesaja zu Hiskia: Höre das Wort des HERRN!*", footnotes: ["℘ 1Sam 9,27"] },
      { number: 17, text: "Siehe, Tage kommen, da wird alles, was in deinem Haus ist und was deine Väter bis zum heutigen Tag angehäuft haben, nach Babel weggebracht werden*. Nichts wird übrig bleiben, spricht der HERR.", footnotes: ["℘ Kap. 24,13; 2Chr 36,18; Jer 20,5"] },
      { number: 18, text: "Und von deinen Söhnen, die von dir abstammen, die du zeugen wirst, wird man <einige> nehmen*; und sie werden im Palast des Königs von Babel Hofbeamte* sein.", footnotes: ["℘ Kap. 24,12.15; 2Chr 33,11; Dan 1,3.4", "w. Eunuchen"] },
      { number: 19, text: "Da sagte Hiskia zu Jesaja: Das Wort des HERRN ist gut, das du geredet hast*. Aber er sagte <sich>: Wenn doch nur Friede und Sicherheit in meinen Tagen bleiben!*", footnotes: ["℘ 1Kö 2,38", "℘ Kap. 22,20; 1Kö 11,12"] },
      { number: 20, text: "Und die übrige Geschichte* Hiskias und all seine Machttaten und wie er den Teich und die Wasserleitung gemacht und das Wasser in die Stadt geleitet hat*, ist das nicht geschrieben im Buch der Geschichte* der Könige von Juda*?", footnotes: ["w. der Rest der Begebenheiten", "℘ 2Chr 32,3.4.30; Neh 2,14; Jes 22,11", "w. der Begebenheiten der Tage", "℘ Kap. 8,23; 1Kö 14,29"] },
      { number: 21, text: "Und Hiskia legte sich zu seinen Vätern. Und sein Sohn Manasse* wurde an seiner Stelle König*.", footnotes: ["℘ 1Chr 3,13; Mt 1,10", "℘ Kap. 21,1"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "*Zwölf Jahre war Manasse alt, als er König wurde*, und er regierte 55 Jahre in Jerusalem; und der Name seiner Mutter war Hefzi-Bah.", heading: "Manasse von Juda — Sein Götzendienst", footnotes: ["℘ 2Chr 33,1-20", "℘ Kap. 20,21"] },
      { number: 2, text: "Und er tat, was böse war in den Augen des HERRN*, nach den Gräueln der Nationen, die der HERR vor den Söhnen Israel vertrieben hatte*.", footnotes: ["℘ V. 16.20; Kap. 17,2", "℘ Kap. 16,3; Hes 11,12; 22,3"] },
      { number: 3, text: "Und er baute die Höhen wieder auf, die sein Vater Hiskia vernichtet hatte*, und errichtete Altäre für den Baal und machte eine Aschera, wie <sie> Ahab, der König von Israel, gemacht hatte, und er warf sich nieder vor dem ganzen Heer des Himmels und diente ihnen*.", footnotes: ["℘ Kap. 13,6; 18,4", "℘ Kap. 17,16; 5Mo 17,3; Jes 65,11"] },
      { number: 4, text: "Und er baute Altäre im Haus des HERRN*, von dem der HERR gesagt hatte: In Jerusalem will ich meinen Namen niederlegen*.", footnotes: ["℘ Jer 32,34", "℘ Kap. 16,11; 23,27; 2Sam 7,13; 1Kö 8,29; 2Chr 6,6.9; Jer 7,30"] },
      { number: 5, text: "Und er baute für das ganze Heer des Himmels Altäre in den beiden Vorhöfen des Hauses des HERRN*.", footnotes: ["℘ Kap. 23,12; 2Chr 4,9; Hes 8,16"] },
      { number: 6, text: "Und er ließ seinen Sohn durchs Feuer gehen*, und er trieb Zauberei und Beschwörung und ließ sich mit Totengeistern und Wahrsagegeistern* ein*. Er tat vieles, was böse war in den Augen des HERRN, um ihn zu reizen*.", footnotes: ["℘ Kap. 16,3; 23,24; Jer 19,5; Hes 23,39", "o. mit Totenbeschwörern und Wahrsagern; o. und Wissenden", "℘ Kap. 17,17", "℘ 5Mo 32,16"] },
      { number: 7, text: "Und er stellte das Götterbild der Aschera*, das er gemacht hatte, in das Haus*, von dem der HERR zu David und zu seinem Sohn Salomo gesagt hatte: In diesem Haus und in Jerusalem, das ich aus allen Stämmen Israels erwählt habe, will ich meinen Namen für ewig niederlegen*!", footnotes: ["d. i. ein geschnitztes o. in Stein gehauenes Götzenbild, das kultisch verehrt wurde", "℘ Kap. 23,6; 5Mo 16,21; Ps 78,58", "℘ Kap. 16,11; 23,27; 2Sam 7,13; 1Kö 8,29; 2Chr 6,6.9; Jer 7,30"] },
      { number: 8, text: "Und ich will den Fuß Israels nicht mehr aus dem Land vertreiben, das ich ihren Vätern gegeben habe, wenn sie nur darauf achten, nach allem zu tun, was ich ihnen geboten habe, und nach dem ganzen Gesetz, das mein Knecht Mose ihnen geboten hat*.", footnotes: ["℘ 2Sam 7,10"] },
      { number: 9, text: "Aber sie hörten nicht*, und Manasse verführte sie, mehr Böses zu tun als die Nationen, die der HERR vor den Söhnen Israel ausgerottet hatte*.", footnotes: ["℘ 1Sam 8,19", "℘ Kap. 16,3; Hes 11,12; 22,3"] },
      { number: 10, text: "Da redete der HERR durch seine Knechte, die Propheten*, und sprach:", footnotes: ["℘ Kap. 17,13"] },
      { number: 11, text: "Weil Manasse, der König von Juda, diese Gräuel verübt <und> Schlimmes getan hat* — mehr als alles, was die Amoriter getan haben*, die vor ihm gewesen sind — und auch Juda durch seine Götzen* zur Sünde verführt hat,", footnotes: ["℘ Kap. 23,26; Jer 15,4; Hes 5,6", "℘ 1Kö 21,26", "w. Klötze, o. Mistkugeln"] },
      { number: 12, text: "darum, so spricht der HERR, der Gott Israels, siehe, will ich Unheil über Jerusalem und Juda bringen, dass jedem, der es hört, die beiden Ohren gellen sollen*.", footnotes: ["℘ 1Sam 3,11; Jer 19,3"] },
      { number: 13, text: "Und ich werde über Jerusalem die Messschnur Samarias spannen* und die Waage des Hauses Ahabs*, und ich werde Jerusalem auswischen, wie man eine Schüssel auswischt: Man wischt <sie> aus und dreht <sie> um auf ihre Oberseite.", footnotes: ["℘ Kap. 9,8; 17,6; Kla 2,8; Hes 23,31", "℘ 1Kö 21,21; Jes 34,11; Am 7,7.8"] },
      { number: 14, text: "Und ich werde den Rest meines Erbteils verstoßen* und werde sie in die Hand ihrer Feinde geben, und sie werden allen ihren Feinden zum Raub und zur Plünderung werden*,", footnotes: ["℘ Kap. 17,19.20; Jer 12,7", "℘ Ps 74,1; Jer 19,7"] },
      { number: 15, text: "weil sie getan haben, was böse ist in meinen Augen, und mich zum Zorn gereizt haben, von dem Tag an, als ihre Väter aus Ägypten gezogen sind, bis auf den heutigen Tag*.", footnotes: ["℘ Jes 24,5; Jer 15,4; Kla 1,5; Dan 9,5-8"] },
      { number: 16, text: "Manasse vergoss auch sehr viel unschuldiges Blut*, bis er Jerusalem damit anfüllte von einem Ende bis zum andern*; abgesehen von seiner Sünde, mit der er Juda zur Sünde verführte*, zu tun, was böse war in den Augen des HERRN.*", footnotes: ["℘ Hes 23,45", "℘ Kap. 24,3.4; Spr 6,16.17; Jer 2,34; Hes 22,2", "℘ Kap. 3,3; 1Kö 14,16", "℘ V. 2"] },
      { number: 17, text: "Und die übrige Geschichte* Manasses und alles, was er getan, und seine Sünde, die er begangen hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Juda*?", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ Kap. 8,23; 1Kö 14,29"] },
      { number: 18, text: "Und Manasse legte sich zu seinen Vätern und wurde begraben im Garten seines Hauses, im Garten des Usa*. Und sein Sohn Amon* wurde an seiner Stelle König*.", footnotes: ["℘ V. 26", "℘ 1Chr 3,14; Mt 1,10", "℘ V. 19"] },
      { number: 19, text: "*22 Jahre war Amon alt, als er König wurde*, und er regierte zwei Jahre in Jerusalem; und der Name seiner Mutter war Meschullemet, die Tochter des Haruz aus Jotba.", heading: "Amon von Juda", footnotes: ["℘ 2Chr 33,21-25", "℘ V. 18"] },
      { number: 20, text: "Und er tat, was böse war in den Augen des HERRN, wie sein Vater Manasse getan hatte*.", footnotes: ["℘ V. 2; Kap. 23,32.37; 24,9.19; 3Jo 11"] },
      { number: 21, text: "Und er ging ganz den Weg, den sein Vater gegangen war, und diente den Götzen, denen sein Vater gedient hatte*, und warf sich vor ihnen nieder.", footnotes: ["℘ V. 2; Kap. 23,32.37; 24,9.19; 3Jo 11"] },
      { number: 22, text: "Und er verließ den HERRN, den Gott seiner Väter*, und ging nicht auf dem Weg des HERRN*.", footnotes: ["℘ Kap. 22,17", "℘ 1Kö 11,33; Jes 1,2.4"] },
      { number: 23, text: "Und die Knechte Amons verschworen sich gegen ihn und töteten den König in seinem Haus*.", footnotes: ["℘ Kap. 9,27"] },
      { number: 24, text: "Das Volk des Landes aber erschlug alle, die sich gegen den König Amon verschworen hatten*; und das Volk des Landes machte seinen Sohn Josia an seiner Stelle zum König*.", footnotes: ["℘ Kap. 14,5", "℘ Kap. 22,1; Mt 1,10"] },
      { number: 25, text: "Und die übrige Geschichte* Amons, was er getan hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Juda*?", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ Kap. 8,23; 1Kö 14,29"] },
      { number: 26, text: "Und man begrub ihn in seinem Begräbnis im Garten Usas*. Und sein Sohn Josia* wurde an seiner Stelle König*.", footnotes: ["℘ V. 18", "℘ 1Chr 3,14; Zef 1,1", "℘ Kap. 22,1; Mt 1,10"] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "*Acht Jahre war Josia alt, als er König wurde*, und er regierte 31 Jahre in Jerusalem; und der Name seiner Mutter war Jedida, die Tochter Adajas aus Bozkat*.", heading: "Josia von Juda: Fund des Gesetzbuches", footnotes: ["℘ V. 1-7: 2Chr 34,1-13", "℘ Kap. 21,24.26", "℘ Jos 15,39"] },
      { number: 2, text: "Und er tat, was recht war in den Augen des HERRN. Er ging ganz den Weg seines Vaters David* und wich nicht zur Rechten noch zur Linken ab*.", footnotes: ["℘ Kap. 12,3; 1Kö 15,11", "℘ 5Mo 5,32; Hes 18,14"] },
      { number: 3, text: "Und es geschah im achtzehnten Jahr des Königs Josia*, da sandte der König den Schreiber Schafan*, den Sohn Azaljas, des Sohnes Meschullams, ins Haus des HERRN und sagte:", footnotes: ["℘ Kap. 23,23", "℘ Jer 36,10"] },
      { number: 4, text: "*Geh hinauf zum Hohenpriester Hilkija*, dass er das Geld ausschütte*, das in das Haus des HERRN gebracht worden ist, das die <Priester, die> an der Schwelle wachen, vom Volk eingesammelt haben,", footnotes: ["℘ V. 4-7: vgl. Kap. 12,5-16", "℘ 1Chr 5,39", "So liest die aram. Üs.; Mas. T.: dass er das Geld fertig mache"] },
      { number: 5, text: "damit man es in die Hand der Werkführer gebe, die am Haus des HERRN eingesetzt sind. Die sollen es den Werkmeistern geben, die im Haus des HERRN sind, um die Risse des Hauses auszubessern," },
      { number: 6, text: "den Handwerkern und den Bauleuten und den Maurern, und zum Ankauf von Holz und behauenen Steinen*, das Haus auszubessern.", footnotes: ["o. Bruchsteinen"] },
      { number: 7, text: "Doch soll das Geld, das in ihre Hand gegeben wird, nicht mit ihnen abgerechnet werden, denn sie handeln gewissenhaft*.", footnotes: ["o. sondern man soll auf Treu und Glauben handeln; w. denn in Treue handeln sie"] },
      { number: 8, text: "*Und der Hohepriester Hilkija sagte zu Schafan, dem Schreiber: Ich habe im Haus des HERRN das Buch des Gesetzes* gefunden*. Und Hilkija gab das Buch dem Schafan, und der las es.", footnotes: ["℘ V. 8-20: 2Chr 34,14-28", "℘ 5Mo 31,24-26", "℘ Kap. 23,2"] },
      { number: 9, text: "Und der Schreiber Schafan kam zum König und brachte dem König Nachricht und sagte: Deine Knechte haben das Geld, das sich im Haus vorfand, ausgeschüttet und es in die Hand der Werkführer gegeben, die am Haus des HERRN eingesetzt sind." },
      { number: 10, text: "Und der Schreiber Schafan berichtete dem König weiter: Der Priester Hilkija hat mir ein Buch gegeben. Und Schafan las es dem König vor*.", footnotes: ["℘ 5Mo 17,19; Jer 36,21"] },
      { number: 11, text: "Und es geschah, als der König die Worte des Buches des Gesetzes hörte, da zerriss er seine Kleider*.", footnotes: ["℘ Ps 119,120; Jes 66,2; Jer 36,16.24; Röm 3,20; Hebr 4,12"] },
      { number: 12, text: "Und der König befahl dem Priester Hilkija und Ahikam, dem Sohn Schafans, und Achbor*, dem Sohn Michajas, und Schafan*, dem Schreiber, und Asaja, dem Knecht des Königs, und sagte:", footnotes: ["℘ Jer 26,22", "℘ Kap. 25,22; Jer 26,24"] },
      { number: 13, text: "Geht hin, befragt den HERRN für mich und für das Volk und für ganz Juda* wegen der Worte dieses aufgefundenen Buches! Denn groß ist der Zorn des HERRN, der sich gegen uns entzündet hat*, dafür, dass unsere Väter auf die Worte dieses Buches nicht gehört haben, nach allem zu tun, was unsertwegen aufgeschrieben ist*.", footnotes: ["℘ Jer 21,1.2", "℘ Kap. 23,26; Ps 76,8; Jer 36,7", "℘ 3Mo 26,14-39; 5Mo 27,26"] },
      { number: 14, text: "Da gingen der Priester Hilkija und Ahikam und Achbor und Schafan und Asaja zu der Prophetin* Hulda, der Frau des Schallum, des Sohnes Tikwas, des Sohnes des Harhas, des Hüters der Kleider; sie wohnte aber in Jerusalem im zweiten Stadtteil*; und sie redeten mit ihr.", footnotes: ["℘ 2Mo 15,20", "d. i. die Neustadt von Jerusalem"] },
      { number: 15, text: "Und sie sagte zu ihnen: So spricht der HERR, der Gott Israels: Sagt dem Mann, der euch zu mir gesandt hat:" },
      { number: 16, text: "So spricht der HERR: Siehe, ich will Unheil über diesen Ort bringen und über seine Bewohner: alle Worte des Buches*, das der König von Juda gelesen hat.", footnotes: ["℘ Kap. 24,2; 1Sam 3,19; Dan 9,12-14"] },
      { number: 17, text: "Weil sie mich verlassen* und anderen Göttern Rauchopfer dargebracht haben, um mich zum Zorn zu reizen mit all dem Machwerk ihrer Hände, so wird mein Zorn sich gegen diesen Ort entzünden und wird nicht erlöschen*.", footnotes: ["℘ Kap. 21,22; Jer 2,13; 22,9", "℘ 5Mo 32,21-23; 1Kö 9,6-9; 2Chr 28,25; Jer 7,20; Sach 1,2"] },
      { number: 18, text: "Zu dem König von Juda aber, der euch gesandt hat, um den HERRN zu befragen, zu ihm sollt ihr so sagen: So spricht der HERR, der Gott Israels: <Was> die Worte, die du gehört hast, <betrifft> —" },
      { number: 19, text: "weil dein Herz weich geworden ist* und du dich vor dem HERRN gedemütigt hast*, als du hörtest, was ich über diesen Ort und über seine Bewohner geredet habe, dass sie zum Entsetzen und zum Fluch werden sollen*, und du deine Kleider zerrissen und vor mir geweint hast*, darum habe auch ich gehört, spricht der HERR*.", footnotes: ["℘ Ps 51,19", "℘ 1Kö 21,29; 2Chr 32,26; Jak 4,10", "℘ Jer 26,6", "℘ Neh 1,4", "w. ist der Ausspruch des HERRN\n℘ Kap. 20,5"] },
      { number: 20, text: "Darum, siehe, ich werde dich zu deinen Vätern versammeln; und du wirst zu deinen Gräbern versammelt werden in Frieden, und deine Augen sollen all das Unheil nicht ansehen, das ich über diesen Ort kommen lasse*. Und sie brachten dem König die Antwort.", footnotes: ["℘ Kap. 20,19; Jes 57,1.2; Mt 5,4"] },
    ]},
    { number: 23, verses: [
      { number: 1, text: "*Und der König sandte hin, und man versammelte zu ihm alle Ältesten von Juda und von Jerusalem*.", heading: "Josias Reformen: Bundeserneuerung, Abschaffung des Götzendienstes, Passahfeier — Sein Tod im Krieg gegen die Ägypter", footnotes: ["℘ 2Chr 34,29-33", "℘ 5Mo 31,38; Jos 24,1"] },
      { number: 2, text: "Und der König ging ins Haus des HERRN hinauf und alle Männer von Juda und alle Einwohner von Jerusalem mit ihm und die Priester und die Propheten und alles Volk, vom Kleinsten bis zum Größten. Und man las vor ihren Ohren alle Worte des Bundesbuches, das im Haus des HERRN gefunden worden war*.", footnotes: ["℘ Kap. 22,8.10; 5Mo 31,11; Neh 8,1.8"] },
      { number: 3, text: "Und der König stand auf dem <erhöhten> Standort* und schloss den Bund vor dem HERRN*, dem HERRN nachzufolgen und seine Gebote und seine Zeugnisse* und seine Ordnungen zu bewahren mit ganzem Herzen und mit ganzer Seele, um die Worte dieses Bundes zu erfüllen, die in diesem Buch aufgeschrieben sind. Und das ganze Volk trat in den Bund ein*.", footnotes: ["℘ Kap. 11,14", "℘ Kap. 11,17", "o. Mahnungen", "℘ 2Chr 15,12-15; Neh 5,13; 10,1.29.30; Jer 34,15"] },
      { number: 4, text: "Und der König befahl dem Hohenpriester Hilkija und den Priestern zweiten Ranges und den Hütern der Schwelle*, aus dem Tempelraum des HERRN alle Geräte hinauszubringen, die für den Baal und die Aschera und das ganze Heer des Himmels gemacht worden waren*. Dann verbrannte er sie außerhalb Jerusalems in den Terrassen<gärten> am Kidron* und ließ ihren Staub nach Bethel bringen*.", footnotes: ["℘ Kap. 12,10", "℘ Kap. 21,3-7", "℘ Kap. 10,26; 1Kö 15,13; 2Chr 15,16", "℘ V. 15; Apg 19,19"] },
      { number: 5, text: "Und er machte den Götzenpriestern ein Ende, die die Könige von Juda eingesetzt hatten und die auf den Höhen, in den Städten von Juda und in der Umgebung von Jerusalem Rauchopfer darbrachten* und die, die dem Baal, der Sonne und dem Mond und dem Tierkreisbild und dem ganzen Heer des Himmels Rauchopfer darbrachten.", footnotes: ["℘ Zef 1,4"] },
      { number: 6, text: "Und er brachte die Aschera aus dem Haus des HERRN hinaus* nach draußen vor Jerusalem in das Bachtal des Kidron*; und er verbrannte sie im Bachtal des Kidron und zermalmte sie zu Staub und warf ihren Staub auf die Gräber der Söhne des Volkes*.", footnotes: ["℘ Kap. 21,7", "℘ Kap. 10,26; 1Kö 15,13; 2Chr 15,16", "℘ 2Chr 34,4"] },
      { number: 7, text: "Und er riss die Häuser der Tempelhurer* nieder, die <sich> im Haus des HERRN <befanden>, in denen die Frauen Gewänder* für die Aschera webten.", footnotes: ["℘ 4Mo 25,1-3; 1Kö 14,24; Hos 4,13", "T. in Anlehnung an mehrere LXX-Handschr.; Mas. T.: Häuser (= Zelte?)"] },
      { number: 8, text: "Und er ließ alle Priester aus den Städten Judas kommen und machte die Höhen unrein, wo die Priester Rauchopfer dargebracht hatten, von Geba* bis Beerscheba*. Und er riss die Höhen der Dämonen* nieder, die am Eingang des Tores Joschuas, des Obersten der Stadt, waren, auf der linken Seite, wenn man zum Stadttor hineinkommt*.", footnotes: ["℘ Jos 18,24", "℘ Am 5,5", "T.; Mas. T.: er riss die Höhen der Tore nieder", "So lesen LXX und die aram. Üs.; Mas. T.: auf der linken Seite jemandes<, der> ins Tor <kommt>"] },
      { number: 9, text: "Doch durften die Priester der Höhen nicht auf dem Altar des HERRN in Jerusalem opfern, sondern <nur noch> vom ungesäuerten Brot inmitten ihrer Brüder essen*.", footnotes: ["℘ 1Sam 2,36"] },
      { number: 10, text: "Und er machte das Tofet* unrein, das im Tal Ben-Hinnoms <lag>*, damit niemand mehr seinen Sohn oder seine Tochter dem Moloch durchs Feuer gehen ließ*.", footnotes: ["w. Gespei, o. Gräuel; daher auch Gräuelstätte\n℘ Jes 30,33; Jer 7,31", "℘ Jos 15,8; 2Chr 28,3; Neh 11,30", "℘ Kap. 16,3; Hes 23,37"] },
      { number: 11, text: "Und er schaffte die Pferde ab, die die Könige von Juda der Sonne <zu Ehren> aufgestellt hatten am Eingang des Hauses des HERRN*, bei der Zelle Netan-Melechs, des Hofbeamten*, die im Parwarim* war*, und die Sonnenwagen verbrannte er mit Feuer*.", footnotes: ["So lesen LXX, Vulg. und die syr. Üs.; Mas. T.: er schaffte es ab, dass die Pferde . . . in das Haus des HERRN kamen", "w. des Eunuchen", "d. i. wahrscheinlich ein an der Westseite des äußeren Tempelvorhofs gelegener Anbau", "℘ 1Chr 26,18", "℘ Hes 8,16"] },
      { number: 12, text: "Und die Altäre, die auf dem Dach des Obergemachs des Ahas waren, die die Könige von Juda gemacht hatten*, und die Altäre, die Manasse in den beiden Vorhöfen des Hauses des HERRN gemacht hatte*, riss der König nieder und zertrümmerte <sie>*, und er warf ihren Staub ins Bachtal des Kidron*.", footnotes: ["℘ Jer 19,13; Zef 1,4.5", "℘ Kap. 21,4.5", "w. zertrümmerte <sie> von dort hinweg; möglich ist auch: und er eilte von dort weg", "℘ Kap. 10,26; 1Kö 15,13; 2Chr 15,16"] },
      { number: 13, text: "Und der König machte die Höhen unrein, die vor* Jerusalem zur Rechten des Berges des Verderbens* waren, die Salomo, der König von Israel, für Astarte, das Scheusal der Sidonier, und Kemosch, das Scheusal Moabs, und Milkom, den Gräuel der Söhne Ammon, gebaut hatte*.", footnotes: ["d. i. östlich von", "Die syr. Üs. und Vulg. üs.: Berg des Ärgernisses. — Im Hebr. klingen »Verderben« und »Salbung« ganz ähnlich; deshalb liegt hier eine Anspielung auf den Ölberg nahe.", "℘ 1Kö 11,5.7"] },
      { number: 14, text: "Und er zertrümmerte die Gedenksteine* und hieb die Ascherim um* und füllte ihre Stätte mit Menschenknochen.", footnotes: ["hebr. mazzebot; das sind aufrecht hingestellte Steine, die kultisch verehrt wurden", "℘ Kap. 18,4; 5Mo 7,5; Jes 27,9"] },
      { number: 15, text: "Auch den Altar, der in Bethel war, die Höhe, die Jerobeam, der Sohn des Nebat, gemacht hatte, der Israel zur Sünde verführt hatte*, auch diesen Altar und die Höhe riss er nieder*; und er verbrannte die Höhe, <und> die Aschera zermalmte er zu Staub* und verbrannte <sie>.", footnotes: ["℘ Kap. 3,3; 1Kö 14,16", "℘ 1Sam 7,3.4", "℘ V. 4"] },
      { number: 16, text: "Und als Josia sich umwandte und die Gräber sah, die dort in dem Berg waren, da sandte er hin und ließ die Gebeine aus den Gräbern holen, verbrannte sie auf dem Altar und machte ihn <auf diese Weise> unrein nach dem Wort des HERRN, das der Mann Gottes ausgerufen hatte, der diese Dinge <damals> ausrief*.", footnotes: ["℘ 1Kö 13,2"] },
      { number: 17, text: "Und er sagte: Was ist das da für ein Steinmal, das ich sehe? Und die Männer der Stadt sagten zu ihm: <Es ist> das Grab des Mannes Gottes, der von Juda gekommen ist und diese Dinge, die du getan hast, über den Altar von Bethel ausgerufen hat." },
      { number: 18, text: "Da sagte er: Lasst ihn liegen, niemand soll seine Gebeine bewegen! Und so retteten sie seine Gebeine zusammen mit den Gebeinen des Propheten, der aus Samaria gekommen war*.", footnotes: ["℘ 1Kö 13,29-32"] },
      { number: 19, text: "Auch alle Häuser der Höhen, die in den Städten Samarias waren, die die Könige von Israel gemacht hatten, um <den HERRN> zum Zorn zu reizen, beseitigte Josia. Er verfuhr mit ihnen genauso, wie er <es> in Bethel vollzogen hatte*.", footnotes: ["℘ 2Chr 34,6.7"] },
      { number: 20, text: "Und alle Priester der Höhen, die dort waren*, schlachtete er auf den Altären und verbrannte Menschenknochen darauf. Dann kehrte er nach Jerusalem zurück.", footnotes: ["℘ Kap. 10,25; 11,18; 2Mo 22,19"] },
      { number: 21, text: "*Und der König befahl dem ganzen Volk: Feiert dem HERRN, eurem Gott, ein Passah, wie in diesem Buch des Bundes geschrieben steht*!", footnotes: ["℘ V. 21-30: 2Chr 35", "℘ 2Mo 12,11"] },
      { number: 22, text: "Denn es war kein Passah gefeiert worden wie dieses von den Tagen der Richter an, die Israel gerichtet hatten, und alle Tage der Könige von Israel und der Könige von Juda*,", footnotes: ["℘ 2Chr 30,1.2"] },
      { number: 23, text: "sondern <erst> im achtzehnten Jahr des Königs Josia* wurde dieses Passah dem HERRN in Jerusalem gefeiert.", footnotes: ["℘ Kap. 22,3"] },
      { number: 24, text: "Und auch die Totenbeschwörer und die Wahrsager* und die Terafim* und die Götzen und alle Scheusale, die im Land Juda und in Jerusalem zu sehen waren, schaffte Josia ab*, um die Worte des Gesetzes* auszuführen, die in dem Buch geschrieben standen, das der Priester Hilkija im Haus des HERRN gefunden hatte*.", footnotes: ["w. die Wissenden\n℘ Kap. 21,6", "das sind Hausgötzen\n℘ 1Mo 31,19", "o. fegte Josia hinaus", "o. der Weisung", "℘ 5Mo 18,10-12"] },
      { number: 25, text: "Vor Josia* gab es keinen König wie ihn, der zu dem HERRN umgekehrt wäre mit seinem ganzen Herzen und mit seiner ganzen Seele* und mit seiner ganzen Kraft* nach dem ganzen Gesetz des Mose*. Und <auch> nach ihm ist seinesgleichen nicht aufgestanden*.", footnotes: ["w. Vor ihm", "o. Person", "℘ 5Mo 6,5; 1Kö 8,48; Lk 10,27", "℘ Neh 10,30", "℘ Kap. 18,5; Jer 22,15"] },
      { number: 26, text: "Doch kehrte sich der HERR nicht ab von der großen Glut seines Zornes, mit der sein Zorn gegen Juda entbrannt war, wegen all der Kränkungen, mit denen Manasse ihn gekränkt hatte*.", footnotes: ["℘ Kap. 21,11.12; 22,13; 24,3.4"] },
      { number: 27, text: "So hatte der HERR gesagt: Auch Juda will ich von meinem Angesicht entfernen, wie ich Israel entfernt habe*; und ich will diese Stadt verwerfen, die ich erwählt habe, Jerusalem, und das Haus, von dem ich gesagt habe: Mein Name soll dort sein*!", footnotes: ["℘ Kap. 17,18-20; 18,11; 25,21; Jer 23,33.39", "℘ Kap. 21,4.7"] },
      { number: 28, text: "Und die übrige Geschichte* Josias und alles, was er getan hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Juda?*", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ Kap. 8,23; 1Kö 14,29"] },
      { number: 29, text: "In seinen Tagen zog der Pharao Necho, der König von Ägypten, zum König von Assur hinauf an den Strom Euphrat*. Und der König Josia zog ihm entgegen; aber Necho* tötete ihn bei Megiddo*, als er ihn sah.", footnotes: ["℘ Jer 46,2", "w. er", "℘ Ri 1,27"] },
      { number: 30, text: "Und seine Knechte führten ihn auf einem Wagen tot von Megiddo fort und brachten ihn nach Jerusalem und begruben ihn in seinem Begräbnis. Und das Volk des Landes nahm Joahas, den Sohn Josias*, und sie salbten ihn und machten ihn zum König anstelle seines Vaters.", footnotes: ["℘ Jer 22,10.11"] },
      { number: 31, text: "*23 Jahre war Joahas alt, als er König wurde, und er regierte drei Monate in Jerusalem; und der Name seiner Mutter war Hamutal, die Tochter Jirmejas aus Libna*.", heading: "Joahas von Juda", footnotes: ["℘ 2Chr 36,1-4", "℘ Kap. 24,18"] },
      { number: 32, text: "Und er tat, was böse war in den Augen des HERRN, nach allem, was seine Väter getan hatten*.", footnotes: ["℘ Kap. 21,20"] },
      { number: 33, text: "Und der Pharao Necho setzte ihn in Ribla im Land Hamat* gefangen, so dass er nicht mehr in Jerusalem König war*. Und er legte dem Land eine Geldbuße von hundert Talenten Silber und einem Talent Gold auf.", footnotes: ["℘ Kap. 25,6.21; 4Mo 34,11", "so mit der Leseform des Mas. T., LXX und Vulg.; mit der Schreibform: als er in Jerusalem König war"] },
      { number: 34, text: "Und der Pharao Necho machte Eljakim, den Sohn Josias, zum König anstelle seines Vaters Josia und änderte seinen Namen in Jojakim*. Joahas aber nahm er <mit sich>, und er kam nach Ägypten und starb dort*.", footnotes: ["℘ Kap. 24,17; 1Chr 3,15; Jer 1,3", "℘ Jer 22,11.12; Hes 19,3-9"] },
      { number: 35, text: "Und das Silber und das Gold gab Jojakim dem Pharao. Doch musste er das Land schätzen, um das Geld nach dem Befehl des Pharao abzuliefern; vom Volk des Landes, von jedem nach seiner Schätzung, trieb er das Silber und das Gold ein, um es dem Pharao Necho abzuliefern*.", footnotes: ["℘ Kap. 15,20"] },
      { number: 36, text: "*25 Jahre war Jojakim alt, als er König wurde*, und er regierte elf Jahre in Jerusalem, und der Name seiner Mutter war Sebuda, die Tochter Pedajas aus Ruma.", heading: "Jojakim von Juda", footnotes: ["℘ 2Chr 36,5-8", "℘ Dan 1,1"] },
      { number: 37, text: "Und er tat, was böse war in den Augen des HERRN, nach allem, was seine Väter getan hatten*.", footnotes: ["℘ Kap. 21,20; Jer 26,20-23"] },
    ]},
    { number: 24, verses: [
      { number: 1, text: "In seinen Tagen zog Nebukadnezar, der König von Babel, herauf*, und Jojakim war drei Jahre sein Knecht, dann wandte er sich <wieder ab> und empörte sich gegen ihn*.", footnotes: ["℘ Jer 25,1; Dan 1,1", "℘ V. 20; Esr 4,12"] },
      { number: 2, text: "Und der HERR sandte gegen ihn Streifscharen der Chaldäer und Streifscharen Arams und Streifscharen Moabs und Streifscharen der Söhne Ammon. Er sandte sie gegen Juda, um es zugrunde zu richten nach dem Wort des HERRN, das er durch seine Knechte, die Propheten, geredet hatte*.", footnotes: ["℘ Kap. 22,16; Jer 25,9; 35,11; Kla 1,17; Hes 19,8; Hab 1,6"] },
      { number: 3, text: "Ja, nach dem Befehl des HERRN geschah das gegen Juda, um es von seinem Angesicht zu entfernen* wegen der Sünden Manasses, nach allem, was er getan hatte;", footnotes: ["℘ V. 20; Kap. 17,18.20.23"] },
      { number: 4, text: "auch wegen des unschuldigen Blutes, das er vergossen hatte, so dass er Jerusalem mit unschuldigem Blut angefüllt hatte*. Das wollte der HERR nicht vergeben*.", footnotes: ["℘ Kap. 21,16; 23,26; Ps 106,38; Spr 6,17; Jer 22,17; Hes 22,3", "℘ 4Mo 35,33; 5Mo 29,19; Hes 24,8"] },
      { number: 5, text: "Und die übrige Geschichte* Jojakims und alles, was er getan hat, ist das nicht geschrieben im Buch der Geschichte* der Könige von Juda?*", footnotes: ["w. der Rest der Begebenheiten", "w. der Begebenheiten der Tage", "℘ Kap. 8,23; 1Kö 14,29"] },
      { number: 6, text: "Und Jojakim legte sich zu seinen Vätern. Und sein Sohn Jojachin* wurde an seiner Stelle König.", footnotes: ["℘ Mt 1,11"] },
      { number: 7, text: "Doch der König von Ägypten zog fortan nicht mehr aus seinem Land. Denn der König von Babel hatte von dem Bach Ägyptens an bis zum Strom Euphrat alles genommen, was dem König von Ägypten gehört hatte*.", footnotes: ["℘ Jer 37,5.7; 46,2-6; Hes 30,21"] },
      { number: 8, text: "*Achtzehn Jahre war Jojachin* alt, als er König wurde, und er regierte drei Monate in Jerusalem; und der Name seiner Mutter war Nehuschta, die Tochter Elnatans aus Jerusalem.", heading: "Jojachin von Juda — Erste Eroberung Jerusalems und erste Wegführung nach Babel", footnotes: ["℘ 2Chr 36,9.10; Jer 22,24-30", "℘ 1Chr 3,16"] },
      { number: 9, text: "Und er tat, was böse war in den Augen des HERRN, nach allem, was sein Vater getan hatte*.", footnotes: ["℘ Kap. 21,20"] },
      { number: 10, text: "In jener Zeit zogen die Knechte Nebukadnezars, des Königs von Babel, nach Jerusalem herauf, und die Stadt kam in Belagerung." },
      { number: 11, text: "Und Nebukadnezar, der König von Babel, ging <selbst> gegen die Stadt vor, während seine Knechte sie belagerten." },
      { number: 12, text: "Und Jojachin, der König von Juda, ging zum König von Babel hinaus, er und seine Mutter und seine Knechte und seine Obersten und seine Hofbeamten*. Und der König von Babel nahm ihn gefangen* im achten Jahr seiner Königsherrschaft*.", footnotes: ["w. Eunuchen\n℘ Kap. 20,18; Est 2,5.6", "℘ Jer 29,2; Hes 1,2", "℘ Kap. 25,8"] },
      { number: 13, text: "Und er brachte von dort heraus alle Schätze des Hauses des HERRN und die Schätze des Königshauses und brach <das Gold von> allen goldenen Geräten ab, die Salomo, der König von Israel, im Tempel des HERRN gemacht hatte*, ganz wie der HERR geredet hatte*.", footnotes: ["℘ Dan 5,2.3", "℘ Kap. 20,17; Jer 20,5; Hes 23,26"] },
      { number: 14, text: "Und er führte ganz Jerusalem gefangen fort und alle Obersten und alle kriegstüchtigen <Männer>, zehntausend Gefangene, und alle Schmiede und Schlosser*. Niemand blieb übrig als nur das geringe Volk des Landes*.", footnotes: ["℘ Kap. 25,12.21; 1Chr 9,1; Jer 52,28; Hes 17,3.4", "℘ Kap. 25,12"] },
      { number: 15, text: "Und er führte Jojachin gefangen fort nach Babel. Und die Mutter des Königs und die Frauen des Königs und seine Hofbeamten* und die Bürgerschaft des Landes führte er als Gefangene* aus Jerusalem nach Babel*.", footnotes: ["w. Eunuchen\n℘ Kap. 25,12.21; 1Chr 9,1; Jer 52,28; Hes 17,3.4", "w. Weggeführte", "℘ Kap. 25,12.21; 1Chr 9,1; Jer 52,28; Hes 17,3.4"] },
      { number: 16, text: "Und alle Kriegsmänner, 7 000, und die Schmiede und die Schlosser, 1 000, alles tüchtige*, kampferprobte Männer, die brachte der König von Babel als Gefangene* nach Babel*.", footnotes: ["o. angesehene; o. vermögende", "w. Weggeführte", "℘ Kap. 25,12.21; 1Chr 9,1; Jer 52,28; Hes 17,3.4"] },
      { number: 17, text: "Und der König von Babel machte Mattanja, Jojachins* Onkel an seiner Stelle zum König und änderte seinen Namen* in Zedekia*.", footnotes: ["w. seinen", "℘ Kap. 23,34; Dan 1,7", "℘ 1Chr 3,15; Jer 37,1"] },
      { number: 18, text: "*21 Jahre war Zedekia alt, als er König wurde, und er regierte elf Jahre in Jerusalem; und der Name seiner Mutter war Hamutal, die Tochter Jirmejas aus Libna*.", heading: "Zedekia, letzter König von Juda — Belagerung Jerusalems — Flucht und Gefangennahme des Königs", footnotes: ["℘ 2Chr 36,11-16; Jer 52,1-11", "℘ Kap. 23,31"] },
      { number: 19, text: "Und er tat, was böse war in den Augen des HERRN, nach allem, was Jojakim getan hatte*.", footnotes: ["℘ Kap. 21,20"] },
      { number: 20, text: "Denn wegen des Zornes des HERRN kam es in Jerusalem und in Juda dahin, dass er sie von seinem Angesicht verwarf*. Und Zedekia empörte sich gegen den König von Babel*.", footnotes: ["℘ V. 3; Hes 19,14", "℘ V. 1; Hes 17,12-19"] },
    ]},
    { number: 25, verses: [
      { number: 1, text: "*Und es geschah im neunten Jahr seiner Regierung, im zehnten Monat, am Zehnten des Monats, da kam Nebukadnezar, der König von Babel, er und sein ganzes Heer, gegen Jerusalem und belagerte es*; und sie bauten Belagerungstürme gegen es ringsumher*.", footnotes: ["℘ V. 1-7: Jer 39,1-7", "℘ V. 8; Jer 34,1.7; Hes 24,2", "℘ Jer 32,2.24"] },
      { number: 2, text: "So kam die Stadt in Belagerung* bis ins elfte Jahr des Königs Zedekia.", footnotes: ["℘ 5Mo 28,52"] },
      { number: 3, text: "Am Neunten des <vierten> Monats, als der Hunger in der Stadt überhandgenommen hatte und kein Brot <mehr> da war für das Volk des Landes*,", footnotes: ["℘ Jes 3,1; Jer 19,9; Kla 4,4-10; Hes 4,16.17"] },
      { number: 4, text: "da wurde die Stadt<mauer> aufgebrochen, und alle Kriegsleute <flohen> nachts auf dem Weg durch das Tor, das zwischen den beiden Mauern beim Garten des Königs <lag> — die Chaldäer aber waren rings um die Stadt her —, und der König* zog den Weg zur Steppe*.", footnotes: ["w. er", "hebr. Araba; vgl. Anm. zu 5Mo 1,1"] },
      { number: 5, text: "Aber das Heer der Chaldäer jagte dem König* nach, und sie holten ihn ein in den Steppen* von Jericho; und sein ganzes Heer zerstreute sich von ihm weg.", footnotes: ["℘ Jes 30,16", "hebr. Araba; vgl. Anm. zu 5Mo 1,1"] },
      { number: 6, text: "Und sie ergriffen den König und führten ihn hinauf zum König von Babel nach Ribla*; und man sprach das Urteil über ihn.", footnotes: ["℘ Kap. 23,33"] },
      { number: 7, text: "Und man schlachtete die Söhne Zedekias vor seinen Augen ab; und man blendete die Augen Zedekias und band ihn mit ehernen Fesseln* und brachte ihn nach Babel*.", footnotes: ["w. bronzenen Doppelfesseln\n℘ Ri 16,21", "℘ Jes 22,3; Jer 21,7; 37,17; Kla 2,9; Hes 12,11"] },
      { number: 8, text: "*Und im fünften Monat, am Siebten des Monats, das war das neunzehnte Jahr des Königs Nebukadnezar*, des Königs von Babel, kam Nebusaradan, der Oberste der Leibwache, der Knecht des Königs von Babel, nach Jerusalem*.", heading: "Zerstörung Jerusalems und des Tempels — Zweite Wegführung nach Babel", footnotes: ["℘ 2Chr 36,17-21; Jer 52,12-27; V. 8-12: Jer 39,8-10", "℘ Kap. 24,12", "℘ V. 1; Kla 4,12"] },
      { number: 9, text: "Und er verbrannte das Haus des HERRN* und das Haus des Königs; und alle Häuser Jerusalems und jedes große Haus verbrannte er mit Feuer*.", footnotes: ["℘ 1Kö 9,7-9; Ps 74,3; 79,1; Jes 64,9; Kla 2,7; 5,18", "℘ Esr 5,12; Jer 34,22; Hes 10,2; Am 2,5"] },
      { number: 10, text: "Und das ganze Heer der Chaldäer, das bei dem Obersten der Leibwache war, riss die Mauern von Jerusalem ringsum nieder*.", footnotes: ["℘ 5Mo 28,51; Neh 1,3"] },
      { number: 11, text: "Und den Rest des Volkes, die in der Stadt Übriggebliebenen und die Überläufer, die zum König von Babel übergelaufen waren, und den Rest der Menge führte Nebusaradan, der Oberste der Leibwache, gefangen fort*.", footnotes: ["℘ Hes 12,11"] },
      { number: 12, text: "Aber von den Geringen des Landes ließ der Oberste der Leibwache <einige> zurück als Weingärtner und als Ackerleute*.", footnotes: ["℘ Kap. 24,14-16; Neh 1,2; Jes 24,6"] },
      { number: 13, text: "Und die bronzenen Säulen, die am Haus des HERRN waren, und die Gestelle und das bronzene Meer, die im Haus des HERRN waren*, zerschlugen die Chaldäer und nahmen die Bronze davon mit nach Babel.", footnotes: ["℘ 1Kö 7,15-37; Jer 20,5"] },
      { number: 14, text: "Und die Töpfe und die Schaufeln und die Messer und die Schalen und alle bronzenen Geräte, mit denen man den Dienst verrichtete*, nahmen sie mit.", footnotes: ["℘ 1Kö 7,40.45"] },
      { number: 15, text: "Auch die Feuerbecken* und die Sprengschalen*, was aus reinem Gold und was aus reinem Silber war*, nahm der Oberste der Leibwache mit*,", footnotes: ["Das sind Gefäße zur Aufbewahrung oder zum Transport brennender Kohlen.", "℘ 1Kö 7,40.45", "o. die ganz aus Gold und die ganz aus Silber waren\n℘ 1Kö 7,48-51; 2Chr 24,14", "℘ Dan 5,2.3; Esr 1,9-11"] },
      { number: 16, text: "<ferner> die beiden Säulen, das eine Meer und die Gestelle, die Salomo für das Haus des HERRN gemacht hatte. Die Bronze aller dieser Geräte war nicht zu wiegen*.", footnotes: ["℘ 1Kö 7,47"] },
      { number: 17, text: "Achtzehn Ellen war die Höhe der einen Säule, und ein Kapitell aus Bronze war darauf, und die Höhe des Kapitells <betrug> drei Ellen, und Flechtwerk und Granatäpfel waren an dem Kapitell ringsum, alles aus Bronze; und genauso war es an der anderen Säule mit dem Flechtwerk*.", footnotes: ["℘ 1Kö 7,15-22"] },
      { number: 18, text: "Und der Oberste der Leibwache nahm den Oberpriester* Seraja* und Zefanja, den zweiten Priester*, und die drei, die an der Schwelle Wache hielten;", footnotes: ["o. den ersten Priester", "℘ 1Chr 5,40.41; Esr 7,1", "℘ Jer 21,1; Sach 6,10"] },
      { number: 19, text: "und aus der Stadt nahm er einen Hofbeamten*, der über die Kriegsleute eingesetzt war, und fünf Männer von denen, die ständig um den König waren*, die sich in der Stadt fanden, und den Schreiber des Heerobersten, der das Volk des Landes zum Heer<esdienst> aushob, und sechzig Mann vom Volk des Landes, die sich in der Stadt fanden.", footnotes: ["w. Eunuchen", "w. die das Gesicht des Königs sahen"] },
      { number: 20, text: "Und Nebusaradan, der Oberste der Leibwache, nahm sie und brachte sie zum König von Babel nach Ribla." },
      { number: 21, text: "*Und der König von Babel erschlug sie und tötete sie in Ribla im Land Hamat*. — So wurde Juda aus seinem Land gefangen weggeführt*.", footnotes: ["℘ V. 21-26: Jer 40-43", "℘ Kap. 23,27.33; Kla 4,16", "℘ Kap. 17,23; 24,15; 5Mo 29,27; 1Kö 8,46; 1Chr 5,41; Jer 16,13"] },
      { number: 22, text: "*Und <was> das Volk <betrifft>, das im Land Juda übrig geblieben war, das Nebukadnezar, der König von Babel, übrig gelassen hatte, über sie setzte er Gedalja, den Sohn Ahikams, des Sohnes Schafans* <als Statthalter> ein.", heading: "Statthalter Gedalja", footnotes: ["℘ V. 22-24: Jer 40,7-9; 41,1-7; 43,5-7", "℘ Kap. 22,12; Jer 41,18"] },
      { number: 23, text: "Und als alle Heerobersten, sie und ihre Männer, hörten, dass der König von Babel Gedalja <als Statthalter> eingesetzt habe, da kamen sie zu Gedalja nach Mizpa*; nämlich Ismael, der Sohn des Netanja, und Johanan, der Sohn des Kareach, und Seraja, der Sohn des Tanhumet, der Netofatiter, und Jaasanja, der Sohn des Maachatiters, sie und ihre Männer.", footnotes: ["℘ Jos 18,26"] },
      { number: 24, text: "Und Gedalja schwor ihnen und ihren Männern und sagte zu ihnen: Fürchtet euch nicht vor den Knechten der Chaldäer!* Bleibt im Land und dient dem König von Babel! Dann wird es euch gut gehen.", footnotes: ["Vulg. liest mit Jer 40,9: Fürchtet euch nicht, den Chaldäern zu dienen!"] },
      { number: 25, text: "Es geschah aber im siebten Monat, da kam Ismael, der Sohn Netanjas, des Sohnes Elischamas, <einer> von den königlichen Nachkommen, und zehn Männer mit ihm; und sie erschlugen Gedalja, so dass er starb, sowie die Judäer und die Chaldäer, die bei ihm in Mizpa waren*.", footnotes: ["℘ Jer 41,1-3; Sach 7,5; 8,19"] },
      { number: 26, text: "Da machte sich alles Volk, vom Kleinsten bis zum Größten, mit den Heerobersten auf, und sie kamen nach Ägypten*; denn sie fürchteten sich vor den Chaldäern.", footnotes: ["℘ Jer 43,4.7"] },
      { number: 27, text: "*Und es geschah im 37. Jahr der Wegführung Jojachins, des Königs von Juda, im zwölften Monat, am 27. des Monats, da erhob Ewil-Merodach, der König von Babel, in dem Jahr, als er König wurde, das Haupt* Jojachins, des Königs von Juda, <und führte ihn> aus dem Gefängnis.", heading: "Jojachins Begnadigung", footnotes: ["℘ Jer 52,31-34", "℘ 1Mo 40,13"] },
      { number: 28, text: "Und er redete gütig mit ihm und setzte seinen Thron über den Thron der Könige*, die bei ihm in Babel waren*.", footnotes: ["o. und wies ihm seinen Sitz oberhalb des Sitzes der Könige an", "℘ Dan 5,19"] },
      { number: 29, text: "Und Jojachin* durfte seine Gefängniskleidung ablegen*. Und er aß beständig vor ihm alle Tage seines Lebens*.", footnotes: ["w. er", "℘ 1Mo 41,14", "℘ 1Kö 2,7; Jer 22,26"] },
      { number: 30, text: "Und sein Unterhalt, ein beständiger Unterhalt, wurde ihm, soviel er täglich nötig hatte*, vom König gegeben alle Tage seines Lebens*.", footnotes: ["w. das Tägliche an seinem Tage", "℘ 1Kö 2,7; Jer 22,26"] },
    ]},
  ]
};
